// The match itself: two athletes across the net — one against the CPU, two
// people sharing the screen, or a co-op pair of them against two CPUs — the
// usual best of three, or the MARATHON of
// five sets at 11 points a set; a set is first to its target, ends swap
// between sets — and the BLITZ, three minutes on the clock against the CPU:
// one running score, no sets, one swap of ends at half time, the horn
// deciding it and sudden death when the scores sit level. A SERIES toggle on
// the title turns plain VS CPU play into a best-of-three of full matches: a
// series pill beside the score carries the session's running tally, whoever
// lost the previous match serves the next one fresh, the second series win
// lifts a brief SERIES WON card over the court, and the second loss hands
// the series over. Each
// match draws a court theme at random — or, for the plain matches, plays the
// venue picked on the title screen, which overrides the draw while the cup,
// the daily and the ladder keep theirs: midday sun, sunset, a floodlit night,
// or the floodlit indoor arena — a real volleyball hall of gym walls, LED
// boards, a hung scoreboard and a polished floor that mirrors the play
// standing on it. Arcade volleyball. The ball flies on honest
// ballistic physics — gravity,
// net blocks, out-of-bounds landings — and each athlete bumps it automatically
// the moment it comes within reach. Aiming is the skill: drag on the left of
// the screen to move and steer where the ball goes, and hold jump to rise while
// the power meter fills — in the air every contact spikes flat and hard
// exactly as the CPU's does, the meter buying extra pace on top, while a
// light tap from the sand lobs high over a net-hugging CPU and a held charge
// plays the rally pass, obeying the drag more strongly — and on the team's
// second touch a light strike tap becomes the hand set instead: a soft
// overhead pop that hangs high just this side of the net, the CPU partner in
// doubles reading it and running onto the set to swing, and the co-op
// ownership call naming whoever takes the ball next so nobody collides —
// and swiping the drag across the flight at contact bends the shot with
// sidespin, a faint curve hint on the aim arrow naming the break, while a
// late, low contact digs up backspin that sits a float down short. The
// arrow itself plays the breeze too: drawn against the live wind, its tip
// leans toward where the drift will actually put the ball down — and
// straightens again under the arena roof, where the air never moves.
// Serving is in the player's hands too: a tap of jump tosses the ball up, and
// a strike timed at the top of the toss with a charged meter flies flat and
// fast, while one struck on the way down floats high and slow — drop the toss
// and the point is gone. The practice mode drops the scoreboard entirely: an
// endless rally where faults just re-serve, the rally counter doubling as a
// survival streak the career record keeps — with the CPU quietly sharpening
// as the streak grows. A ball machine can take over the far end instead:
// it lobs a steady supply of balls at a chosen pace for passing and digging
// practice, no serving needed. A guided drill ladder can take over instead:
// serve timing, platform passing, steering and spike placement, each a short
// challenge with a clear pass mark, a drill pill tracking the progress, and
// a gold star banked on the career record for every drill passed. Low
// terraces all round the court carry an
// instanced crowd that sways with the rally and throws a wave round the
// stands whenever the arena erupts — and under the floodlights, on the night
// and indoor courts, a share of the fans hold tiny glowing phone lights that
// flicker and sway with the crowd, brightening as it erupts and settling
// during serves. A pause button in the top corner freezes
// the whole match mid-frame — timers, slow motion, a toss in the air — until
// it is resumed, restarted or left for the menu, and a timeout spent beside
// it once a set freezes the play for a beat on its own — the murmur
// settles, the booth names it, and the CPU's momentum run and the adaptive
// bias both reset to even, so a runaway streak can be stopped once a set.
// A slim momentum bar under
// the score leans toward whichever side owns the run of play, tinted in each
// side's colours, the crowd murmur reads it, the stands chant along to it in
// the rhythm of the surging player's typed name, and the booth calls the
// swing aloud by that name when a point shoves it past the mark.
// In the cup every round's opponent plays a signature style — a net-hugging
// blocker, a deep-court defender who lobs everything back, a jump-serve ace
// who attacks second balls — sharpened in the hard tier. A cup run can be
// taken in doubles too: the co-op rules all three rounds, the player and
// their CPU partner facing the round's opponent and the player's own build
// in its roster colours, a step harder each round, the pairing labelled on
// the bracket. Doubles plays a serving tactic picked beside the mode
// choices — the classic side-by-side rotation, or the stacking formation
// where the near pair line up together on one half and the partner takes
// over the half the player would normally hold — the pre-match team sheet
// naming the pick. The daily challenge
// is one seeded match a day: the date draws the opponent, their style, the
// level, the court and the wind, and one attempt banks the result until
// tomorrow. Between sets the breeze can freshen, ease or swing a quarter —
// the booth calls the shift and the flags show it at once — though never
// under a roof, and never in the day's seeded match. The season ladder plays
// its rungs one set at a time — the rank
// you sit on names the opponent, their style and the level, a win climbs one
// rung, a loss slides one back, and the rank rides the career record. A
// plain VS CPU match quietly adapts instead: a run of three
// straight points shifts the CPU's speed, prediction and aim a notch toward
// the player left behind, easing back once the score evens out, with a tiny
// pill beside the clock naming the live bias. The legend tier above hard —
// unlocked by beating the season ladder's top rung — plays the top scale of
// everything and never adapts at all. A stadium team sheet rides the
// pre-match flyover: both athletes named with their builds and stats, the
// cup round or daily seeding when there is one, and the day's wind call —
// sliding in with the sweep and away as the camera lands. The players read
// by the names typed on the title screen — the team sheet, the recap
// headline, the momentum labels and the title tally line — with YOU and P2
// kept as the fallbacks when a field was left empty. A point won clean
// replays too: an untouched serve landing for an ace, or a launch at the net
// stopping a spike dead, earns the slow-motion sideline treatment with the
// booth calling ACE! or WHAT A BLOCK! over the banner and the crowd wave
// sweeping the stands as the point lands — whoever played it. The super
// strike earns the same treatment at its rally's end: the booth calls SUPER
// STRIKE! over the banner and the blazing trail burns again in the slow
// motion — whoever played it, with a settings toggle picking the angle the
// replays cut to: the low sideline shot as always, or the net cam hung on
// the post above its pennant looking down the tape. A lost
// match's recap carries the coach's line under the stats, read off the
// match's own numbers and rotating across losses, so the next defeat
// teaches something new. A mark that grazes a line can go to review: one
// challenge a set, offered to the side the call favoured, settled by an
// overhead replay that draws the landing mark and rules it IN or OUT — a
// won challenge keeps the point, a lost one hands it over. Where the
// player's shots land is kept as well: every human strike dying in bounds
// on the far court drops into a light six-by-six grid of buckets, the
// match's tally banking into a career-long one at the final point — read
// back on the career screen as a small overhead heat map of the far court,
// cool blue where shots rarely land, hot red where they pile up — and the
// far side's own landings are kept the same way over the near half, the
// career screen's one overhead court flipping between where your shots go
// and where theirs do. Every shot that dies on the court leaves a small
// chalk mark on the sand where it landed — a dozen pooled, fading out over
// a few seconds — so placement reads on the court itself. The big points
// are measured as well: set point, match point and every tie-break point
// are counted won and lost — on the recap card and, career long, on the
// stats screen. The serve runs are kept too: consecutive points won on
// serve, the run dying the moment service changes hands — the match's
// best run reads on the recap, the career best on the stats screen. A set
// taken after trailing it by three or more points is a comeback: the booth
// calls WHAT A COMEBACK! with its own sting while the crowd erupts, the
// match's comeback sets read on the recap, and the career total joins the
// record. The match ends by naming its standout moment too: the fastest
// serve, the longest rally or a super strike — whichever measured biggest —
// takes a gold SHOT OF THE MATCH card on the recap, and the matches that
// earned one are counted on the career screen. Every athlete carries a
// stamina meter as well: sprints and jumps spend it, standing and the break
// between points refill it, and as it empties the legs run and jump a size
// smaller — a slim bar beside each side's power meter keeping the score,
// with the CPU reading the same meter so a tired opponent plays tired. And
// the opponent talks back: the second ace in a row, a super strike and a set
// stolen from behind each earn a word from across the net — grudging respect
// from a rival already beaten, needle from one still ahead — as a small
// speech pill by their name in the score, on a cooldown so it never
// interrupts the flow of play. The week's goals read the play as it goes,
// too: match wins, aces served up, rallies kept alive past twelve touches
// and runs of points won on serve all bank toward the three rotating weekly
// goals the title screen's card tracks, each toasted in gold the moment it
// completes. A title raised or a milestone badge earned unfurls a gold
// banner across the far stand — a few of the fans holding it up while the
// wave sweeps — and it never shows during a replay or the flyover. The
// team sheet scouts a named opponent as well: the head-to-head off the log,
// the run either side is on, and how their aces and spikes have landed in
// past meetings — a first meeting reads their style alone.

import * as THREE from 'three';
import { Scene } from '../scene.js';
import { addText, addButton, clearHUD } from '../hud.js';
import { haptic, hapticStop } from '../hapticsGate.js';
import { createAthlete, updateAthlete, triggerSwing, applyPose, canStrikeBall, captureAthletePose, resetAthlete, setDiveLean } from '../athlete.js';
import { updateModels } from '../models.js';
import { makeAdBoardTexture, makeBallTexture, makeCourtTexture, makeGymWallTexture, makeIndoorCourtTexture, makeNetTexture, makeSandTexture, makeScoreboardTexture, makeSkyTexture } from '../textures.js';
import { shakeOn, broadcastCamera, replayNetCam } from '../settings.js';
import { cycleRotation, toLocal, toLocalDelta } from '../orientation.js';
import { playSlap, playBump, playNet, playFloor, playWhistle, playCheer, playHeartbeat, playSqueak, playFanfare, playWhoosh, playZap, playSting, playBadgeSting, playComebackSting, crowdErupt, murmur, speakName, speakLine } from '../sfx.js';
import { randomTheme, selectedVenue } from '../themes.js';
import { ROSTER, selectedCharacter, cpuCharacter, p2Character, athleteUnlocked, selectedDifficulty, selectedMode, selectedLength, selectedTactic, playerColors, playerName, selectedName, DIFFICULTIES } from '../roster.js';
import { recordMatch, recordMatchLog, recordMilestone, recordServe, recordStreak, recordTouch, recordDrillStar, recordHeatShots, recordRivalHeatShots, HEAT_COLS, HEAT_ROWS, recordRallyReplay, rallyReplay, careerStats, careerLosses, matchLog, rivalScout, BADGES, dateKey, playerTitle, recordWeeklyStat, recordWeeklyBest, weeklyGoalName, takeAthleteToast } from '../record.js';
import { cupRun, advanceCup, endCup, completeCup } from '../cup.js';
import { dailyRun, finishDaily } from '../daily.js';
import { ladderRun, finishLadder } from '../ladder.js';
import { rivalRun, finishRivalMatch } from '../rivalMatch.js';
import { seriesActive, seriesScore, seriesNextServer, seriesMatchNo, recordSeriesMatch } from '../series.js';
import { BootScene } from './BootScene.js';

const G = 22;                 // a slightly heavy gravity keeps arcs readable
const HALF_W = 4;             // court half width (x) — the real 8 m court
const HALF_L = 8;             // court half length (z) — the real 16 m court
const NET_TOP = 2.34;         // top of the net band
const NET_HALF_W = 4.4;      // the net posts, slightly wider than the court
const BALL_R = 0.2;           // the ball: chunky and easy to track
const REACH = 1.22;           // bump contact radius around the chest
const REACH2 = REACH * REACH;
const WIN_SCORE = 7;          // points that take a set — best of three
const TIEBREAK_SCORE = 15;    // points that take the golden tie-break set
const TIEBREAK_MARGIN = 2;    // ...and it has to be won by two clear points
const TIEBREAK_SWAP = 6;      // tie-break ends swap after every six points
const CHARGE_TIME = 0.85;     // seconds of holding jump to fill the meter
const CHARGE_DECAY = 0.35;    // seconds for a released charge to fade out
const LOB_CHARGE = 0.22;      // below this, a strike in the air is a lob
const TOSS_V = 8.2;           // upward speed of the player's serve toss
// The three deliberate moves: a panic dive for balls dropping out of reach,
// an on-demand power strike, and a launch — a super jump on a cooldown.
const DIVE_T = 0.55;          // cap on the dive's airtime
const DIVE_SPEED = 5.6;       // horizontal lunge speed
const DIVE_VY = 3.3;          // the little hop that starts the dive
const DIVE_GETUP = 0.85;      // seconds spent picking yourself up off the sand
const LAUNCH_MULT = 1.55;     // the launch jumps this much higher
const LAUNCH_CD = 3.4;        // ...and then needs this long to recharge
const STRIKE_CD = 0.4;        // the gap between strike attempts
// Player stamina: sprints and jumps spend the legs, standing and the break
// between points refill them. An empty tank runs at its floor pace and jumps
// at its floor height — late long sets feel heavy in everyone's legs, the
// CPU reading the same meter so tired opponents play tired.
const STAM_DRAIN = 0.07;      // per second at a full sprint
const STAM_REGEN = 0.09;      // per second while standing
const STAM_JUMP = 0.06;       // spent by every jump
const STAM_LAUNCH = 0.1;      // ...and a little more by a launch
const STAM_SPEED = 0.72;      // the run-speed floor of an empty tank
const STAM_JUMP_LOSS = 0.8;   // ...and its jump-height floor
// The super strike: touches fill the meter, a full meter arms the flame
// button, and the next touch that sends the ball over burns the whole thing
// on one blistering drive.
const SUPER_GAIN = 0.25;      // meter earned per touch
const SUPER_CHARGE = 1.35;    // the charge a super shot strikes with
const SUPER_MAXH = 30;        // ...and how fast the court will let it fly
// The practice target challenge: the glowing ring on the far court starts at
// this radius, shrinks by this factor with every hit, and never gets tighter
// than the floor.
const RING_R0 = 0.95;
const RING_SHRINK = 0.8;
const RING_R_MIN = 0.34;
// The guided drill ladder: four short challenges, each with a clear pass
// mark. Serve timing, steering and spike placement count shots into the
// target ring — which holds still for them, at its opening size — while
// platform passing is judged on the live rally instead. Five shots short of
// the mark and the drill simply starts over.
const DRILLS = [
  { id: 'serve', name: 'SERVE TIMING', goal: 'LAND 3 OF 5 SERVES INSIDE THE RING', need: 3, attempts: 5, accepts: 'serve' },
  { id: 'pass', name: 'PLATFORM PASSING', goal: 'KEEP A 6-TOUCH RALLY ALIVE', touches: 6 },
  { id: 'steer', name: 'STEERING', goal: 'STEER 3 OF 5 SHOTS INTO THE RING', need: 3, attempts: 5, accepts: 'steer' },
  { id: 'spike', name: 'SPIKE PLACEMENT', goal: 'LAND 3 OF 5 SPIKES INSIDE THE RING', need: 3, attempts: 5, accepts: 'spike' }
];
// The ball machine drill: the gap between feeds and the flight time of a
// machine lob, per pace — slow arcs well apart, fast feeds coming thick.
const DRILL_PACE = {
  slow: { gap: 3.4, T: 1.9 },
  medium: { gap: 2.4, T: 1.55 },
  fast: { gap: 1.6, T: 1.25 }
};
// How hard the breeze blows per CPU level: barely there on easy, a real
// factor on hard, a shade stiffer still under the legend tier.
const WIND_SCALE = { easy: 0.38, normal: 0.6, hard: 0.9, legend: 1.0 };
// Sand spray: one pooled instanced mesh of grain quads. A dive, a launch and
// a long rally's strides kick the surface up; every grain falls and shrinks
// away inside a second.
const SPRAY_MAX = 72;
const SPRAY_G = 7.5;
// The end-of-set huddle: a beat to walk in to the tape, a beat grouped up
// while the booth sums the set, then out to the new ends.
const HUDDLE_GATHER = 1.0;
const HUDDLE_HOLD = 1.6;
const HUDDLE_BACK = 1.0;
// The pre-match flyover: this many seconds from high behind the net down
// into the playing camera, run once at the top of every match.
const FLY_T = 3.0;
// The booth's momentum call: a point that shoves the bar this far toward one
// side earns a one-line call from the commentary — and then the booth keeps
// quiet for this long, so the call never spams.
const MOMENTUM_CALL = 0.72;
const MOMENTUM_CD = 14;
// The match-point drama: this long is the terrace spotlight's sweep across
// the stands before its beam locks onto the serving athlete.
const SPOT_SWEEP = 2.2;
// The line-judge challenge: a mark within half a metre of a line can be
// reviewed — one challenge per set — and the tighter the mark, the likelier
// the judge misread it. The offer window, and how sporting the CPU is with
// a close point of its own, sit here too.
const CHALLENGE_DIST = 0.5;     // how close to a line a reviewable mark lands
const CHALLENGE_ERR = 0.16;     // misread chance at the edge of that window
const CHALLENGE_ERR_MAX = 0.66; // ...and right on the line
const CHALLENGE_WAIT = 3.6;     // how long the offer stays on the table
const CHALLENGE_CPU = 0.3;      // the CPU's chance of reviewing its own point
// Ball spin, read off the drag at contact: swiping across the shot's flight
// puts sidespin on the ball — it breaks sideways mid-air — and a late, low
// contact digs up backspin that drags a float down short of its mark.
const SPIN_DEAD = 0.14;         // drag across below this reads as plain aim
// The landing marks: how long a chalk disc takes to fade off the sand.
const MARK_LIFE = 3.5;
// The opponent's reactions: the second ace in a row, a super strike and a
// set stolen from behind all earn the far athlete a word — grudging respect
// from a rival the player has beaten before, needle from one still ahead —
// held back this long after each one so the play is never interrupted.
const REACT_CD = 12;
const REACT_LINES = {
  ace: {
    respect: [
      'OK — THAT SERVE IS YOURS TODAY.',
      'FINE. NOBODY IS TOUCHING THAT ONE.',
      'STOP SERVING LIKE THAT, SERIOUSLY.'
    ],
    needle: [
      'BEGINNER LUCK. SERVE IT AGAIN.',
      'THE SUN WAS IN MY EYES ON THAT ONE.',
      'THAT ONE DOES NOT LAND TWICE.'
    ]
  },
  super: {
    respect: [
      'ALRIGHT — THAT ONE WAS FILTHY.',
      'NOBODY RETURNS THAT. NOBODY.'
    ],
    needle: [
      'SHOWING OFF ALREADY?',
      'SAVE THE FIREWORKS FOR MATCH POINT.',
      'CUTE TRICK. TRY IT AGAIN.'
    ]
  },
  comeback: {
    respect: [
      'I HAD THAT SET. I HAD IT.',
      'YOU STOLE THAT ONE — NEXT SET IS MINE.'
    ],
    needle: [
      'THAT SET WAS GIFT-WRAPPED.',
      'ENJOY IT — IT WILL NOT HAPPEN AGAIN.'
    ]
  }
};

const clamp = (v, lo, hi) => Math.min(hi, Math.max(lo, v));
const mix = (a, b, t) => a + (b - a) * t;
const TAU = Math.PI * 2;

// What the crowd wears, per theme: bright summer kit under the midday sun,
// warm tones at sunset, darker coats with a few bright flags of colour under
// the floodlights. Heads are skin tones, with the odd cap.
const CROWD_KIT = {
  midday: [0xd8453f, 0x1d6fb8, 0xf2d16b, 0x2f9e6e, 0xf2f2f2, 0xe8834a, 0x8a5a9e],
  sunset: [0xe8834a, 0xb05c6e, 0xf2d16b, 0x8a4a62, 0xd9c2a0, 0xc25b3a],
  night: [0x2b3a52, 0x3a4750, 0xd8453f, 0x1d6fb8, 0xf2d16b, 0x6e5a8e]
};
const CROWD_SKIN = [0xd9a679, 0xb07b4f, 0x8a5a3b, 0xf2c9a0, 0x6e4527];
const CROWD_CAP = [0x2b2320, 0xd8453f, 0x1d6fb8, 0xf2f2f2];

/// A jersey colour as a CSS tint — the momentum bar and its end labels are
/// dressed in each side's own kit colours.
const hexCss = (n) => '#' + n.toString(16).padStart(6, '0');

/// The radar gun: a launch velocity read as a serve speed in km/h. What it
/// measures is the flat horizontal drive — the pace the court actually feels
/// — plus a small share of the lift, so a charged jump serve reads far hotter
/// than a float that only hangs.
const serveKmh = (vel) =>
  Math.round((Math.hypot(vel.x, vel.z) + 0.15 * Math.abs(vel.y)) * 8);

/// A kit's colours as the record's kit string — jersey and shorts, two hex
/// codes — so the serve speed league can dress every entry as struck.
const kitText = (c) => `#${c.jersey.toString(16).padStart(6, '0')},` +
  `#${c.shorts.toString(16).padStart(6, '0')}`;

/// Rounding for the career replay's stored frames: three decimals on the
/// metre-scale numbers, four on the quaternion channels — small enough to
/// keep in the record, exact enough that the playback reads smoothly.
const r3 = (n) => Math.round(n * 1000) / 1000;
const r4 = (n) => Math.round(n * 10000) / 10000;
const packArr = (a) => {
  const out = new Array(a.length);
  for (let i = 0; i < a.length; i++) out[i] = r4(a[i]);
  return out;
};

/// A name's syllables, read the cheap way: every run of vowels is a beat the
/// crowd can shout. The chant layer beats the surging player's name in that
/// rhythm — short names slow and heavy, long ones fast and urgent.
const syllables = (name) => {
  const m = name.toLowerCase().match(/[aeiouy]+/g);
  return m ? m.length : 1;
};
const chantRate = (name) => clamp(0.9 + 0.5 * syllables(name), 1.2, 3.4);

// Scratch for the spin read: filled per call and consumed on the spot, so
// the per-frame aim hint never allocates.
const spinRead = { mag: 0, signed: 0, perpX: 0, perpZ: 0 };

export class MatchScene extends Scene {
  create() {
    this.tmp = new THREE.Vector3();
    this.tmp2 = new THREE.Vector3();
    this.tmpQ = new THREE.Quaternion();
    this.tmpQ2 = new THREE.Quaternion();
    this.tmpUp = new THREE.Vector3(0, 1, 0);
    this.netWobble = 0;
    this.camKick = 0;
    // Drama state: the crowd murmur level, the heartbeat timer, how long the
    // rally has run and whether the commentator has had his say this rally.
    this.murmurLevel = 0;
    this.murmurBright = 0;
    this.heartT = 0.5;
    this.rallyLen = 0;
    this.hypeSaid = false;
    this.hypeT = 0;
    // Slow motion on the big spike, and the celebration once the match ends.
    this.timeScale = 1;
    this.slowT = 0;
    this.matchWinner = null;
    this.overT = 0;
    // Whether match point is up: the crowd erupts outright the moment it
    // arrives, so the scene has to remember when it came up — and whether
    // the booth has already named it this set, the call being once per set.
    this.mpWas = false;
    this.mpSaid = false;
    // The stands: how much the crowd sways and lifts, the wave currently
    // sweeping the terraces, and the clock that drives the idle bobbing.
    this.crowdLift = 0.15;
    this.crowdLiftTarget = 0.15;
    this.crowdWave = 0;
    this.crowdWaveA = 0;
    this.crowdT = Math.random() * 10;
    // The milestone banner: the gold cloth the far stand unfurls when a
    // career title is reached or a badge is earned. -1 is its resting clock.
    this.bannerT = -1;
    this.bannerHold = null;
    this.bannerHoldLevel = 0;
    // The pre-match flyover: the match opens on a slow sweep from high
    // behind the net down into the playing camera — once per match, never
    // between sets.
    this.flyT = FLY_T;
    // The match recap: points won per side, the longest rally in touches, the
    // spikes each side hit, the aces and blocks each side served up, the
    // clutch record — the big points won and lost — the best run of
    // consecutive points won on serve, and the comeback sets — sets taken
    // from three or more points down — shown on the card after the final
    // point.
    this.stats = {
      points: { player: 0, cpu: 0 },
      longestRally: 0,
      spikes: { player: 0, cpu: 0 },
      aces: { player: 0, cpu: 0 },
      blocks: { player: 0, cpu: 0 },
      clutch: { won: 0, lost: 0 },
      serveRun: { player: 0, cpu: 0, best: 0 },
      comebacks: 0,
      // The match's fastest rally touch, in km/h — the pace readout's own
      // row on the recap, beside the aces and blocks.
      fastestTouch: 0
    };
    this.recapShown = false;
    this.pendingHeadline = null;
    // The shot of the match's raw material: the fastest serve of the match
    // and the first super strike struck, kept beside the longest rally the
    // stats already hold — read together at the final point to pick the
    // standout moment the recap names in gold.
    this.bestServe = null;
    this.superMoment = null;
    this.shot = null;
    // The match's own reel of banked rally recordings: every replay banks
    // its rally's closing seconds here, tagged with the touch count, the
    // serve's pace and whether a super strike burned in it — the keys the
    // gold moment finds its own clip by when the recap offers its REPLAY
    // pill.
    this.shotPool = [];
    // The placement heat grids: where the shots land, bucketed six across
    // and six deep over each court — the player's on the far half, the far
    // side's on the near half, both read as the camera sees them. Each is
    // the match's own tally: it starts fresh here and banks into the
    // career-long one the moment the match ends.
    this.heat = new Array(HEAT_COLS * HEAT_ROWS).fill(0);
    this.heatRival = new Array(HEAT_COLS * HEAT_ROWS).fill(0);
    // The serve in flight: the id of the athlete who struck it, kept until
    // anyone touches the ball again — an untouched serve that lands for a
    // point is an ace.
    this.serveLive = null;
    // A block in progress: the id of the athlete whose launch met a crossing
    // spike at the net — if the ball then dies on the attacker's side, the
    // block takes the point.
    this.blockPending = null;
    // The beginner CPU's queued misread: set as a ball crosses the net, spent
    // on the next plan — one approach in four it goes after the wrong spot.
    this.cpuFumble = false;
    // The match clock: total time on court, shown as a pill under the score.
    this.clock = 0;
    this.clockShown = -1;
    // The replay recorder: a rolling window of the live rally — the ball and
    // both athletes, transforms and poses — kept ready to play back in slow
    // motion after a big point.
    this.recBuf = [];
    this.recT = 0;
    this.replayPending = false;
    // The end-of-set huddle's own state: null between sets.
    this.huddle = null;
    // The victory lap: null until the player wins a match.
    this.victoryLap = null;
    // The set-break team talk's tactics: the near team's pick and the CPU's
    // own, each standing for the next set only.
    this.teamTalk = null;
    this.cpuTalk = null;
    this.replayBanner = null;
    // The kind of the point that just died — an ace or a block — read by
    // the award flow to queue its replay and the booth's call for it.
    this.lastPointKind = null;
    // The booth's one-liner over the replay banner, queued with the replay.
    this.replayCall = null;
    // The super strike's own replay queue: a burn marks the rally it was
    // struck in, and that rally's end sends the sideline slow motion round
    // again with SUPER STRIKE! on the banner — the strike's own moment kept
    // in the recording, so the blazing trail burns a second time.
    this.superReplay = false;
    this.superStamp = false;
    this.superRecT = null;
    this.superQueued = false;
    this.replaySuper = false;
    this.superReplayDone = false;

    // Who the player picked on the title screen, and who the CPU drew from
    // the remaining roster. Each carries their own speed and jump.
    this.playerStats = selectedCharacter();
    // The picked mode as its id, whether the picker hands back the mode
    // object or the bare id.
    const picked = selectedMode();
    const modeId = typeof picked === 'string' ? picked : picked.id;
    // The far athlete: in a two-player match that is player two, drawn
    // deterministically so the title preview can dress them; against the CPU
    // it is a random draw from the characters the player did not pick.
    this.cpuStats = modeId === '2p' ? p2Character() : cpuCharacter();
    // The recruit's status as the scene opened: the win that crosses her
    // wins requirement announces her in play — a first-time crossing only,
    // so a record already past the mark stays quiet for the title to speak.
    this.novaChar = ROSTER.find((r) => r.id === 'nova') || null;
    this.novaBefore = !this.novaChar || athleteUnlocked(this.novaChar);
    // Doubles draws the partner and the second opponent from the rest of the
    // roster: the partner takes the first athlete the player did not pick,
    // the far opponent the second, and the fourth athlete is the player's own
    // build in its roster colours — three bodies across four jerseys, each
    // pair told apart by its kit.
    if (modeId === 'doubles') {
      const rest = ROSTER.filter((r) => r.id !== this.playerStats.id);
      this.partnerStats = rest[0];
      this.cpuStats = rest[1] || rest[0];
      this.cpu2Stats = {
        ...selectedCharacter(),
        colors: { ...selectedCharacter().colors }
      };
    }
    // Co-op doubles: player two takes the near partner's body — the first
    // roster slot the player did not pick, dressed in their own picked kit —
    // and the far pair are two CPUs: the remaining roster athlete, and the
    // player's own build in its roster colours.
    if (modeId === 'coop') {
      this.partnerStats = p2Character();
      const rest = ROSTER.filter((r) => r.id !== this.playerStats.id);
      this.cpuStats = rest.find((r) => r.id !== this.partnerStats.id) || rest[0];
      this.cpu2Stats = {
        ...selectedCharacter(),
        colors: { ...selectedCharacter().colors }
      };
    }
    // The CPU level chosen on the title screen: how fast it runs, how well it
    // predicts the landing, how tightly it aims and how often it mistimes.
    this.diff = selectedDifficulty();
    // Two players sharing the screen: the far athlete is human too, driven by
    // a drag zone on the right of the screen and a jump button on the left.
    this.twoPlayer = modeId === '2p';
    // Co-op doubles: the same four-athlete structure as the CPU doubles —
    // serves alternate within each team, each near athlete holds a half of
    // the court and the usual set, tie-break and scoring rules all hold —
    // but the near partner is player two, driven by the second set of
    // controls against two CPU opponents.
    this.coop = modeId === 'coop';
    this.doubles = modeId === 'doubles' || this.coop;
    // Practice: the endless rally. The scoreboard stays dark, faults re-serve
    // instead of awarding points, and a close button returns to the title.
    this.practice = modeId === 'practice';
    this.practiceServer = 'player';
    // Blitz: a three-minute match against the CPU. One running score, no
    // sets, the clock shown beside the score deciding it at the horn — and
    // level at the horn handing the next point sudden-death power. The ends
    // swap once, at half time.
    this.blitz = modeId === 'blitz';
    this.blitzT = 180;
    this.blitzHalf = false;
    this.blitzSD = false;
    this.blitzOver = false;
    this.blitzExpired = false;
    // The arena's look is drawn fresh every match: midday, sunset, a
    // floodlit night or the indoor arena — or, for the plain matches, the
    // venue picked on the title screen, which overrides the random draw.
    // Practice keeps drawing, and the cup, the daily and the ladder hand
    // over their own court further down. The beach courts change only the
    // sky, the fog and the lights; the indoor arena swaps its sand for a
    // smooth blue floor dressed like a real volleyball hall — gym walls, LED
    // boards, a scoreboard and a lit ceiling — and plays in still air.
    this.theme = this.practice
      ? randomTheme()
      : (selectedVenue() || randomTheme());
    // The CPU's jump serve: planned the moment its countdown ends, then run
    // while its toss hangs in the air.
    this.cpuServeT = 9;
    this.cpuServeJumped = false;
    // A cup round, if one is under way: the opponent, its level and the
    // arena's look are all fixed by the run, the whole match is a single
    // set, and the opponent plays its signature style on top of the level.
    this.cupMatch = null;
    // The cup opponent's signature style, if one is under way: the biases
    // the CPU brain reads on top of its difficulty, sharpened in the hard
    // tier. Null everywhere else, where the CPU plays plain.
    this.cpuStyle = null;
    const cup = cupRun();
    if (cup) {
      this.cupMatch = cup;
      // The cup owns the format: every round plays the rules its run was
      // started under — singles as always, or the co-op doubles rules —
      // whatever the mode picker happens to be sitting on. A doubles run
      // draws its partner and second opponent exactly as the plain doubles
      // mode does: the near partner takes the roster slot the round's named
      // opponent is not wearing, and the player's own build in its roster
      // colours stands beside that opponent on the far court.
      this.twoPlayer = false;
      this.coop = false;
      this.practice = false;
      this.blitz = false;
      this.doubles = !!cup.doubles;
      if (this.doubles) {
        this.partnerStats = cup.partners
          ? cup.partners[cup.round - 1]
          : ROSTER.filter((r) => r.id !== this.playerStats.id)[0];
        this.cpu2Stats = {
          ...selectedCharacter(),
          colors: { ...selectedCharacter().colors }
        };
      }
      this.cpuStats = cup.opponents[cup.round - 1];
      this.theme = cup.themes[cup.round - 1];
      this.diff = DIFFICULTIES.find((d) => d.id === cup.levels[cup.round - 1]);
      const st = this.cpuStats.style;
      if (st) this.cpuStyle = this.styleBiases(st, cup.sharp);
    }
    // A daily challenge, if one is under way: the whole day drew it — the
    // opponent and their style, the level, the court and the breeze — and
    // the match is a single set, one attempt.
    this.dailyMatch = null;
    const daily = dailyRun();
    if (daily) {
      this.dailyMatch = daily;
      this.cpuStats = daily.opp;
      this.theme = daily.theme;
      this.diff = daily.diff;
      const st = daily.opp.style;
      if (st) this.cpuStyle = this.styleBiases(st, 1);
    }
    // A season ladder rung, if one is under way: the opponent under their
    // ladder name, their signature style, the level and the court are all
    // fixed by the rung, and the match is a single set that moves the rank
    // one way or the other.
    this.ladderMatch = null;
    const ladder = ladderRun();
    if (ladder) {
      this.ladderMatch = ladder;
      this.cpuStats = ladder.opp;
      this.theme = ladder.theme;
      this.diff = DIFFICULTIES.find((d) => d.id === ladder.opp.level);
      const st = ladder.opp.style;
      if (st) this.cpuStyle = this.styleBiases(st, 1);
    }
    // A rival dossier's PLAY THEM pill: a one-off VS CPU match against the
    // rival the rivals screen sent over — their body and their signature
    // style riding on top of the player's chosen difficulty, the plain
    // best-of-three rules around it. The result lands in the log under
    // their name, so the rivalry keeps growing. A cup run still live stands
    // aside for this one match — the bracket itself is untouched and waits.
    this.rivalMatch = null;
    const rival = rivalRun();
    if (rival) {
      this.rivalMatch = rival;
      this.twoPlayer = false;
      this.coop = false;
      this.practice = false;
      this.blitz = false;
      this.doubles = false;
      this.cupMatch = null;
      this.cpuStats = rival;
      this.diff = selectedDifficulty();
      this.theme = selectedVenue() || randomTheme();
      const st = rival.style;
      if (st) this.cpuStyle = this.styleBiases(st, 1);
      finishRivalMatch();
    }

    // The session's series, when the title's SERIES toggle is on and this is
    // a plain VS CPU match: two players, doubles, practice, the blitz and
    // the cup's own matches all stay out of it.
    this.seriesMatch = !this.twoPlayer && !this.doubles && !this.practice &&
      !this.blitz && !this.cupMatch && !this.dailyMatch &&
      !this.ladderMatch && seriesActive();
    this.seriesWon = false;

    // The adaptive level: plain VS CPU matches only — the cup, the daily and
    // two-player stay fixed to their chosen level, practice has no score
    // to read, and the legend tier never bends for anyone. The live
    // difficulty is swapped for a biased copy whenever the bias moves; at
    // even it is the chosen level untouched.
    this.adaptOn = !this.twoPlayer && !this.doubles && !this.cupMatch &&
      !this.dailyMatch && !this.ladderMatch && !this.practice &&
      !this.diff.legend;
    this.baseDiff = this.diff;
    this.adapt = 0;
    this.runWho = null;
    this.runLen = 0;

    // The breeze: the daily drew its own for the whole day; every other
    // match draws fresh, blowing steadily from one quarter, stronger the
    // harder the CPU level.
    if (this.dailyMatch) {
      this.wind = { ...this.dailyMatch.wind };
    } else {
      const ang = (Math.random() < 0.5 ? 0 : Math.PI) + (Math.random() - 0.5) * 1.3;
      this.wind = {
        x: Math.cos(ang),
        z: Math.sin(ang),
        strength: (0.55 + Math.random() * 0.5) * WIND_SCALE[this.diff.id]
      };
    }
    this.windT = 0;
    // Under a roof there is no weather at all: the drawn breeze dies, the
    // pennants hang still and the ball flies true wherever it was struck.
    if (this.theme.indoor) this.wind.strength = 0;

    this.buildCourt();
    this.buildAthletes();
    this.buildBall();
    this.buildAimArrow();
    this.buildWind();
    this.buildCrowd();
    this.buildBanner();
    this.buildSpotlight();
    this.buildFlash();
    this.buildMarks();
    this.buildSpray();
    // The flash state: one burst on the court at a time, plus the burning
    // trail of embers the ball drags behind a hard strike.
    this.flashT = 1;
    this.trailT = 0;
    this.trailTimer = 0;
    this.trailI = 0;

    // Sky, reflections and lights from the theme — applied after the world
    // exists, so the environment and the shadows dress everything at once.
    this.applyTheme();
    // Indoors, the mirror world under the polished court is built last: the
    // net, both athletes, the ball and the practice machine, each a flipped
    // copy of the real thing.
    if (this.theme.indoor) this.buildReflection();

    // ----- HUD -----
    this.scoreText = addText('YOU 0 · CPU 0', {
      top: 'calc(env(safe-area-inset-top) + 14px)',
      left: '0',
      right: '0',
      textAlign: 'center',
      fontSize: '21px',
      color: '#ffffff',
      textShadow: '0 2px 6px rgba(20,40,60,0.55)'
    });
    this.setTally = addText('SETS 0–0', {
      top: 'calc(env(safe-area-inset-top) + 48px)',
      left: '0',
      right: '0',
      textAlign: 'center',
      fontSize: '13px',
      fontWeight: '700',
      letterSpacing: '1px',
      color: 'rgba(255,255,255,0.85)',
      textShadow: '0 1px 4px rgba(20,40,60,0.5)'
    });
    // The set-by-set strip: a small pill per set, tucked under the score and
    // clock, filling in as each set finishes — the live set's score riding the
    // end in gold. It reads the match's own set tally and shows the scores the
    // way the ends stand, flipping around when the sides swap.
    this.setStrip = addText('', {
      top: 'calc(env(safe-area-inset-top) + 116px)',
      left: '50%',
      transform: 'translateX(-50%)',
      display: 'flex',
      gap: '5px',
      pointerEvents: 'none'
    });
    this.setPills = [];
    // Five pills is the most a match can fill (a best-of-five marathon).
    for (let i = 0; i < 5; i++) {
      const pill = addText('', {
        position: 'static',
        padding: '2px 9px',
        borderRadius: '999px',
        backgroundColor: 'rgba(10, 18, 30, 0.45)',
        border: '1px solid rgba(255, 255, 255, 0.12)',
        fontSize: '10px',
        fontWeight: '800',
        letterSpacing: '0.5px',
        color: 'rgba(255, 255, 255, 0.75)',
        display: 'none',
        pointerEvents: 'none'
      });
      this.setStrip.appendChild(pill);
      this.setPills.push(pill);
    }
    this.refreshSetStrip();

    // The match clock: a small pill at the top, ticking with every second on
    // court and freezing when the match ends.
    this.timeText = addText('00:00', {
      top: 'calc(env(safe-area-inset-top) + 70px)',
      left: '50%',
      transform: 'translateX(-50%)',
      fontSize: '13px',
      fontWeight: '800',
      letterSpacing: '1.5px',
      padding: '3px 12px',
      borderRadius: '999px',
      backgroundColor: 'rgba(10, 18, 30, 0.45)',
      color: 'rgba(255,255,255,0.92)'
    });
    // The adaptive level's readout: a tiny pill beside the clock, naming the
    // live bias — EVEN, FAVOURS YOU, FAVOURS CPU — so the rubber-band reads
    // as drama rather than rubber-stamping. Only an adapting match has one.
    if (this.adaptOn) {
      this.adaptPill = addText('EVEN', {
        top: 'calc(env(safe-area-inset-top) + 92px)',
        left: '50%',
        transform: 'translateX(-50%)',
        fontSize: '9px',
        fontWeight: '800',
        letterSpacing: '1px',
        padding: '3px 8px',
        borderRadius: '999px',
        backgroundColor: 'rgba(10, 18, 30, 0.45)',
        color: 'rgba(255,255,255,0.75)'
      });
      this.adaptShown = 'EVEN';
    }
    // The series pill: the session's running series score beside the score,
    // carried across the session's matches — MATCHES 1–0.
    if (this.seriesMatch) {
      const ss = seriesScore();
      this.seriesPill = addText(`MATCHES ${ss.wins}–${ss.losses}`, {
        top: 'calc(env(safe-area-inset-top) + 70px)',
        right: '16px',
        fontSize: '9px',
        fontWeight: '800',
        letterSpacing: '1px',
        padding: '3px 9px',
        borderRadius: '999px',
        backgroundColor: 'rgba(10, 18, 30, 0.45)',
        color: ss.wins + ss.losses > 0 ? '#ffd24a' : 'rgba(255,255,255,0.75)'
      });
    }
    // The momentum meter: a slim bar under the score, filling from its
    // centre toward whichever side owns the run of play. Each point won
    // pushes it that way — a long rally won pushes harder — and it eases
    // back toward centre as the points trade. Tinted in each side's kit
    // colour, with the ends labelled, and the crowd murmur reads it too.
    // Practice has no score, so it has no bar either.
    this.momentum = 0;
    this.momentumShown = -1;
    // The booth's momentum call and the cooldown that keeps it occasional.
    this.momentumCall = null;
    this.momentumCallT = 0;
    // The murmur's chant layer: what it was last sent as, so the audio graph
    // is only touched on real change — the chant's tempo included.
    this.murmurChant = 0;
    this.murmurTint = 0;
    this.murmurRate = 2.4;
    this.colPlayer = hexCss(playerColors('p1').jersey);
    this.colCpu = hexCss(this.twoPlayer
      ? playerColors('p2').jersey
      : this.cpuStats.colors.jersey);
    if (!this.practice) {
      this.momentumTrack = addText('', {
        top: 'calc(env(safe-area-inset-top) + 38px)',
        left: '50%',
        transform: 'translateX(-50%)',
        width: '170px',
        height: '5px',
        borderRadius: '999px',
        backgroundColor: 'rgba(10, 18, 30, 0.45)',
        border: '1px solid rgba(255, 255, 255, 0.2)'
      });
      this.momentumFill = addText('', {
        left: '50%',
        top: '0',
        width: '0px',
        height: '3px',
        borderRadius: '999px',
        backgroundColor: this.colPlayer,
        opacity: '0',
        pointerEvents: 'none'
      });
      this.momentumTrack.appendChild(this.momentumFill);
      this.momentumTrack.appendChild(addText('', {
        left: '50%',
        top: '-2px',
        width: '2px',
        height: '7px',
        transform: 'translateX(-50%)',
        borderRadius: '1px',
        backgroundColor: 'rgba(255, 255, 255, 0.55)',
        pointerEvents: 'none'
      }));
      // The ends are labelled and tinted with each side's own name — the one
      // typed on the title screen, falling back to P1 and P2 — and the CPU
      // keeps its roster name.
      this.momentumL = addText(playerName('p1'), {
        top: 'calc(env(safe-area-inset-top) + 33px)',
        right: 'calc(50% + 94px)',
        fontSize: '10px',
        fontWeight: '800',
        letterSpacing: '1px',
        color: this.colPlayer,
        textShadow: '0 1px 4px rgba(20,40,60,0.5)'
      });
      this.momentumR = addText(this.twoPlayer ? playerName('p2') : 'CPU', {
        top: 'calc(env(safe-area-inset-top) + 33px)',
        left: 'calc(50% + 94px)',
        fontSize: '10px',
        fontWeight: '800',
        letterSpacing: '1px',
        color: this.colCpu,
        textShadow: '0 1px 4px rgba(20,40,60,0.5)'
      });
    }
    // The live rally counter: consecutive touches beside the score, growing
    // and warming as the rally builds. The practice close button owns the top
    // right corner, so the pill shifts left of it there.
    this.rallyText = addText('', {
      top: 'calc(env(safe-area-inset-top) + 44px)',
      right: this.practice ? '72px' : '16px',
      textAlign: 'center',
      fontSize: '13px',
      fontWeight: '800',
      letterSpacing: '1.5px',
      padding: '3px 10px',
      borderRadius: '999px',
      backgroundColor: 'rgba(10, 18, 30, 0.45)',
      color: '#9fd8ff',
      opacity: '0'
    });
    this.rallyShown = 0;
    this.rallyPop = 0;
    // The line-judge challenge: one review per set. The small pill by the
    // pause button shows how many remain, and the gold offer pill appears
    // whenever a close call hands the decision to the side it favoured.
    this.challengesLeft = 1;
    if (!this.practice) {
      this.challengePill = addText('CHALLENGE · 1', {
        left: '16px',
        top: 'calc(env(safe-area-inset-top) + 66px)',
        fontSize: '9px',
        fontWeight: '800',
        letterSpacing: '1px',
        padding: '2px 8px',
        borderRadius: '999px',
        backgroundColor: 'rgba(10, 18, 30, 0.45)',
        color: '#ffd24a'
      });
      this.challengeBtn = addButton({
        label: 'Challenge the call',
        onPress: () => this.takeChallengeOffer(),
        style: {
          position: 'absolute',
          width: '210px',
          height: '46px',
          left: 'calc(50% - 105px)',
          bottom: 'calc(env(safe-area-inset-bottom) + 122px)',
          borderRadius: '999px',
          backgroundColor: 'rgba(228, 178, 34, 0.95)',
          color: '#231503',
          fontSize: '13px',
          fontWeight: '800',
          letterSpacing: '2px',
          display: 'none'
        }
      });
      this.challengeBtn.textContent = 'CHALLENGE';
    }
    this.msgText = addText('', {
      top: 'max(32%, 130px)',
      left: '0',
      right: '0',
      textAlign: 'center',
      fontSize: '20px',
      fontWeight: '800',
      lineHeight: '1.25',
      padding: '0 16px',
      color: '#ffffff',
      textShadow: '0 2px 10px rgba(20,40,60,0.6)'
    });
    // The badge toast: created on the first milestone earned in play, a
    // small gold pill that slides in under the score and slides away again.
    this.badgeToast = null;
    this.badgeToastT = 0;
    // The opponent's reactions: a scored match against a named CPU opponent
    // only — the shared-screen and practice courts have nobody to talk. The
    // match log knows every opponent by name, so whether this one has been
    // beaten before decides the tone of everything they say: grudging
    // respect from a beaten rival, needle from one still ahead.
    this.reactOn = !this.twoPlayer && !this.coop && !this.doubles &&
      !this.practice;
    this.reactBeaten = this.reactOn && matchLog().some(
      (e) => e.won && e.opp === this.cpuStats.name.toUpperCase()
    );
    this.reactCd = 4; // a settle-in grace, so nobody talks over the flyover
    this.reactAces = 0;
    this.reactPill = null;
    this.reactPillT = 0;
    // The serve-speed radar: one pill that pops beside the server after every
    // serve, showing the pace of the strike in km/h — gold when it sets a new
    // career best.
    this.speedText = addText('', {
      left: '0px',
      top: '0px',
      transform: 'translate(-50%, -50%)',
      padding: '3px 10px',
      borderRadius: '999px',
      backgroundColor: 'rgba(10, 18, 30, 0.55)',
      color: '#ffffff',
      fontSize: '13px',
      fontWeight: '800',
      letterSpacing: '1px',
      opacity: '0',
      pointerEvents: 'none'
    });
    this.speedPop = null;
    // The league line: a small gold rank under the radar pill — 3RD
    // FASTEST EVER — shown when a serve enters the top five without
    // taking the record itself.
    this.speedRankText = addText('', {
      left: '0px',
      top: '0px',
      transform: 'translate(-50%, 0)',
      fontSize: '9px',
      fontWeight: '800',
      letterSpacing: '1.5px',
      color: '#ffd24a',
      textShadow: '0 1px 4px rgba(20,40,60,0.6)',
      whiteSpace: 'nowrap',
      opacity: '0',
      pointerEvents: 'none'
    });
    // The rally pace readout: a second pill, kept apart from the serve
    // radar's, that pops beside the athlete who just struck the ball —
    // every touch, not just the serve. It reads the strike's launch pace in
    // km/h the way the radar does and fades after a moment on its own,
    // never stacking on the serve pill's own readout.
    this.paceText = addText('', {
      left: '0px',
      top: '0px',
      transform: 'translate(-50%, -50%)',
      padding: '3px 10px',
      borderRadius: '999px',
      backgroundColor: 'rgba(10, 18, 30, 0.55)',
      color: '#ffffff',
      fontSize: '12px',
      fontWeight: '800',
      letterSpacing: '1px',
      opacity: '0',
      pointerEvents: 'none'
    });
    this.pacePop = null;
    // The partner's call: a gold MINE! pill projected over their head when a
    // dropping ball belongs to their half of the court. Doubles only.
    if (this.doubles) {
      this.callText = addText('', {
        left: '0px',
        top: '0px',
        transform: 'translate(-50%, -50%)',
        padding: '2px 9px',
        borderRadius: '999px',
        backgroundColor: 'rgba(228, 178, 34, 0.92)',
        color: '#231503',
        fontSize: '11px',
        fontWeight: '800',
        letterSpacing: '1.5px',
        opacity: '0',
        pointerEvents: 'none'
      });
      this.callT = 0;
      this.callPop = null;
    }
    // The CPU's automatic serve leaves as its first bump; the radar reads it
    // there. Cleared again the moment a serve is struck by hand.
    this.autoServeLive = false;
    // The screen the radar pill projects the server into, until resize says
    // otherwise — the stage's own size, which carries the turn's swapped
    // dimensions when the game is presenting landscape.
    this.viewW = this.game.stage.clientWidth;
    this.viewH = this.game.stage.clientHeight;
    this.jumpBtn = addButton({
      icon: 'arrow-up',
      label: 'Jump',
      onPress: () => {
        this.wantJump = true;
        // Holding charges the power meter; releasing lets it fade. A light
        // tap at contact lobs, a held charge spikes.
        this.charging = true;
        haptic('charge', 'charge1');
      },
      onRelease: () => {
        this.charging = false;
        hapticStop('charge1');
        // A release during the serve toss strikes the ball.
        if (this.state === 'toss' && this.tossWho === 'player') {
          if (this.tossIgnoreRelease) this.tossIgnoreRelease = false;
          else this.serveStrike();
        }
      },
      style: {
        position: 'absolute',
        width: '88px',
        height: '88px',
        right: '24px',
        bottom: 'calc(env(safe-area-inset-bottom) + 48px)',
        backgroundColor: 'rgba(23, 84, 130, 0.45)'
      }
    });

    // ----- the three new moves -----
    // Dive: a full-length panic save. Strike: an on-demand power hit.
    // Launch: a super jump that needs a cooldown to recharge. Player one's
    // strike and launch sit in the column beside jump; the dive lives on the
    // other thumb, low in the corner. In a shared-screen match the far
    // athlete gets a mirrored set, placed so no two buttons ever overlap.
    this.wantDive = false;
    this.wantStrike = false;
    this.wantLaunch = false;
    this.wantSuper = false;
    this.wantDive2 = false;
    this.wantStrike2 = false;
    this.wantLaunch2 = false;
    this.wantSuper2 = false;
    const mkMove = (icon, label, style, onPress, tint) => addButton({
      icon, label, onPress,
      style: {
        position: 'absolute',
        width: '64px',
        height: '64px',
        borderRadius: '999px',
        ...style,
        backgroundColor: tint
      }
    });
    this.diveBtn = mkMove('hand', 'Dive',
      this.twoPlayer || this.coop
        ? { left: '24px', bottom: 'calc(env(safe-area-inset-bottom) + 150px)' }
        : { left: '24px', bottom: 'calc(env(safe-area-inset-bottom) + 48px)' },
      () => { this.wantDive = true; },
      'rgba(20, 120, 110, 0.5)');
    this.strikeBtn = mkMove('zap', 'Strike',
      { right: '122px', bottom: 'calc(env(safe-area-inset-bottom) + 48px)' },
      () => { this.wantStrike = true; },
      'rgba(204, 92, 40, 0.5)');
    this.launchBtn = mkMove('rocket', 'Launch',
      { right: '122px', bottom: 'calc(env(safe-area-inset-bottom) + 124px)' },
      () => { this.wantLaunch = true; },
      'rgba(98, 62, 168, 0.5)');
    this.superBtn = mkMove('flame', 'Super strike',
      { right: '122px', bottom: 'calc(env(safe-area-inset-bottom) + 200px)' },
      () => { this.wantSuper = true; },
      'rgba(212, 140, 24, 0.5)');
    if (this.twoPlayer || this.coop) {
      this.diveBtn2 = mkMove('hand', 'Dive (player two)',
        { right: '24px', bottom: 'calc(env(safe-area-inset-bottom) + 150px)' },
        () => { this.wantDive2 = true; },
        'rgba(20, 120, 110, 0.5)');
      this.strikeBtn2 = mkMove('zap', 'Strike (player two)',
        { left: '122px', bottom: 'calc(env(safe-area-inset-bottom) + 48px)' },
        () => { this.wantStrike2 = true; },
        'rgba(204, 92, 40, 0.5)');
      this.launchBtn2 = mkMove('rocket', 'Launch (player two)',
        { left: '122px', bottom: 'calc(env(safe-area-inset-bottom) + 124px)' },
        () => { this.wantLaunch2 = true; },
        'rgba(98, 62, 168, 0.5)');
      this.superBtn2 = mkMove('flame', 'Super strike (player two)',
        { left: '122px', bottom: 'calc(env(safe-area-inset-bottom) + 200px)' },
        () => { this.wantSuper2 = true; },
        'rgba(212, 140, 24, 0.5)');
    }

    // ----- second player: jump button inset at the bottom left -----
    if (this.twoPlayer || this.coop) {
      this.jumpBtn2 = addButton({
        icon: 'arrow-up',
        label: 'Jump (player two)',
        onPress: () => {
          this.wantJump2 = true;
          this.charging2 = true;
          haptic('charge', 'charge2');
        },
        onRelease: () => {
          this.charging2 = false;
          hapticStop('charge2');
          // A release during their serve toss strikes the ball.
          if (this.state === 'toss' && this.tossWho === 'cpu') {
            if (this.tossIgnoreRelease2) this.tossIgnoreRelease2 = false;
            else this.serveStrike2();
          }
        },
        style: {
          position: 'absolute',
          width: '88px',
          height: '88px',
          left: '24px',
          bottom: 'calc(env(safe-area-inset-bottom) + 48px)',
          backgroundColor: 'rgba(150, 48, 48, 0.45)'
        }
      });
    }

    // ----- practice: the close button, and the close-out it raises -----
    if (this.practice) {
      this.closeBtn = addButton({
        icon: 'x',
        label: 'Back to menu',
        onPress: () => this.showCloseOut(),
        style: {
          position: 'absolute',
          width: '46px',
          height: '46px',
          right: '16px',
          top: 'calc(env(safe-area-inset-top) + 12px)',
          backgroundColor: 'rgba(20, 40, 60, 0.5)'
        }
      });
    }

    // ----- practice: the serving target challenge -----
    // A glowing ring on the far court, one at a time: land a serve or a
    // spike inside it and the tally ticks, the ring shrinks with every hit,
    // and a fresh ring waits on the next serve. The pill under the score
    // keeps hits out of attempts.
    if (this.practice) {
      // The survival streak: how long a rally can be kept alive against the
      // CPU. The session tracks its own best for the close-out; the record
      // keeps the longest ever, across sessions.
      this.sessionStreak = 0;
      this.closeOut = false;
      this.target = { r: RING_R0, hits: 0, attempts: 0, pop: 0 };
      this.buildTarget();
      this.placeTarget();
      this.targetText = addText('HITS 0/0', {
        top: 'calc(env(safe-area-inset-top) + 41px)',
        left: '50%',
        transform: 'translateX(-50%)',
        fontSize: '13px',
        fontWeight: '800',
        letterSpacing: '1.5px',
        padding: '3px 12px',
        borderRadius: '999px',
        backgroundColor: 'rgba(10, 18, 30, 0.45)',
        color: '#ffd24a'
      });
    }

    // ----- practice: the ball machine drill -----
    // A toggle in the top left corner hands the far end to a ball machine:
    // it lobs a steady supply of balls at a chosen pace — slow, medium or
    // fast — so passing and digging can be drilled without serving. The CPU
    // athlete stays on his feet the whole time, standing beside the feeder
    // working the drill, instead of vanishing while it runs.
    if (this.practice) {
      this.drill = false;
      this.pace = 'medium';
      this.buildMachine();
      this.drillBtn = addButton({
        icon: 'refresh-cw',
        label: 'Ball machine drill',
        onPress: () => this.toggleDrill(),
        style: {
          position: 'absolute',
          width: '46px',
          height: '46px',
          left: '16px',
          top: 'calc(env(safe-area-inset-top) + 12px)',
          backgroundColor: 'rgba(20, 40, 60, 0.5)'
        }
      });
      this.paceBtn = addButton({
        label: 'Feed pace',
        onPress: () => this.cyclePace(),
        style: {
          position: 'absolute',
          width: '92px',
          height: '46px',
          left: '70px',
          top: 'calc(env(safe-area-inset-top) + 12px)',
          borderRadius: '999px',
          backgroundColor: 'rgba(10, 18, 30, 0.55)',
          color: '#9fd8ff',
          fontSize: '12px',
          fontWeight: '800',
          letterSpacing: '1px',
          display: 'none'
        }
      });
      this.paceBtn.textContent = 'MEDIUM';
    }

    // ----- practice: the guided drill ladder -----
    // A whistle button under the pause hands practice a four-drill ladder:
    // serve timing, platform passing, steering and spike placement. The pill
    // under the score becomes the drill pill, showing the current drill and
    // its progress, and every drill passed banks a gold star on the career
    // record. The machine and the free rally stay exactly as they were —
    // the three ways to practice are mutually exclusive.
    if (this.practice) {
      this.ladder = false;
      this.drillIdx = 0;
      this.drillHits = 0;
      this.drillShots = 0;
      this.drillBanner = null;
      this.lastShot = null;
      this.ladderBtn = addButton({
        icon: 'list-checks',
        label: 'Guided drills',
        onPress: () => this.toggleLadder(),
        style: {
          position: 'absolute',
          width: '46px',
          height: '46px',
          left: '16px',
          top: 'calc(env(safe-area-inset-top) + 120px)',
          backgroundColor: 'rgba(20, 40, 60, 0.5)'
        }
      });
    }

    // ----- the pause button -----
    // A small corner control during any match. The top right belongs to the
    // close button in practice and the rally pill beside it, and the top
    // left to the drill toggle, so the pause sits top left in a match and
    // directly under the drill toggle in practice — clear of everything.
    this.paused = false;
    this.pauseBtn = addButton({
      icon: 'pause',
      label: 'Pause',
      onPress: () => this.togglePause(),
      style: {
        position: 'absolute',
        width: '46px',
        height: '46px',
        left: '16px',
        top: this.practice
          ? 'calc(env(safe-area-inset-top) + 66px)'
          : 'calc(env(safe-area-inset-top) + 12px)',
        backgroundColor: 'rgba(20, 40, 60, 0.5)'
      }
    });

    // ----- the turn control -----
    // A small control in the top-left stack: one tap turns the game a
    // quarter — upright, then one way, then the other — so a host that
    // presents the whole frame sideways when the device lies down can always
    // be met with an upright, landscape-playing match. Practice stacks it
    // under its own two top-left controls.
    this.turnBtn = addButton({
      icon: 'rotate-ccw',
      label: 'Turn the game',
      onPress: () => {
        cycleRotation();
        haptic('tick');
      },
      style: {
        position: 'absolute',
        width: '46px',
        height: '46px',
        left: '16px',
        top: this.practice
          ? 'calc(env(safe-area-inset-top) + 172px)'
          : 'calc(env(safe-area-inset-top) + 92px)',
        backgroundColor: 'rgba(20, 40, 60, 0.5)'
      }
    });

    // ----- the timeout pill -----
    // One timeout a set, spent from a small pill at the top right's stack —
    // scored matches with a CPU on the far court only: practice has nothing
    // to stall and a shared screen has nobody's run to break. The pill dims
    // once spent and refreshes with each set like the challenge pill.
    this.timeoutsLeft = 1;
    this.timeoutT = 0;
    if (!this.practice && !this.twoPlayer) {
      this.timeoutBtn = addButton({
        label: 'Call timeout',
        onPress: () => this.callTimeout(),
        style: {
          position: 'absolute',
          width: '84px',
          height: '26px',
          right: '16px',
          top: 'calc(env(safe-area-inset-top) + 96px)',
          borderRadius: '999px',
          backgroundColor: 'rgba(10, 18, 30, 0.45)',
          color: '#ffd24a',
          fontSize: '10px',
          fontWeight: '800',
          letterSpacing: '1px'
        }
      });
      this.timeoutBtn.textContent = 'TIMEOUT · 1';
    }

    // ----- power meter: fills while jump is held -----
    this.meterTrack = addText('', {
      right: '58px',
      bottom: 'calc(env(safe-area-inset-bottom) + 228px)',
      width: '14px',
      height: '106px',
      borderRadius: '7px',
      backgroundColor: 'rgba(20, 40, 60, 0.45)',
      border: '1px solid rgba(255,255,255,0.35)',
      opacity: '0'
    });
    this.meterFill = addText('', {
      right: '60px',
      bottom: 'calc(env(safe-area-inset-bottom) + 230px)',
      width: '10px',
      height: '0px',
      borderRadius: '5px',
      backgroundColor: '#ffd24a',
      opacity: '0'
    });

    // Player two reads their own charge on a mirrored meter by their button.
    if (this.twoPlayer || this.coop) {
      this.meterTrack2 = addText('', {
        left: '58px',
        bottom: 'calc(env(safe-area-inset-bottom) + 228px)',
        width: '14px',
        height: '106px',
        borderRadius: '7px',
        backgroundColor: 'rgba(20, 40, 60, 0.45)',
        border: '1px solid rgba(255,255,255,0.35)',
        opacity: '0'
      });
      this.meterFill2 = addText('', {
        left: '60px',
        bottom: 'calc(env(safe-area-inset-bottom) + 230px)',
        width: '10px',
        height: '0px',
        borderRadius: '5px',
        backgroundColor: '#ffd24a',
        opacity: '0'
      });
    }

    // The stamina bar: a slim gauge beside each side's charge meter, always
    // live — falling as sprints and jumps spend the legs, refilling while
    // they stand and between points. The far athlete's own bar rides their
    // meter in the shared-screen modes.
    this.stamTrack = addText('', {
      right: '44px',
      bottom: 'calc(env(safe-area-inset-bottom) + 228px)',
      width: '6px',
      height: '106px',
      borderRadius: '3px',
      backgroundColor: 'rgba(20, 40, 60, 0.55)'
    });
    this.stamFill = addText('', {
      left: '1px',
      right: '1px',
      bottom: '1px',
      height: '104px',
      borderRadius: '2px',
      backgroundColor: '#7ddb6a',
      pointerEvents: 'none'
    });
    this.stamTrack.appendChild(this.stamFill);
    if (this.twoPlayer || this.coop) {
      this.stamTrack2 = addText('', {
        left: '44px',
        bottom: 'calc(env(safe-area-inset-bottom) + 228px)',
        width: '6px',
        height: '106px',
        borderRadius: '3px',
        backgroundColor: 'rgba(20, 40, 60, 0.55)'
      });
      this.stamFill2 = addText('', {
        left: '1px',
        right: '1px',
        bottom: '1px',
        height: '104px',
        borderRadius: '2px',
        backgroundColor: '#7ddb6a',
        pointerEvents: 'none'
      });
      this.stamTrack2.appendChild(this.stamFill2);
    }

    // ----- touch input: drag anywhere to steer -----
    // `x`/`z` are what the athlete steers by — a gently filtered feed of the
    // drag — while `tx`/`tz` are where the finger currently points.
    this.input = { x: 0, z: 0, tx: 0, tz: 0 };
    this.charging = false;
    this.charge = 0;
    this.pointers = new Map();
    // The gesture is invisible, so it is named once: a small caption under the
    // court that fades the moment the first drag lands.
    this.moveHint = addText('DRAG ANYWHERE TO MOVE', {
      left: '0',
      right: '0',
      bottom: 'calc(env(safe-area-inset-bottom) + 148px)',
      textAlign: 'center',
      fontSize: '11px',
      fontWeight: '800',
      letterSpacing: '2px',
      color: 'rgba(255, 255, 255, 0.75)',
      textShadow: '0 1px 4px rgba(20, 40, 60, 0.6)',
      transition: 'opacity 0.4s ease',
      pointerEvents: 'none'
    });
    this.bindInput();

    // ----- match state -----
    // The match length picked on the title screen: the usual best of three
    // — sets to 7, two sets take it — or the MARATHON, five sets at 11 a
    // set. The cup, the daily and the ladder stay one set at 7 whatever it
    // says, and a 2-2 marathon split still goes to the golden tie-break.
    const len = selectedLength();
    const oneSet = !!(this.cupMatch || this.dailyMatch || this.ladderMatch);
    this.setsToWin = oneSet ? 1 : len.sets;
    this.setPoints = oneSet ? WIN_SCORE : len.points;
    // The blitz plays no sets at all: the set target sits far out of reach
    // so no set point can ever be called — the clock alone decides.
    if (this.blitz) this.setPoints = 99;
    // A set is first to its target points, and the athletes swap ends of the
    // court between sets.
    this.score = { player: 0, cpu: 0 };
    this.sets = { player: 0, cpu: 0 };
    // Set scores as they finished, the player's points first — the recap
    // reads them back, with the tie-break as the final set when it goes the
    // distance.
    this.setScores = [];
    // How far behind each side has fallen in the set under way: the worst of
    // it is kept, so a set taken from three or more points down reads as a
    // comeback.
    this.deficitMax = { player: 0, cpu: 0 };
    // A 1-1 split is decided by the golden tie-break instead of a third set.
    this.tieBreak = false;
    this.tieBanner = null;
    this.touches = { player: 0, cpu: 0 };
    this.server = 'player';
    // The athlete holding this serve: teams alternate — the player and the
    // partner trade the near side's turns, the two opponents the far side's.
    this.serverAth = this.player;
    // A series match after the first one: the loser of the previous match
    // serves the next fresh, whoever it was — the series already decided
    // who opens.
    if (this.seriesMatch) {
      const lost = seriesNextServer();
      if (lost) {
        this.server = lost;
        this.serverAth = lost === 'player' ? this.player : this.cpu;
      }
    }
    this.serverRot = { player: 0, cpu: 0 };
    this.state = 'serve';
    this.timer = 1.2;
    this.tossIgnoreRelease = false;
    this.tossWho = 'player';
    this.tossAth = this.player;
    // The second player's controls: their own drag, jump button, meter and
    // charge, driving the far athlete.
    this.input2 = { x: 0, z: 0, tx: 0, tz: 0 };
    this.wantJump2 = false;
    this.charging2 = false;
    this.charge2 = 0;
    this.tossIgnoreRelease2 = false;
    this.camBase = { y: 4.0, z: 9.2 };
    // The broadcast look point: the pan target the sideline camera eases
    // after — starting on the court centre so the first frame is framed.
    this.bcLook = new THREE.Vector3(0, 1.2, 0);
    this.playerSide = 1;
    // The camera's orbit: 0 sits behind the +z end. A side swap swings it
    // round the sideline instead of cutting through the net.
    this.camA = 0;
    this.camSwing = false;
    this.applySides();
    this.refreshScore();
    this.refreshTally();
    this.game.camera.position.set(0, this.camBase.y, this.playerSide * this.camBase.z);
    // The booth opens with the court, and the wind it will be played in.
    this.setMsg(this.practice
      ? `${this.theme.name} COURT — NO SCORE. LEARN THE METER, THE LOB, THE STEER, THE DIVE AND THE STRIKE. ${this.windCall()}.`
      : this.blitz
      ? `${this.theme.name} COURT — THREE MINUTES ON THE CLOCK. EVERY POINT COUNTS. ${this.windCall()}.`
      : `${this.theme.name} COURT — FORGET THE SCOREBOARD. ONE POINT AT A TIME. ${this.windCall()}.`);

    // ----- the announcing intro card -----
    // A stadium team sheet riding the pre-match sweep: it slides in from the
    // left as the camera lifts off, naming both athletes — their builds and
    // their speed and jump stats — with the mode's seeding (a cup round or
    // the day's daily draw when there is one, the signature style with it)
    // and the wind call beneath. It slides away as the camera lands, and a
    // tap that skips the sweep skips the card with it.
    this.introShown = false;
    // The scouting row: read off the record's match log — the head-to-head
    // against this opponent, the run either side is on, and how their aces
    // and spikes have landed across past meetings. A first meeting with a
    // signature style reads that style alone; the practice court and the
    // shared-screen modes scout nobody.
    const scout = this.scoutRival();
    const hasStyle = !!this.cpuStyle && !(scout && scout.styleOnly);
    // Every athlete on the sheet now carries their serve style too, so the
    // athlete rows grew a line apiece and the tail reads lower. The tail's
    // start follows the tallest sheet — the doubles card carries a third
    // athlete row — and everything below flows down from there.
    const tail = this.doubles || this.coop ? 228 : 164;
    const scoutTitleY = scout ? (hasStyle ? tail + 16 : tail) : 0;
    const scoutReadY = scout ? scoutTitleY + 26 : 0;
    const windY = scout ? scoutReadY + 40
      : hasStyle ? tail + 30
      : tail + 14;
    this.introCard = addText('', {
      left: '12px',
      top: '47%',
      width: '196px',
      height: `${windY + 26}px`,
      transform: 'translate(-230px, -50%)',
      padding: '12px 14px',
      borderRadius: '14px',
      backgroundColor: 'rgba(10, 18, 30, 0.72)',
      border: '1px solid rgba(255, 255, 255, 0.16)',
      transition: 'transform 0.45s ease, opacity 0.45s ease',
      opacity: '0',
      pointerEvents: 'none'
    });
    const seed = this.cupMatch
      ? `${this.cupMatch.doubles ? 'DOUBLES ' : ''}CUP · ROUND ${this.cupMatch.round} OF 3`
      : this.dailyMatch ? 'DAILY CHALLENGE'
      : this.ladderMatch ? `SEASON LADDER · RANK ${this.ladderMatch.rung}`
      : this.practice ? 'PRACTICE COURT'
      : this.blitz ? 'BLITZ · 3:00 ON THE CLOCK'
      : this.coop ? `CO-OP DOUBLES · ${this.diff.name}`
      : this.doubles ? `DOUBLES · ${this.diff.name}`
      : this.twoPlayer ? 'TWO PLAYERS'
      : `VS CPU · ${this.diff.name}`;
    this.introCard.appendChild(addText(seed, {
      left: '0', right: '0', top: '10px', textAlign: 'center',
      fontSize: '11px', fontWeight: '800', letterSpacing: '2px', color: '#ffd24a'
    }));
    const sheet = (role, stats, colour, y) => {
      this.introCard.appendChild(addText(`${role} · ${stats.name}`, {
        left: '0', top: `${y}px`, fontSize: '14px', fontWeight: '800',
        letterSpacing: '1px', color: colour
      }));
      this.introCard.appendChild(addText(stats.tag, {
        left: '0', top: `${y + 18}px`, fontSize: '10px',
        color: 'rgba(255, 255, 255, 0.55)'
      }));
      this.introCard.appendChild(addText(
        `SPD ${stats.speed.toFixed(1)} · JMP ${stats.jump.toFixed(1)}`, {
        left: '0', top: `${y + 32}px`, fontSize: '11px', fontWeight: '700',
        letterSpacing: '1px', color: 'rgba(255, 255, 255, 0.85)'
      }));
      // The serve style: how this athlete's serve reads before the match
      // starts — on either side of the net.
      this.introCard.appendChild(addText(
        `SERVE · ${stats.serve ? stats.serve.tag : '—'}`, {
        left: '0', top: `${y + 46}px`, fontSize: '9px', fontWeight: '800',
        letterSpacing: '1px', color: 'rgba(255, 255, 255, 0.65)'
      }));
    };
    sheet(playerName('p1'), this.playerStats, this.colPlayer, 36);
    if (this.coop) {
      const pk = playerColors('p2');
      sheet(playerName('p2'), this.partnerStats,
        `#${pk.jersey.toString(16).padStart(6, '0')}`, 100);
      sheet('OPPONENTS', this.cpuStats, this.colCpu, 164);
    } else if (this.doubles) {
      const pk = playerColors('partner');
      sheet('YOUR PARTNER', this.partnerStats,
        `#${pk.jersey.toString(16).padStart(6, '0')}`, 100);
      sheet('OPPONENTS', this.cpuStats, this.colCpu, 164);
    } else {
      sheet(this.twoPlayer ? playerName('p2') : 'CPU', this.cpuStats, this.colCpu, 100);
    }
    // The serving tactic named on the sheet: the formation the near pair
    // plays, in the doubles modes.
    if (this.doubles) {
      this.introCard.appendChild(addText(`FORMATION · ${selectedTactic().name}`, {
        left: '0', right: '0', top: '24px', textAlign: 'center',
        fontSize: '8px', fontWeight: '800', letterSpacing: '1.5px', color: '#ffd24a'
      }));
    }
    if (hasStyle) {
      this.introCard.appendChild(addText(`STYLE · ${this.cpuStats.style.tag}`, {
        left: '0', top: `${tail}px`, fontSize: '10px', fontWeight: '700',
        letterSpacing: '1px', color: '#ffd24a'
      }));
    }
    // The scouting row itself: the head-to-head with the run of results on
    // it, and the read off the meetings — their aces and spikes landed, and
    // which way the last one went.
    if (scout) {
      this.introCard.appendChild(addText(scout.title, {
        left: '0', right: '0', top: `${scoutTitleY}px`,
        fontSize: '9px', fontWeight: '800', letterSpacing: '1px',
        lineHeight: '1.35', color: '#ffd24a'
      }));
      this.introCard.appendChild(addText(scout.read, {
        left: '0', right: '0', top: `${scoutReadY}px`,
        fontSize: '9px', fontWeight: '700', lineHeight: '1.35',
        color: 'rgba(255, 255, 255, 0.85)'
      }));
    }
    this.introCard.appendChild(addText(this.windCall(), {
      left: '0', right: '0', top: `${windY}px`, textAlign: 'center',
      fontSize: '11px', fontWeight: '700', letterSpacing: '1px', color: '#9fd8ff'
    }));
  }

  /// The team sheet's scouting read, built from the record's match log —
  /// the opponent's head-to-head with the player, the run of results counting
  /// back from the last meeting, and the aces and spikes they have landed
  /// across those meetings, with the last one's result and score. A first
  /// meeting against a signature style reads that style alone; the practice
  /// court and the shared-screen modes scout nobody.
  scoutRival() {
    if (this.practice || this.twoPlayer || this.doubles) return null;
    const s = rivalScout(this.cpuStats.name.toUpperCase());
    if (s) {
      const run = s.streak >= 2
        ? ` · ${s.last.won ? 'YOU' : 'THEY'} TOOK ${s.streak} STRAIGHT` : '';
      return {
        title: `SCOUT · ${s.wins}W–${s.losses}L IN ${s.played}${run}`,
        read: `${s.aces} ACES · ${s.spikes} SPIKES LANDED — ` +
          `LAST WENT ${s.last.won ? 'TO YOU' : 'THEIR WAY'}`
      };
    }
    const tag = this.cpuStats.style && this.cpuStats.style.tag;
    if (!tag) return null;
    return {
      title: 'SCOUT · FIRST MEETING',
      read: `NO HISTORY ON RECORD — THEY PLAY ${tag}`,
      styleOnly: true
    };
  }

  // ---------------------------------------------------------------- world

  buildCourt() {
    // Outdoors: open sand out to the horizon — the dome and the haze take
    // over past the fog — with the lined court sitting on top of it.
    // Indoors: a smooth blue sports floor under the same lines, ringed by
    // dark walls beyond the terraces. Both floors take the shadows — and
    // indoors the ground is laid as a ring around the court, because the
    // court surface itself is polished to a shine and half-transparent: the
    // one window into the mirror world standing under it.
    const indoor = this.theme.indoor;
    let sand;
    if (indoor) {
      const shape = new THREE.Shape();
      shape.moveTo(-120, -120);
      shape.lineTo(120, -120);
      shape.lineTo(120, 120);
      shape.lineTo(-120, 120);
      const hole = new THREE.Path();
      hole.moveTo(-10.2, -9.2);
      hole.lineTo(10.2, -9.2);
      hole.lineTo(10.2, 9.2);
      hole.lineTo(-10.2, 9.2);
      shape.holes.push(hole);
      sand = new THREE.Mesh(
        new THREE.ShapeGeometry(shape),
        new THREE.MeshStandardMaterial({ color: 0x25405e, roughness: 0.92 })
      );
    } else {
      sand = new THREE.Mesh(
        new THREE.PlaneGeometry(240, 240),
        new THREE.MeshStandardMaterial({ map: makeSandTexture(), roughness: 1 })
      );
    }
    sand.rotation.x = -Math.PI / 2;
    sand.receiveShadow = true;
    this.root.add(sand);

    if (indoor) this.buildIndoorArena();

    const court = new THREE.Mesh(
      new THREE.PlaneGeometry(20, 18),
      indoor
        ? new THREE.MeshStandardMaterial({
            map: makeIndoorCourtTexture(),
            roughness: 0.35,
            envMapIntensity: 0.7,
            // Polished and half-transparent: the mirror world under the
            // floor reads through as the court's reflection.
            transparent: true,
            opacity: 0.66,
            depthWrite: false
          })
        : new THREE.MeshStandardMaterial({ map: makeCourtTexture(), roughness: 1 })
    );
    court.rotation.x = -Math.PI / 2;
    court.position.y = 0.012;
    court.receiveShadow = true;
    // Drawn after the mirror world, so the reflection blends in under the
    // surface rather than painting itself over it.
    if (indoor) court.renderOrder = 2;
    this.root.add(court);

    // The net: two steel posts, a white headband, a thin cable low down, and
    // a see-through mesh between them. The metal mirrors the sky.
    // The net's parts are collected as they are built: the indoor mirror
    // world copies each one.
    this.netParts = [];
    const postGeo = new THREE.CylinderGeometry(0.045, 0.055, 2.6, 8);
    const postMat = new THREE.MeshStandardMaterial({ color: 0x9fb2be, roughness: 0.2, metalness: 0.9 });
    for (const x of [-NET_HALF_W, NET_HALF_W]) {
      const post = new THREE.Mesh(postGeo, postMat);
      post.position.set(x, 1.3, 0);
      post.castShadow = true;
      this.root.add(post);
      this.netParts.push(post);
    }

    const band = new THREE.Mesh(
      new THREE.BoxGeometry(NET_HALF_W * 2, 0.075, 0.035),
      new THREE.MeshStandardMaterial({ color: 0xf2f2f2, roughness: 0.4, envMapIntensity: 0.8 })
    );
    band.position.set(0, NET_TOP, 0);
    band.castShadow = true;
    this.root.add(band);
    this.netParts.push(band);

    const cable = new THREE.Mesh(
      new THREE.BoxGeometry(NET_HALF_W * 2, 0.025, 0.025),
      new THREE.MeshStandardMaterial({ color: 0x3a4750, roughness: 0.3, metalness: 0.8 })
    );
    cable.position.set(0, 0.4, 0);
    this.root.add(cable);
    this.netParts.push(cable);

    // The mesh itself stays out of the shadow pass: a transparent plane would
    // drop a solid rectangle of shadow on the sand.
    this.netMesh = new THREE.Mesh(
      new THREE.PlaneGeometry(NET_HALF_W * 2, NET_TOP - 0.4),
      new THREE.MeshBasicMaterial({
        map: makeNetTexture(),
        transparent: true,
        alphaTest: 0.3,
        side: THREE.DoubleSide
      })
    );
    this.netMesh.position.set(0, (NET_TOP + 0.4) / 2, 0);
    this.root.add(this.netMesh);
    this.netParts.push(this.netMesh);
  }

  /// The indoor hall dressed like a real volleyball arena: the flat dark
  /// slabs become gym walls — a padded wainscot along the foot, a red accent
  /// stripe, panel seams and, on the far end, the house name with two
  /// championship banners — LED advertising boards ringing the court at
  /// floor level, a scoreboard hung on the far wall, and a dark ceiling
  /// carrying four rows of hall lights overhead.
  buildIndoorArena() {
    const g = new THREE.Group();
    this.root.add(g);

    // The four walls: the far end wears the house name and banners, the
    // other three the plain panel dress.
    const side = new THREE.MeshStandardMaterial({
      map: makeGymWallTexture(false), roughness: 0.9
    });
    const end = new THREE.MeshStandardMaterial({
      map: makeGymWallTexture(true), roughness: 0.9
    });
    const wall = (w, x, z, ry, mat) => {
      const m = new THREE.Mesh(new THREE.BoxGeometry(w, 11, 0.6), mat);
      m.position.set(x, 5.5, z);
      m.rotation.y = ry;
      g.add(m);
    };
    wall(38, 0, -16.5, 0, end);
    wall(38, 0, 16.5, 0, side);
    wall(34, 16.5, 0, Math.PI / 2, side);
    wall(34, -16.5, 0, Math.PI / 2, side);

    // The scoreboard: a dark LED panel hung above the stands on the far wall.
    const board = new THREE.Mesh(
      new THREE.BoxGeometry(6.4, 2.2, 0.35),
      new THREE.MeshBasicMaterial({ map: makeScoreboardTexture() })
    );
    board.position.set(0, 8.3, -16.15);
    g.add(board);

    // The advertising boards: court-wide runs on both ends and down both
    // sidelines, standing on the surround just short of the terraces. Unlit
    // material — they read as the LED panels they are.
    const adMat = new THREE.MeshBasicMaterial({ map: makeAdBoardTexture() });
    const long = new THREE.BoxGeometry(19, 0.95, 0.18);
    const deep = new THREE.BoxGeometry(18.4, 0.95, 0.18);
    for (const s of [1, -1]) {
      const endBoard = new THREE.Mesh(long, adMat);
      endBoard.position.set(0, 0.475, s * 9.55);
      g.add(endBoard);
      const sideBoard = new THREE.Mesh(deep, adMat);
      sideBoard.position.set(s * 10.55, 0.475, 0);
      sideBoard.rotation.y = Math.PI / 2;
      g.add(sideBoard);
    }

    // The roof: a dark deck closing the hall overhead, with four rows of
    // hall lights across it — seen on the flyover and at the top of frame.
    const deck = new THREE.Mesh(
      new THREE.PlaneGeometry(44, 36),
      new THREE.MeshBasicMaterial({ color: 0x0b1017 })
    );
    deck.rotation.x = Math.PI / 2;
    deck.position.y = 11.4;
    g.add(deck);
    const stripGeo = new THREE.BoxGeometry(15, 0.1, 0.55);
    const stripMat = new THREE.MeshBasicMaterial({ color: 0xf2ead4 });
    for (const z of [-7.4, -2.5, 2.5, 7.4]) {
      const strip = new THREE.Mesh(stripGeo, stripMat);
      strip.position.set(0, 11.2, z);
      g.add(strip);
    }
  }

  /// The mirror world under the indoor floor: the net, both athletes, the
  /// ball and the practice machine, built a second time inside a root that
  /// is flipped across the court surface — the flip does the mirroring, so
  /// every copy simply keeps the real thing's transforms, and what the
  /// camera sees through the polished, half-transparent court is the true
  /// planar reflection. The copies wear unlit, dimmed versions of their
  /// source materials: a reflection is an image, not lit geometry. Built
  /// only indoors; the beach courts keep their open sand.
  buildReflection() {
    const root = new THREE.Group();
    root.scale.y = -1;
    // The court surface sits 12 mm up — that is the mirror plane.
    root.position.y = 2 * 0.012;
    this.root.add(root);
    this.mirrorRoot = root;
    this.mirrorMats = [];
    const dim = (src, opacity) => {
      const mat = new THREE.MeshBasicMaterial({
        map: src.map || null,
        color: src.map ? 0xffffff : new THREE.Color(src.color).multiplyScalar(0.85),
        transparent: true,
        opacity,
        depthWrite: false,
        alphaTest: src.alphaTest || 0,
        side: src.side === THREE.DoubleSide ? THREE.DoubleSide : THREE.FrontSide
      });
      this.mirrorMats.push(mat);
      return mat;
    };
    const mirrorMesh = (mesh, opacity) => {
      const m = new THREE.Mesh(mesh.geometry, dim(mesh.material, opacity));
      m.position.copy(mesh.position);
      m.rotation.copy(mesh.rotation);
      m.scale.copy(mesh.scale);
      m.renderOrder = 1;
      m.frustumCulled = false;
      root.add(m);
      return m;
    };
    // The net and its steel: static, so one mirrored copy lasts the match.
    for (const part of this.netParts) {
      mirrorMesh(part, part.material.map ? 0.42 : 0.5);
    }
    // The athletes: fresh rigs wearing the same kits, posed node for node
    // from the real ones every frame.
    const athlete = (w, colors) => {
      const m = createAthlete(colors);
      m.traverse((o) => {
        if (!o.isMesh) return;
        o.castShadow = false;
        o.receiveShadow = false;
        o.frustumCulled = false;
        o.renderOrder = 1;
        const wasArray = Array.isArray(o.material);
        const mats = (wasArray ? o.material : [o.material]).map((s) => dim(s, 0.85));
        o.material = wasArray ? mats : mats[0];
      });
      m.visible = w.athlete.visible;
      root.add(m);
      return m;
    };
    this.player.mirror = athlete(this.player, playerColors('p1'));
    this.cpu.mirror = athlete(this.cpu, this.twoPlayer ? playerColors('p2') : this.cpuStats.colors);
    if (this.doubles) {
      this.partner.mirror = athlete(
        this.partner, this.coop ? playerColors('p2') : playerColors('partner')
      );
      this.cpu2.mirror = athlete(this.cpu2, this.cpu2Stats.colors);
    }
    // The ball shares the real ball's geometry, spin and squash.
    this.ball.mirror = mirrorMesh(this.ball.mesh, 0.85);
    // The ball machine, when practice brought one along: its reflection
    // follows the recoil and the drill toggle like the athletes do.
    if (this.machineGroup) {
      const m = this.machineGroup.clone(true);
      m.traverse((o) => {
        if (!o.isMesh) return;
        o.castShadow = false;
        o.renderOrder = 1;
        o.material = dim(o.material, 0.6);
      });
      root.add(m);
      this.machineMirror = m;
    }
  }

  buildAthletes() {
    const make = (id, side, colors, homeZ) => {
      const athlete = createAthlete(colors);
      athlete.position.set(0, 0, homeZ);
      // The models face local +z; the player turns around to face the net.
      athlete.rotation.y = side > 0 ? Math.PI : 0;
      this.root.add(athlete);
      return {
        id, side, athlete, vy: 0,
        moveMag: 0, runMag: 0, dir: { x: 0, z: 0 },
        dive: null, getUp: 0, launchCd: 0, strikeCd: 0,
        launched: false,
        superMeter: 0, superArmed: false,
        stamina: 1,
        home: new THREE.Vector3(0, 0, homeZ)
      };
    };

    // The player wears the kit picked on the title screen; the CPU keeps its
    // own roster colours, while in a two-player match the far athlete wears
    // player two's own picked kit and jersey number. Doubles adds a CPU
    // partner on the near court and a second opponent on the far one.
    this.player = make('player', 1, playerColors('p1'), 5.5);
    this.cpu = make('cpu', -1, this.twoPlayer ? playerColors('p2') : this.cpuStats.colors, -5.5);
    this.player.stats = this.playerStats;
    this.cpu.stats = this.cpuStats;
    if (this.doubles) {
      // In co-op the partner is player two: they wear their own picked kit,
      // exactly as the far athlete does in a two-player match.
      this.partner = make('partner', 1, this.coop ? playerColors('p2') : playerColors('partner'), 5.5);
      this.cpu2 = make('cpu2', -1, this.cpu2Stats.colors, -5.5);
      this.partner.stats = this.partnerStats;
      this.cpu2.stats = this.cpu2Stats;
    }

    for (const c of this.cpuTeam()) {
      c.think = 0;
      c.target = new THREE.Vector3(0, 0, c.home.z);
      c.wantJump = false;
      c.wantDive = false;
      c.wantLaunch = false;
      c.wantStrike = false;
    }
  }

  /// Every athlete the shared CPU loops run over — motion, bump passes —
  /// the far opponent always, and in the doubles modes the near partner and
  /// the second opponent too. The brains themselves plan cpuBrains().
  cpuTeam() {
    return this.doubles ? [this.partner, this.cpu, this.cpu2] : [this.cpu];
  }

  /// The far pair the CPU brains plan for: both opponents in the doubles
  /// modes — the near partner is player two's own athlete in co-op — and the
  /// single opponent in singles.
  cpuBrains() {
    return this.doubles ? [this.cpu, this.cpu2] : [this.cpu];
  }

  nearTeam() {
    return this.doubles ? [this.player, this.partner] : [this.player];
  }

  farTeam() {
    return this.doubles ? [this.cpu, this.cpu2] : [this.cpu];
  }

  allTeam() {
    return [...this.nearTeam(), ...this.farTeam()];
  }

  /// Which side of the scoreboard an athlete — or a touch id — plays for.
  sideOf(w) {
    return w.id === 'player' || w.id === 'partner' ? 'player' : 'cpu';
  }

  sideOfId(id) {
    return id === 'player' || id === 'partner' ? 'player' : 'cpu';
  }

  otherSide(s) {
    return s === 'player' ? 'cpu' : 'player';
  }

  buildBall() {
    const mesh = new THREE.Mesh(
      new THREE.SphereGeometry(BALL_R, 24, 18),
      new THREE.MeshStandardMaterial({ map: makeBallTexture(), roughness: 0.3, envMapIntensity: 1.15 })
    );
    mesh.castShadow = true;
    this.root.add(mesh);

    this.ball = {
      mesh,
      vel: new THREE.Vector3(),
      lastTouch: null,
      sinceTouch: 9,
      contactPause: 0,
      landed: false,
      sideSign: 0,
      pop: 0,
      squashDir: new THREE.Vector3(0, 1, 0),
      spinAxis: new THREE.Vector3(1, 0, 0),
      spinRate: 0,
      wasSpike: false,
      // A hand set in flight: the soft second touch a teammate's brain reads.
      handSet: false,
      // The in-flight spin state: the sideways bend a sidespun shot carries,
      // how hard a backspin float drags against its own pace, and how long
      // the bend has been building — all reset at every fresh touch.
      curve: new THREE.Vector3(),
      backDrag: 0,
      flightT: 0
    };
  }

  /// The aim arrow: a flat marker on the sand that shows where the charged
  /// shot would go with the current drag, stretching as the meter fills.
  buildAimArrow() {
    const geo = new THREE.BufferGeometry();
    geo.setAttribute(
      'position',
      new THREE.Float32BufferAttribute([0, 0, 1.2, -0.5, 0, -0.2, 0.5, 0, -0.2], 3)
    );
    this.aimArrow = new THREE.Mesh(
      geo,
      new THREE.MeshBasicMaterial({
        color: 0xffe066,
        transparent: true,
        opacity: 0.85,
        side: THREE.DoubleSide,
        depthWrite: false
      })
    );
    this.aimArrow.visible = false;
    this.aimArrow.renderOrder = 2;
    this.root.add(this.aimArrow);
    // The curve hint: a smaller, fainter copy of the arrow that appears off
    // the tip when the drag is swiping across the flight, angled the way the
    // ball will break.
    this.spinHint = new THREE.Mesh(
      geo,
      new THREE.MeshBasicMaterial({
        color: 0xffe066,
        transparent: true,
        opacity: 0,
        side: THREE.DoubleSide,
        depthWrite: false
      })
    );
    this.spinHint.visible = false;
    this.spinHint.renderOrder = 2;
    this.spinHint.scale.set(0.42, 1, 0.42);
    this.root.add(this.spinHint);
  }

  /// The breeze made visible: a pennant hung from the top of each net post,
  /// and a haze of fine sand drifting low across the court with the wind.
  buildWind() {
    const flagGeo = new THREE.BufferGeometry();
    flagGeo.setAttribute(
      'position',
      new THREE.Float32BufferAttribute(
        [0, 0.06, 0, 0, -0.27, 0, 0.62, -0.1, 0], 3
      )
    );
    flagGeo.computeVertexNormals();
    const flagMat = new THREE.MeshStandardMaterial({
      color: 0xd8453f, roughness: 0.85, side: THREE.DoubleSide
    });
    const capGeo = new THREE.CylinderGeometry(0.03, 0.03, 0.14, 6);
    const capMat = new THREE.MeshStandardMaterial({ color: 0x9fb2be, roughness: 0.25, metalness: 0.85 });
    this.pennants = [];
    for (const x of [-NET_HALF_W, NET_HALF_W]) {
      const g = new THREE.Group();
      g.position.set(x, 2.72, 0);
      const cap = new THREE.Mesh(capGeo, capMat);
      cap.position.y = -0.03;
      const flag = new THREE.Mesh(flagGeo, flagMat);
      g.add(cap, flag);
      this.root.add(g);
      this.pennants.push(g);
    }

    // The drifting sand haze: one instanced mesh, forty faint wisps hovering
    // just off the sand, riding the wind and wrapping round upwind when they
    // drift off the far edge.
    this.haze = new THREE.InstancedMesh(
      new THREE.PlaneGeometry(0.62, 0.36),
      new THREE.MeshBasicMaterial({
        color: 0xf7ecd8, transparent: true, opacity: 0.13, depthWrite: false
      }),
      40
    );
    this.haze.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    this.haze.frustumCulled = false;
    // Indoors the haze rides above the polished court's draw order, so the
    // see-through surface cannot dim it.
    this.haze.renderOrder = this.theme.indoor ? 3 : 1;
    this.root.add(this.haze);
    this.hazeSeeds = [];
    for (let i = 0; i < 40; i++) {
      this.hazeSeeds.push({
        d: Math.random() * 30 - 15,
        lane: Math.random() * 18 - 9,
        sp: Math.random(),
        ph: Math.random() * Math.PI * 2
      });
    }
    this.dummy = new THREE.Object3D();
  }

  /// Dresses the arena in the drawn theme: the sky panorama — doubled as the
  /// environment map that every material reflects — the fog, and the lights,
  /// with the key light casting the real shadows that go long at sunset.
  applyTheme() {
    const t = this.theme;
    // One painted panorama serves twice: wrapped on the dome, and reflected
    // by the ball, the steel and the athletes as the environment map.
    const skyTex = makeSkyTexture(t);
    skyTex.mapping = THREE.EquirectangularReflectionMapping;
    this.root.environment = skyTex;
    this.root.environmentIntensity = 0.85;
    this.buildSky(skyTex);
    // The haze takes over at the horizon: the fog fades the ground into the
    // same colour the sky meets it at.
    this.root.background = new THREE.Color(t.horizon);
    this.root.fog = new THREE.Fog(t.horizon, t.fogNear, t.fogFar);
    this.root.add(new THREE.AmbientLight(t.ambient[0], t.ambient[1]));
    const sun = new THREE.DirectionalLight(t.sun[0], t.sun[1]);
    sun.position.set(t.sun[2], t.sun[3], t.sun[4]);
    // Real shadows: one casting key light, its frustum tight around the court
    // so the shadow map stays sharp where it matters.
    sun.castShadow = true;
    sun.shadow.mapSize.set(1024, 1024);
    const sc = sun.shadow.camera;
    sc.left = -15;
    sc.right = 15;
    sc.top = 15;
    sc.bottom = -15;
    sc.near = 1;
    sc.far = 60;
    sc.updateProjectionMatrix();
    sun.shadow.bias = -0.0015;
    sun.shadow.normalBias = 0.02;
    this.root.add(sun);
    if (t.floods) this.buildFloodlights();
  }

  /// The sky dome: a giant inverted sphere painted with the theme's panorama —
  /// zenith down to horizon haze, sea below, the sun where the key light sits.
  /// It ignores the fog, so the gradient stays crisp above the haze line while
  /// the ground melts into it.
  buildSky(skyTex) {
    const dome = new THREE.Mesh(
      new THREE.SphereGeometry(180, 32, 24),
      new THREE.MeshBasicMaterial({
        map: skyTex,
        side: THREE.BackSide,
        fog: false
      })
    );
    this.root.add(dome);
  }

  /// Four floodlight poles at the corners of the court, each with a glowing
  /// lamp panel angled at the sand; two opposite corners carry real spotlights
  /// that do the actual lighting.
  buildFloodlights() {
    const poleGeo = new THREE.CylinderGeometry(0.07, 0.11, 7, 8);
    const poleMat = new THREE.MeshStandardMaterial({ color: 0x2b3440, roughness: 0.7, metalness: 0.4 });
    const backGeo = new THREE.BoxGeometry(1.25, 0.75, 0.3);
    const backMat = new THREE.MeshStandardMaterial({ color: 0x222a34, roughness: 0.6 });
    const lampGeo = new THREE.BoxGeometry(1.05, 0.55, 0.06);
    const lampMat = new THREE.MeshBasicMaterial({ color: 0xfff3cf });
    for (const [x, z] of [[-7.6, -9.6], [7.6, -9.6], [-7.6, 9.6], [7.6, 9.6]]) {
      const g = new THREE.Group();
      g.position.set(x, 0, z);
      g.rotation.y = Math.atan2(-x, -z);
      const pole = new THREE.Mesh(poleGeo, poleMat);
      pole.position.y = 3.5;
      const back = new THREE.Mesh(backGeo, backMat);
      back.position.set(0, 6.6, 0.12);
      const lamp = new THREE.Mesh(lampGeo, lampMat);
      lamp.position.set(0, 6.6, 0.3);
      lamp.rotation.x = 0.35;
      g.add(pole, back, lamp);
      this.root.add(g);
    }
    for (const [x, z] of [[-7.6, -9.6], [7.6, 9.6]]) {
      const spot = new THREE.SpotLight(0xdfe9ff, 34, 45, 0.62, 0.5, 1);
      spot.position.set(x, 6.6, z);
      spot.target.position.set(0, 0, 0);
      this.root.add(spot, spot.target);
    }
  }

  /// The style biases the CPU brain reads on top of its difficulty: where it
  /// stands and covers, how willingly it launches, lobs, toss-jumps its serve
  /// and attacks soft balls. A tier multiplier sharpens every willingness.
  styleBiases(st, sh) {
    return {
      homeT: st.homeT,
      coverT: st.coverT,
      netShadeT: st.netShadeT,
      launchChance: Math.min(1, st.launchChance * sh),
      lobChance: Math.min(1, st.lobChance * sh),
      serveJump: Math.min(1, st.serveJump * sh),
      serveHeat: st.serveHeat * sh,
      secondBall: Math.min(1, st.secondBall * sh)
    };
  }

  // ---------------------------------------------------------------- sides

  /// Where each athlete lives for the current set, which way they face, and
  /// which end the camera sits behind. Called at match start and after each
  /// set, when the sides swap.
  applySides() {
    const s = this.playerSide;
    this.player.home.set(0, 0, s * 5.5);
    this.faceSides();
    this.player.zLo = s > 0 ? 0.7 : -7.7;
    this.player.zHi = s > 0 ? 7.7 : -0.7;
    this.cpu.zLo = -this.player.zHi;
    this.cpu.zHi = -this.player.zLo;
    // A cup opponent's signature style lives at its own depth between
    // points: the net-hugger waits at the tape, the defender waits on the
    // baseline. Everyone else stands where they always did.
    this.cpu.home.set(0, 0, mix(
      this.cpu.zLo, this.cpu.zHi,
      this.cpuStyle ? this.cpuStyle.homeT : 0.314
    ));
    // The side each athlete attacks is the net-relative direction the bump
    // maths uses, so it has to follow the swap too.
    this.player.side = s;
    this.cpu.side = -s;
    // Everyone roams the whole width by default; doubles then hands the left
    // half of each court to its second athlete — cover bands the brains read
    // and movement clamps they hold.
    for (const w of this.allTeam()) {
      w.xLo = -4.6;
      w.xHi = 4.6;
      w.coverLo = -4.6;
      w.coverHi = 4.6;
    }
    if (this.doubles) {
      this.partner.side = s;
      this.partner.zLo = this.player.zLo;
      this.partner.zHi = this.player.zHi;
      this.cpu2.side = -s;
      this.cpu2.zLo = this.cpu.zLo;
      this.cpu2.zHi = this.cpu.zHi;
      this.cpu2.home.set(-1.35, 0, -s * 5.5);
      this.cpu2.xLo = -4.6;
      this.cpu2.xHi = -0.15;
      this.cpu2.coverLo = -4.6;
      this.cpu2.coverHi = -0.15;
      this.cpu.xLo = 0.15;
      this.cpu.coverLo = 0.15;
      // The serving tactic sets the near pair's formation: the classic
      // side-by-side rotation — partner left, player right — or the
      // stacking formation, where the pair line up together on one half at
      // the serve and the partner takes over the half the player would
      // normally hold. The cover bands and the MINE! call both read off it.
      if (selectedTactic().id === 'stacking') {
        this.partner.home.set(2.2, 0, s * 5.5);
        this.partner.xLo = 0.15;
        this.partner.xHi = 4.6;
        this.partner.coverLo = 0.15;
        this.partner.coverHi = 4.6;
        this.player.coverLo = -4.6;
        this.player.coverHi = -0.15;
      } else {
        this.partner.home.set(-1.35, 0, s * 5.5);
        this.partner.xLo = -4.6;
        this.partner.xHi = -0.15;
        this.partner.coverLo = -4.6;
        this.partner.coverHi = -0.15;
        this.player.coverLo = -0.15;
      }
    }
    // The strip shows the scores the way the ends now stand.
    this.refreshSetStrip();
  }

  /// Which way each athlete faces for the current set — the group yaw the
  /// strike maths and the run lean both read. Its own method so the replay
  /// can hand the live facing back once it is done with the recorded one.
  faceSides() {
    const s = this.playerSide;
    this.player.athlete.rotation.y = s > 0 ? Math.PI : 0;
    this.cpu.athlete.rotation.y = s > 0 ? 0 : Math.PI;
    if (this.doubles) {
      this.partner.athlete.rotation.y = s > 0 ? Math.PI : 0;
      this.cpu2.athlete.rotation.y = s > 0 ? 0 : Math.PI;
    }
  }

  // ---------------------------------------------------------------- loop

  update(dt) {
    // Paused: the whole simulation holds exactly mid-frame — no timers, no
    // slow motion, no athletes, not even the crowd or the breeze. The murmur
    // already faded out when the pause went up; it picks back up on resume.
    if (this.paused) return;
    // A timeout called: the match holds exactly where it is for a beat —
    // the murmur already settled when it was spent and the booth's call
    // holds the strip — then play picks up on the exact frame it froze on.
    if (this.timeoutT > 0) {
      this.timeoutT -= dt;
      return;
    }
    // Model mixers, the indoor mirror and the poses are presentation: a fault
    // in any of them must never stop the athletes or the ball from moving.
    try {
      updateModels(dt);
      this.updateReflections();
    } catch (error) {
      this.noteFault(error);
    }
    // The practice close-out owns the frame: the rally waits behind the dim.
    if (this.closeOut) return;
    // The pre-match flyover owns the frame: nothing simulates until the
    // camera has landed or the player taps it away.
    if (this.flyT > 0) {
      this.updateFlyover(dt);
      return;
    }
    // A replay owns the frame: nothing simulates while it is on screen.
    if (this.state === 'replay') {
      this.updateReplay(dt);
      return;
    }
    // A line-judge challenge owns the frame too: the overhead review replays
    // the close while nothing simulates.
    if (this.state === 'challenge') {
      this.updateChallenge(dt);
      return;
    }
    // The end-of-set huddle owns the frame for a few seconds, exactly like the
    // pre-match sweep — and is skipped by a tap the same way.
    if (this.huddle) {
      this.updateHuddle(dt);
      return;
    }
    // The victory lap owns the frame for a couple of seconds before the recap.
    if (this.victoryLap) {
      this.updateVictoryLap(dt);
      return;
    }
    // Whether this frame simulated live play — the instant a rally ends the
    // recording stops, so the buffer always ends on the last touch.
    const liveFrame = this.state === 'rally' || this.state === 'toss';
    // The big spike plays out in slow motion: the world stretches while the
    // timers and the camera keep running at full speed.
    if (this.slowT > 0) {
      this.slowT -= dt;
      if (this.slowT <= 0 && this.state === 'rally') this.setMsg('');
    }
    const sdt = this.slowT > 0 ? dt * 0.35 : dt;
    this.smoothInputs(dt);
    this.updatePlayer(sdt);
    // In the drill the machine owns the far end: the CPU sits the drill out.
    // In doubles the brains drive the partner and both opponents.
    if (this.twoPlayer) this.updatePlayer2(sdt);
    else if (this.coop) {
      // Co-op: player two drives the near partner while the brains run the
      // far pair only. The partner's body still gets its motion and bump
      // passes with the cpuTeam loop below.
      this.updatePlayer2(sdt);
      for (const c of this.cpuBrains()) this.updateCpuLike(c, sdt);
    } else if (!this.drill) for (const c of this.cpuTeam()) this.updateCpuLike(c, sdt);
    // The bodies are posed and the contacts resolved in a guard of their own:
    // a fault here must not stop the ball from flying or the states from
    // ticking, or a single bad pose would leave the athletes standing still.
    try {
      this.updateAthleteMotion(this.player, sdt);
      // The drill stands the brains down but the bodies keep living: the
      // athlete beside the machine idles, breathes and watches the feeds.
      for (const w of this.cpuTeam()) this.updateAthleteMotion(w, sdt);
      // Pose the approaching hand first, then resolve the actual contact.
      this.tryBump(this.player);
      if (!this.drill) for (const w of this.cpuTeam()) this.tryBump(w);
    } catch (error) {
      this.noteFault(error);
    }
    this.updateBall(sdt);
    this.updateStates(dt);
    this.updateClock(dt);
    this.updateRallyHud(dt);
    this.updateMomentum(dt);
    this.updateCamera(dt);
    this.updateMeter();
    this.updateStaminaHud();
    this.updateActionButtons();
    this.updateAim();
    // Presentation — the crowd, the breeze, the banner, the little readouts
    // and the booth's toasts — runs guarded as one block: a fault in any of it
    // can never take the simulation down with it.
    try {
      this.updateDrama(dt);
      this.updateSpotlight(dt);
      this.updateDrillBanner(dt);
    } catch (error) {
      this.noteFault(error);
    }
    this.updateFinale(dt);
    // A finale can hand the match straight to the title — the cup, the daily
    // and the ladder all own their own flow — which disposes this scene on
    // the spot, mid-update. Everything after this point belongs to whatever
    // scene is running now, so stop here rather than ticking a disposed
    // world: the marks pool, the stands and the flash are already gone.
    if (this.game.scene !== this) return;
    try {
      this.updateWind(dt);
      this.updateBanner(dt);
      this.updateCrowd(dt);
      this.updateMachine(dt);
      this.updateFlash(dt);
      this.updateMarks(dt);
      this.updateSpray(dt);
      this.updateTarget(dt);
      this.updateSpeedPop(dt);
      this.updateRallyPacePop(dt);
      // The call runs off the rally state itself now, not the partner's brain
      // loop — in co-op the near pair are both human and nobody plans them.
      if (this.callText) this.updatePartnerCall(dt);
      this.updatePartnerCallPop(dt);
      this.updateBadgeToast(dt);
      this.updateOpponentReact(dt);
      // The rolling record: a few seconds of every live rally, kept ready for
      // the slow-motion replay after a big point.
      if (liveFrame && !this.practice) this.recordFrame(dt);
    } catch (error) {
      this.noteFault(error);
    }
  }

  /// A fault in a guarded subsystem is named once in the runtime log and then
  /// left alone: the match keeps playing exactly as it was.
  noteFault(error) {
    if (this.faulted) return;
    this.faulted = true;
    console.error('Match subsystem failed:', error);
  }

  /// The steering read from the drag: the finger's own position is a target and
  /// the athlete steers on a lightly damped feed of it, so thumb tremor and an
  /// uneven event rate never show up as a jitter — while a real change of
  /// direction still lands within a few frames.
  smoothInputs(dt) {
    const k = Math.min(1, dt * 26);
    for (const input of [this.input, this.input2]) {
      input.x += (input.tx - input.x) * k;
      input.z += (input.tz - input.z) * k;
      if (Math.abs(input.x) < 0.002) input.x = 0;
      if (Math.abs(input.z) < 0.002) input.z = 0;
    }
  }

  updatePlayer(dt) {
    const p = this.player;
    const a = p.athlete;
    const grounded = a.position.y <= 0.001;
    // A launch only counts as one while its jumper is in the air: back on
    // the sand, a block is no longer in progress.
    if (grounded) p.launched = false;

    if (this.wantJump) {
      this.wantJump = false;
      if (this.state === 'serveReady' && this.server === 'player') {
        // First tap on the serve: the toss goes up.
        this.startToss();
      } else if (grounded && !p.getUp) {
        // The legs pay for the jump: an empty tank leaves the sand lower.
        p.vy = p.stats.jump * this.staminaJump(p);
        this.spendStamina(p, STAM_JUMP);
        haptic('jump');
      }
    }

    // The meter fills while the jump button is held and fades after release,
    // so a tap that lands just before contact still counts as a light lob.
    if (this.charging) {
      this.charge = Math.min(1, this.charge + dt / CHARGE_TIME);
    } else {
      this.charge = Math.max(0, this.charge - dt / CHARGE_DECAY);
    }

    // The launch, the dive and the strike, in order of desperation.
    p.launchCd = Math.max(0, p.launchCd - dt);
    p.strikeCd = Math.max(0, p.strikeCd - dt);
    if (this.wantLaunch) {
      this.wantLaunch = false;
      if (grounded && !p.getUp && p.launchCd <= 0) {
        p.launchCd = LAUNCH_CD;
        p.vy = p.stats.jump * LAUNCH_MULT * this.staminaJump(p);
        this.spendStamina(p, STAM_LAUNCH);
        p.launched = true;
        // The shove off the sand throws a puff up around the take-off.
        this.spawnSpray(a.position.x, a.position.z, 8,
          { spread: 1.0, up: 1.5, size: 1.1 });
        playSqueak();
        haptic('launch');
      }
    }
    if (this.wantSuper) {
      this.wantSuper = false;
      if (p.superMeter >= 1 && !p.superArmed) {
        p.superArmed = true;
        playZap();
        haptic('superarm');
        this.setMsg('SUPER STRIKE ARMED — YOUR NEXT HIT!');
      }
    }
    if (this.wantDive) {
      this.wantDive = false;
      this.startDive(p, this.diveDir(p, this.input));
    }
    if (this.wantStrike) {
      this.wantStrike = false;
      this.tryStrike(p, this.input, this.charge);
    }
    // Mid-dive or still picking themselves up: the dive owns the body.
    if (this.updateDiveState(p, dt)) return;

    p.vy -= G * dt;
    // Drag directions stay screen-relative after a side swap: down always
    // pulls the athlete back toward the camera. The drag names a pace and a
    // direction; the body eases into both and eases back out of them, so
    // starts and stops carry weight instead of teleporting.
    const wx = this.input.x * this.playerSide;
    const wz = this.input.z * this.playerSide;
    const len = Math.hypot(wx, wz);
    const raw = Math.min(1, len);
    // Ease into the pace and back out of it: a sprint picks up within a couple
    // of frames, a stop settles instead of snapping.
    p.runMag += (raw - p.runMag) * Math.min(1, dt * (raw > p.runMag ? 13 : 12));
    if (len > 0.02) {
      p.dir.x = wx / len;
      p.dir.z = wz / len;
    }
    a.position.x = clamp(
      a.position.x + p.dir.x * p.runMag * p.stats.speed * this.staminaScale(p) * this.talkSpeed(p) * dt,
      -4.6, 4.6
    );
    a.position.z = clamp(
      a.position.z + p.dir.z * p.runMag * p.stats.speed * this.staminaScale(p) * this.talkSpeed(p) * dt,
      p.zLo, p.zHi
    );
    a.position.y = Math.max(0, a.position.y + p.vy * dt);
    if (a.position.y === 0 && p.vy < 0) {
      // A real landing kicks the surface up — a launch's landing is bigger.
      if (p.vy < -2.2) {
        this.spawnSpray(a.position.x, a.position.z, p.launched ? 10 : 4,
          { spread: 1.1, up: 1.0, size: p.launched ? 1.2 : 0.8 });
      }
      // A hard landing: sneakers squeak and the camera feels it a little.
      if (p.vy < -3.4) {
        playSqueak();
        this.camKick = Math.max(this.camKick, 0.22);
      }
      p.vy = 0;
    }

    // A NaN anywhere in the run maths would pin the athlete for good: every
    // later frame adds to it and stays NaN, which reads to the player as an
    // athlete who simply will not move. Take them back home instead.
    if (!Number.isFinite(a.position.x) || !Number.isFinite(a.position.z) ||
        !Number.isFinite(a.position.y) || !Number.isFinite(p.stamina)) {
      a.position.copy(p.home);
      p.vy = 0;
      p.runMag = 0;
      p.dir.x = 0;
      p.dir.z = 0;
      p.stamina = 1;
    }
    p.moveMag = raw;
    // The sprint spends the legs; standing gives them back.
    this.updateStamina(p, dt, raw > 0.05);
    // A long rally's sprint leaves little kick-ups at each stride.
    p.sprayT = (p.sprayT || 0) - dt;
    if (this.state === 'rally' && this.rallyLen >= 6 &&
        raw > 0.55 && p.sprayT <= 0) {
      p.sprayT = 0.26 + Math.random() * 0.1;
      this.spawnSpray(
        a.position.x - p.dir.x * 0.22, a.position.z - p.dir.z * 0.22, 2,
        { spread: 0.45, up: 0.7, size: 0.55 }
      );
    }
  }

  /// The second athlete, driven by the second player: the same movement, jump
  /// and charge as player one, from a drag zone on the right of the screen and
  /// a jump button inset at the bottom left. In a two-player match that is the
  /// far athlete; in co-op doubles it is the near partner.
  updatePlayer2(dt) {
    const c = this.coop ? this.partner : this.cpu;
    const a = c.athlete;
    const grounded = a.position.y <= 0.001;
    if (grounded) c.launched = false;

    if (this.wantJump2) {
      this.wantJump2 = false;
      if (this.state === 'serveReady' &&
          (this.server === 'cpu' || (this.coop && this.serverAth === c))) {
        // First tap on the serve: the toss goes up.
        this.startTossCpu(c);
      } else if (grounded && !c.getUp) {
        // The legs pay for the jump: an empty tank leaves the sand lower.
        c.vy = c.stats.jump * this.staminaJump(c);
        this.spendStamina(c, STAM_JUMP);
        haptic('jump');
      }
    }

    if (this.charging2) {
      this.charge2 = Math.min(1, this.charge2 + dt / CHARGE_TIME);
    } else {
      this.charge2 = Math.max(0, this.charge2 - dt / CHARGE_DECAY);
    }

    // The far athlete's own three moves, mirrored.
    c.launchCd = Math.max(0, c.launchCd - dt);
    c.strikeCd = Math.max(0, c.strikeCd - dt);
    if (this.wantLaunch2) {
      this.wantLaunch2 = false;
      if (grounded && !c.getUp && c.launchCd <= 0) {
        c.launchCd = LAUNCH_CD;
        c.vy = c.stats.jump * LAUNCH_MULT * this.staminaJump(c);
        this.spendStamina(c, STAM_LAUNCH);
        c.launched = true;
        // The puff off the sand at the take-off, mirrored for player two.
        this.spawnSpray(a.position.x, a.position.z, 8,
          { spread: 1.0, up: 1.5, size: 1.1 });
        playSqueak();
        haptic('launch');
      }
    }
    if (this.wantSuper2) {
      this.wantSuper2 = false;
      if (c.superMeter >= 1 && !c.superArmed) {
        c.superArmed = true;
        playZap();
        haptic('superarm');
        this.setMsg('SUPER STRIKE ARMED — P2, YOUR NEXT HIT!');
      }
    }
    if (this.wantDive2) {
      this.wantDive2 = false;
      this.startDive(c, this.diveDir(c, this.input2));
    }
    if (this.wantStrike2) {
      this.wantStrike2 = false;
      this.tryStrike(c, this.input2, this.charge2);
    }
    if (this.updateDiveState(c, dt)) return;

    c.vy -= G * dt;
    // Screen-relative exactly like player one: drag right moves the athlete
    // right on the screen and drag down pulls them toward the camera,
    // whichever end the set is being played from — with the same eased pace,
    // so their body accelerates and brakes like a person too.
    const wx2 = this.input2.x * this.playerSide;
    const wz2 = this.input2.z * this.playerSide;
    const len2 = Math.hypot(wx2, wz2);
    const raw2 = Math.min(1, len2);
    c.runMag += (raw2 - c.runMag) * Math.min(1, dt * (raw2 > c.runMag ? 13 : 12));
    if (len2 > 0.02) {
      c.dir.x = wx2 / len2;
      c.dir.z = wz2 / len2;
    }
    a.position.x = clamp(
      a.position.x + c.dir.x * c.runMag * c.stats.speed * this.staminaScale(c) * this.talkSpeed(c) * dt,
      -4.6, 4.6
    );
    a.position.z = clamp(
      a.position.z + c.dir.z * c.runMag * c.stats.speed * this.staminaScale(c) * this.talkSpeed(c) * dt,
      c.zLo, c.zHi
    );
    a.position.y = Math.max(0, a.position.y + c.vy * dt);
    if (a.position.y === 0 && c.vy < 0) {
      // The landing off a launch takes its own puff.
      if (c.vy < -2.2) {
        this.spawnSpray(a.position.x, a.position.z, c.launched ? 10 : 4,
          { spread: 1.1, up: 1.0, size: c.launched ? 1.2 : 0.8 });
      }
      if (c.vy < -3.4) playSqueak();
      c.vy = 0;
    }

    c.moveMag = raw2;
    // The sprint spends the legs; standing gives them back.
    this.updateStamina(c, dt, raw2 > 0.05);
    // The same stride kick-ups as player one's, in a long rally.
    c.sprayT = (c.sprayT || 0) - dt;
    if (this.state === 'rally' && this.rallyLen >= 6 &&
        raw2 > 0.55 && c.sprayT <= 0) {
      c.sprayT = 0.26 + Math.random() * 0.1;
      this.spawnSpray(
        a.position.x - c.dir.x * 0.22, a.position.z - c.dir.z * 0.22, 2,
        { spread: 0.45, up: 0.7, size: 0.55 }
      );
    }
  }

  updateCpuLike(c, dt) {
    const a = c.athlete;

    // Its own toss is up: the jump-serve routine runs the show until the
    // strike lands.
    if (this.state === 'toss' && this.tossAth === c && !this.twoPlayer) {
      this.updateCpuServe(c, dt);
      return;
    }

    c.think -= dt;
    if (c.think <= 0) {
      c.think = this.diff.think;
      this.planCpu(c);
    }

    const grounded = a.position.y <= 0.001;
    if (grounded) c.launched = false;
    if (c.wantJump && grounded) {
      c.wantJump = false;
      // The legs pay for the jump, the CPU's meter reading like anyone's.
      c.vy = c.stats.jump * 0.95 * this.staminaJump(c);
      this.spendStamina(c, STAM_JUMP);
    }

    c.launchCd = Math.max(0, c.launchCd - dt);
    c.strikeCd = Math.max(0, c.strikeCd - dt);
    if (c.wantDive) {
      c.wantDive = false;
      this.startDive(c, this.diveDir(c, { x: 0, z: 0 }));
    }
    if (c.wantLaunch) {
      c.wantLaunch = false;
      if (grounded && c.launchCd <= 0) {
        c.launchCd = LAUNCH_CD;
        c.vy = c.stats.jump * 1.4 * this.staminaJump(c);
        this.spendStamina(c, STAM_LAUNCH);
        c.launched = true;
        // The CPU's shove kicks the surface up like anyone's launch does.
        this.spawnSpray(a.position.x, a.position.z, 8,
          { spread: 1.0, up: 1.5, size: 1.1 });
      }
    }
    // The strike move: the serve ace's second-ball attack fires here, flat
    // and aimed with the same error its bump aims with.
    if (c.wantStrike) {
      c.wantStrike = false;
      const steer = 6.5 + 9 * 0.45;
      const tx = clamp(
        (Math.random() * 5.2 - 2.6) + (Math.random() - 0.5) * 2 * this.diff.aimError,
        -3.6, 3.6
      );
      this.tryStrike(c, { x: tx / (this.playerSide * steer), z: 0 }, 0.45);
    }
    // Mid-dive or getting up: the CPU goes nowhere until it is standing.
    if (this.updateDiveState(c, dt)) return;

    c.vy -= G * dt;
    // The CPU plays slower than its own build; the difficulty scales how much.
    // Its pace eases in and out of its targets and its direction turns rather
    // than snapping, so it reads as a person chasing the ball. In practice a
    // long rally sharpens it — see cpuSharpness. In doubles each athlete also
    // holds their own half of the court. The stamina meter reads on top of it
    // all: a tired opponent runs heavy, whoever drives them.
    const cpuSpeed =
      c.stats.speed * this.diff.speedScale * this.cpuSharpness() *
      this.staminaScale(c) * this.talkSpeed(c);
    const dx = c.target.x - a.position.x;
    const dz = c.target.z - a.position.z;
    const dist = Math.hypot(dx, dz);
    c.runMag += ((dist > 0.08 ? 1 : 0) - c.runMag) * Math.min(1, dt * 8);
    if (dist > 0.08) {
      const turn = Math.min(1, dt * 10);
      c.dir.x += (dx / dist - c.dir.x) * turn;
      c.dir.z += (dz / dist - c.dir.z) * turn;
      const step = Math.min(dist, cpuSpeed * c.runMag * dt);
      a.position.x = clamp(a.position.x + c.dir.x * step, c.xLo, c.xHi);
      a.position.z += c.dir.z * step;
    }
    c.moveMag = c.runMag;
    // The sprint spends the legs; standing gives them back.
    this.updateStamina(c, dt, c.runMag > 0.05);
    // The same stride kick-ups at the CPU's feet in a long rally.
    c.sprayT = (c.sprayT || 0) - dt;
    if (this.state === 'rally' && this.rallyLen >= 6 &&
        c.runMag > 0.6 && c.sprayT <= 0) {
      c.sprayT = 0.26 + Math.random() * 0.1;
      this.spawnSpray(
        a.position.x - c.dir.x * 0.22, a.position.z - c.dir.z * 0.22, 2,
        { spread: 0.45, up: 0.7, size: 0.55 }
      );
    }

    a.position.y = Math.max(0, a.position.y + c.vy * dt);
    if (a.position.y === 0 && c.vy < 0) {
      // The landing off a launch takes its own puff.
      if (c.vy < -2.2) {
        this.spawnSpray(a.position.x, a.position.z, c.launched ? 10 : 4,
          { spread: 1.1, up: 1.0, size: c.launched ? 1.2 : 0.8 });
      }
      if (c.vy < -3.4) playSqueak();
      c.vy = 0;
    }
  }

  /// A CPU toss, once it has chosen to jump serve: it holds its spot, rises
  /// to meet the ball a beat before the strike, and swings at the top of the
  /// toss — struck much later, the serve floats instead.
  updateCpuServe(c, dt) {
    const a = c.athlete;

    this.cpuServeT -= dt;
    if (this.cpuServeT < 0.16 && a.position.y <= 0.001 && !this.cpuServeJumped) {
      // The jump serve is hit in the air: take off just before the strike.
      this.cpuServeJumped = true;
      // The legs pay for the serve jump like any other.
      c.vy = c.stats.jump * 0.95 * this.staminaJump(c);
      this.spendStamina(c, STAM_JUMP);
    }
    c.vy -= G * dt;
    a.position.y = Math.max(0, a.position.y + c.vy * dt);
    if (a.position.y === 0 && c.vy < 0) c.vy = 0;
    c.moveMag = 0;
    c.runMag = 0;

    if (this.cpuServeT > 0) return;
    // If the timing was early, wait for the toss to reach the striking hand.
    if (!canStrikeBall(a, this.ball.mesh.position)) return;
    this.cpuServeT = 9; // one strike only, however long the ball hangs on
    const jumpServe = this.ball.mesh.position.y >= this.tossApex - 0.8;
    // The rally is live from the instant the ball is struck.
    this.state = 'rally';
    playWhistle();
    this.setMsg('');
    this.cpuServeLaunch(c, jumpServe);
  }

  /// The CPU's strike on its own toss — the same launch maths as the player's
  /// serve, with its aim error choosing where it lands instead of a drag.
  cpuServeLaunch(c, jumpServe) {
    const d = this.diff;
    // The serve ace hits its jump serve hotter than the level alone would.
    const heat = this.cpuStyle ? this.cpuStyle.serveHeat : 0;
    const charge = jumpServe
      ? Math.min(1, 0.8 + Math.random() * 0.2 + heat)
      : 0.05;
    // The server's signature loosens or tightens the level's aim with it.
    const sig = this.serveSignature(c);
    const tx = (Math.random() * 5.2 - 2.6) +
      (Math.random() - 0.5) * 2 * d.aimError * (sig ? sig.aim : 1);
    // The launch steers off a drag: feed it the drag that points where the
    // CPU meant to put the serve.
    const steer = 6.5 + 9 * charge;
    const input = { x: clamp(tx, -3.6, 3.6) / (this.playerSide * steer), z: 0 };
    this.serveLaunch(c, input, charge, jumpServe);
  }

  /// The call: when a live ball is coming down inside a half of the near
  /// court, a gold pill pops over the athlete it belongs to — MINE! from the
  /// CPU partner in doubles, the owner's own name in co-op — on a cooldown
  /// so it never nags.
  updatePartnerCall(dt) {
    this.callT = Math.max(0, this.callT - dt);
    const b = this.ball;
    if (!this.callText || this.callT > 0 || this.state !== 'rally' || b.landed) return;
    const pos = b.mesh.position;
    // Only a ball coming down on the near court is anyone's to call.
    if (pos.z * this.playerSide < -0.1) return;
    const dy = Math.max(0, pos.y - 1.3);
    const t = (b.vel.y + Math.sqrt(b.vel.y * b.vel.y + 2 * G * dy)) / G;
    const px = pos.x + b.vel.x * t;
    if (this.coop) {
      // Two humans share the near court, each with their own half: the call
      // names whoever's half the ball is dropping into, over that athlete's
      // head — the spoken version of the CPU partner's MINE!, so neither
      // player has to guess whose ball it is. Once the team has touched the
      // ball the next touch belongs to the teammate who didn't touch it last
      // — the setter while it drops, the attacker once a hand set hangs —
      // and the call names them instead, so nobody converges on the same ball.
      const owner = this.chaserFor(this.nearTeam(), px);
      const taker = this.touches.player >= 1 && b.lastTouch &&
        this.sideOfId(b.lastTouch) === 'player'
        ? this.nearTeam().find((m) => m.id !== b.lastTouch) || owner
        : owner;
      this.callT = 2.4;
      this.callPop = { t: 0, ath: taker.athlete };
      this.callText.textContent =
        selectedName(taker.id === 'player' ? 'p1' : 'p2') ||
        (taker.id === 'player' ? 'P1' : 'P2');
      return;
    }
    const near = Math.hypot(
      pos.x - this.partner.athlete.position.x,
      pos.z - this.partner.athlete.position.z
    ) < 1.5;
    // The call follows the serving tactic's bands: in rotation the partner
    // owns the left half and calls its drops; stacked, they own the right.
    const mine = selectedTactic().id === 'stacking' ? px >= 0.15 : px < -0.15;
    if (!mine && !near) return;
    this.callT = 2.4;
    this.callPop = { t: 0 };
    this.callText.textContent = 'MINE!';
  }

  /// The call pill itself: projected over the partner's head, drifting up as
  /// it fades.
  updatePartnerCallPop(dt) {
    if (!this.callPop) return;
    const s = this.callPop;
    s.t += dt;
    if (s.t >= 1.1) {
      this.callText.style.opacity = '0';
      this.callPop = null;
      return;
    }
    const a = (this.callPop && this.callPop.ath) || this.partner.athlete;
    this.tmp.set(a.position.x, a.position.y + 2.15, a.position.z).project(this.game.camera);
    const x = (this.tmp.x * 0.5 + 0.5) * this.viewW;
    const y = (-this.tmp.y * 0.5 + 0.5) * this.viewH;
    this.callText.style.left = `${Math.round(x)}px`;
    this.callText.style.top = `${Math.round(y - s.t * 16)}px`;
    this.callText.style.opacity = Math.min(
      clamp(s.t / 0.08, 0, 1), clamp((1.1 - s.t) / 0.3, 0, 1)
    ).toFixed(2);
  }

  /// The CPU's toss, once it has chosen to jump serve: it holds its spot,
  /// rises to meet the ball a beat before the strike, and swings at the top
  /// of the toss — struck much later, the serve floats instead.
  updateCpuServeRetired(dt) {
    const a = this.cpu.athlete;

    this.cpuServeT -= dt;
    if (this.cpuServeT < 0.16 && a.position.y <= 0.001 && !this.cpuServeJumped) {
      // The jump serve is hit in the air: take off just before the strike.
      this.cpuServeJumped = true;
      this.cpu.vy = this.cpu.stats.jump * 0.95;
    }
    this.cpu.vy -= G * dt;
    a.position.y = Math.max(0, a.position.y + this.cpu.vy * dt);
    if (a.position.y === 0 && this.cpu.vy < 0) this.cpu.vy = 0;
    this.cpu.moveMag = 0;
    this.cpu.runMag = 0;

    if (this.cpuServeT > 0) return;
    // If the timing was early, wait for the toss to reach the striking hand.
    if (!canStrikeBall(a, this.ball.mesh.position)) return;
    this.cpuServeT = 9; // one strike only, however long the ball hangs on
    const jumpServe = this.ball.mesh.position.y >= this.tossApex - 0.8;
    // The rally is live from the instant the ball is struck.
    this.state = 'rally';
    playWhistle();
    this.setMsg('');
    this.cpuServeLaunchRetired(jumpServe);
  }

  /// The CPU's strike on its own toss — the same launch maths as the player's
  /// serve, with its aim error choosing where it lands instead of a drag.
  cpuServeLaunchRetired(jumpServe) {
    const d = this.diff;
    // The serve ace hits its jump serve hotter than the level alone would.
    const heat = this.cpuStyle ? this.cpuStyle.serveHeat : 0;
    const charge = jumpServe
      ? Math.min(1, 0.8 + Math.random() * 0.2 + heat)
      : 0.05;
    // The server's signature loosens or tightens the level's aim with it.
    const sig = this.serveSignature(this.cpu);
    const tx = (Math.random() * 5.2 - 2.6) +
      (Math.random() - 0.5) * 2 * d.aimError * (sig ? sig.aim : 1);
    // The launch steers off a drag: feed it the drag that points where the
    // CPU meant to put the serve.
    const steer = 6.5 + 9 * charge;
    const input = { x: clamp(tx, -3.6, 3.6) / (this.playerSide * steer), z: 0 };
    this.serveLaunch(this.cpu, input, charge, jumpServe);
  }

  /// The survival streak's bite: in practice the CPU quietly plays a touch
  /// sharper the longer the rally runs past twelve touches — a little more
  /// pace, a wider reaction and a steadier read on the ball — so long
  /// streaks take real work. Everywhere else it plays exactly its level.
  cpuSharpness() {
    if (!this.practice) return 1;
    return 1 + Math.min(0.3, Math.max(0, this.rallyLen - 12) * 0.02);
  }

  // ---------------------------------------------------------------- stamina

  /// The stamina ledger: running drains the legs, standing refills them.
  /// Called once per athlete per frame from whichever loop owns their body —
  /// the player's, player two's and the CPU brains' alike — so every athlete
  /// plays by the same meter.
  updateStamina(w, dt, moving) {
    if (moving) w.stamina = Math.max(0, w.stamina - STAM_DRAIN * dt);
    else w.stamina = Math.min(1, w.stamina + STAM_REGEN * dt);
  }

  /// A jump or a launch spent from the tank outright, at the moment of
  /// take-off.
  spendStamina(w, cost) {
    w.stamina = Math.max(0, w.stamina - cost);
  }

  /// The legs' share of the pace: full stamina runs at full speed, an empty
  /// tank at its floor.
  staminaScale(w) {
    return STAM_SPEED + (1 - STAM_SPEED) * w.stamina;
  }

  /// ...and of the lift: a tired jump clears less.
  staminaJump(w) {
    return STAM_JUMP_LOSS + (1 - STAM_JUMP_LOSS) * w.stamina;
  }

  /// Where a CPU athlete stands and when it jumps, re-decided a few times a
  /// second — the small delay is what keeps it human. Each athlete reads the
  /// net relative to its own side, so the same brain drives both teams. In
  /// doubles each athlete holds their own half, and a landing belongs to
  /// whoever's half it drops in.
  planCpu(c) {
    const a = c.athlete;
    const b = this.ball;

    if (this.state !== 'rally' || b.landed) {
      c.target.set(b.mesh.position.x * 0.2, 0, c.home.z);
      c.wantJump = false;
      c.wantDive = false;
      c.wantLaunch = false;
      c.wantStrike = false;
      return;
    }

    const pos = b.mesh.position;
    // A teammate's hand set still hanging on its own side of the net: the
    // partner reads it, runs onto the set and takes off under its descent to
    // swing — the second touch played the way it was given. The chase keeps
    // to the partner's own half, and the MINE! call goes up with the read so
    // the player knows whose ball it is.
    if (this.doubles && c === this.partner && b.handSet &&
        pos.z * c.side > -0.1 && this.sideOfId(b.lastTouch) === 'player') {
      const dy = Math.max(0, pos.y - 1.3);
      const t = (b.vel.y + Math.sqrt(Math.max(0, b.vel.y * b.vel.y + 2 * G * dy))) / G;
      const landX = pos.x + b.vel.x * t;
      c.target.set(clamp(landX, c.xLo, c.xHi), 0,
        clamp(pos.z + b.vel.z * t, c.zLo, c.zHi));
      c.wantJump =
        a.position.y <= 0.001 && !c.getUp &&
        pos.y > 2.4 && pos.y < 5.6 && b.vel.y < -1 &&
        (pos.x - a.position.x) ** 2 + (pos.z - a.position.z) ** 2 < 2.2;
      c.wantDive = false;
      c.wantLaunch = false;
      c.wantStrike = false;
      if (this.callText && this.callT <= 0 &&
          landX >= c.coverLo - 0.2 && landX <= c.coverHi + 0.2) {
        this.callT = 2.4;
        this.callPop = { t: 0 };
        this.callText.textContent = 'MINE!';
      }
      return;
    }
    if (pos.z * c.side > -0.1) {
      // Ball is on this athlete's own side: cover the depth the style lives
      // at — a net-hugger waits at the tape, a defender waits on the
      // baseline, and a plain CPU covers its home spot as it always has. In
      // doubles the cover keeps to the athlete's own half.
      c.target.set(
        this.doubles ? clamp(pos.x * 0.3, c.xLo, c.xHi) : clamp(pos.x * 0.3, -3.2, 3.2),
        0,
        this.cpuStyle ? mix(c.zLo, c.zHi, this.cpuStyle.coverT) : c.home.z
      );
      c.wantJump = false;
      return;
    }

    // Predict where the ball will be when it drops to bump height, by solving
    // the fall time from its current arc.
    const dy = pos.y - 1.3;
    const disc = b.vel.y * b.vel.y + 2 * G * Math.max(0, dy);
    const t = (b.vel.y + Math.sqrt(disc)) / G;

    let px = pos.x + b.vel.x * t;
    let pz = pos.z + b.vel.z * t;
    if (pz * c.side < 0.55) {
      // It is drifting into the net or back over: shade toward the net
      // instead — how tight to the tape it shades is the style's call.
      px = clamp(pos.x * 0.6, -3.4, 3.4);
      pz = -c.side *
        mix(-0.7, -7.7, this.cpuStyle ? this.cpuStyle.netShadeT : 0.24);
    }
    // Doubles: the landing belongs to whoever's half it drops in — read off
    // the shared prediction before each athlete's own error is added, so
    // teammates always agree on who takes it.
    const chase = !this.doubles || this.chaserFor(
      c.side === this.playerSide ? this.nearTeam() : this.farTeam(), px
    ) === c;
    // Prediction error: the CPU runs for a point near the landing spot, and
    // the wobble in that guess shrinks as the difficulty rises — and, in
    // practice, as the survival streak grows past twelve.
    const d = this.diff;
    const sharp = this.cpuSharpness();
    px += (Math.random() - 0.5) * 2 * d.predict / sharp;
    pz += (Math.random() - 0.5) * 2 * d.predict / sharp;
    // The queued misread: the beginner CPU sets off after a spot well wide
    // of the truth — the miss a fumble looks like on the sand. Only the far
    // side fumbles; the doubles partner plays for the player.
    if (this.cpuFumble && d.id === 'easy' && c.side !== this.playerSide) {
      px += (Math.random() < 0.5 ? -1 : 1) * (1.7 + Math.random() * 1.3);
      this.cpuFumble = false;
    }
    if (!chase) {
      // Not this athlete's ball: hold the middle of their cover spot, well
      // out of the chaser's way.
      c.target.set((c.xLo + c.xHi) / 2, 0, mix(c.zLo, c.zHi, 0.4));
      c.wantJump = false;
      c.wantDive = false;
      c.wantLaunch = false;
      c.wantStrike = false;
      return;
    }
    c.target.set(
      this.doubles ? clamp(px, c.xLo, c.xHi) : clamp(px, -4.6, 4.6),
      0, clamp(pz, c.zLo, c.zHi)
    );

    // Jump when the ball is close, above the net and on its way down — with a
    // chance of misjudging it that shrinks with difficulty. The reaction
    // radius grows too, so on hard it leaves lazy shots almost no gap.
    const dh = (pos.x - a.position.x) ** 2 + (pos.z - a.position.z) ** 2;
    c.wantJump =
      a.position.y <= 0.001 &&
      pos.y > 1.7 && pos.y < 3.6 &&
      b.vel.y < 1 &&
      dh < d.react * sharp * this.talkReach(c) &&
      Math.random() > d.mistime;
    // Once in a while it goes up with real authority for the block — more
    // often for a net-hugging blocker, almost never for a deep defender,
    // and freely at the legend tier.
    if (c.wantJump && Math.random() <
        (this.cpuStyle ? this.cpuStyle.launchChance
          : d.legend ? 0.65 : 0.3)) {
      c.wantLaunch = true;
    }
    // A desperate dive at a ball dropping just out of running reach — the
    // harder the level, the more willingly it throws itself onto the sand,
    // and at the legend tier it throws itself at almost everything.
    const diveChance =
      d.legend ? 0.8 : d.id === 'hard' ? 0.5 : d.id === 'normal' ? 0.25 : 0;
    const lateral = Math.hypot(px - a.position.x, pz - a.position.z);
    if (
      t > 0.06 && t < 0.5 && lateral > 0.7 && lateral < 2.6 &&
      a.position.y <= 0.001 && Math.random() < diveChance
    ) {
      c.wantDive = true;
    }
    // A full meter and a jump-worthy ball: on the higher levels the CPU
    // burns its super strike too, more willingly the harder it plays — and
    // at the legend tier, gladly.
    if (
      c.superMeter >= 1 && !c.superArmed && c.wantJump &&
      Math.random() < (d.legend ? 0.85
        : d.id === 'hard' ? 0.55 : d.id === 'normal' ? 0.2 : 0)
    ) {
      c.superArmed = true;
    }
    // The serve ace's signature: a soft ball crossing the net — a bump, a
    // lob, a float serve — is attacked, not played back. The strike move
    // fires the moment the ball comes within reach.
    c.wantStrike =
      !!this.cpuStyle && !b.wasSpike &&
      Math.hypot(px - a.position.x, pz - a.position.z) < 1.9 &&
      Math.random() < this.cpuStyle.secondBall;
  }

  /// Whose ball a landing is: the teammate whose cover band holds the spot,
  /// ties going to the band nearest it.
  chaserFor(team, px) {
    let best = team[0];
    let bestD = Infinity;
    for (const m of team) {
      const d = px < m.coverLo ? m.coverLo - px : px > m.coverHi ? px - m.coverHi : 0;
      if (d < bestD - 1e-9) {
        bestD = d;
        best = m;
      }
    }
    return best;
  }

  /// Sends the ball on a fresh arc toward the far court when it comes within
  /// reach of an athlete. A bump arcs high and slow; a spike — made in the air
  /// with the ball already above the net — is flat and fast.
  tryBump(who) {
    const b = this.ball;
    if (this.state !== 'rally' || b.landed) return;

    const a = who.athlete;
    const pos = b.mesh.position;
    // A dive digs with the whole body: the contact point drops to chest-and-
    // shoulder height and the reach stretches, and the palm check is waived —
    // any part of the body can dig, only a standing hit needs the hand.
    const diving = !!who.dive;
    const reach = (diving ? REACH * 1.45 : REACH) * this.talkReach(who);
    this.tmp.set(a.position.x, a.position.y + (diving ? 0.55 : 1.35), a.position.z);
    if (this.tmp.distanceToSquared(pos) > reach * reach) return;
    if (b.sinceTouch < 0.18) return;
    if (b.lastTouch === who.id && b.sinceTouch < 0.5) return;
    if (!diving && !canStrikeBall(a, pos)) return;

    const spike = a.position.y > 0.3 && pos.y > NET_TOP - 0.5;

    // A human striker: the player — or, in a shared-screen match, the second
    // athlete: the far one in two-player, the near partner in co-op.
    const p2 = this.twoPlayer || (this.coop && who.id === 'partner');
    const human = who.id === 'player' || p2;
    // An armed super burns on this touch: the meter empties and the shot
    // leaves at super strength, whatever the charge meter was doing.
    const superShot = !!who.superArmed;
    if (superShot) {
      who.superArmed = false;
      who.superMeter = 0;
    }
    const charge = superShot
      ? SUPER_CHARGE
      : (who.id === 'player' ? this.charge : p2 ? this.charge2 : 0);
    const input = who.id === 'player' ? this.input : p2 ? this.input2 : null;

    // Drag steering: a charged strike obeys the drag harder than a plain bump.
    const steer = 6.5 + 9 * (human ? charge : 0);
    let tx;
    if (human) {
      // Push the drag sideways while striking to place the shot.
      tx = clamp(input.x * this.playerSide * steer, -3.6, 3.6) +
        (Math.random() - 0.5) * this.talkAim(who);
    } else {
      // Its aim error shrinks with the difficulty — and it is allowed to
      // miss the court with it: the roll is clamped well past the sidelines,
      // so a sloppy level sprays returns and serves out of play while a
      // sharp one keeps everything inside.
      tx = (Math.random() * 5.2 - 2.6) +
        (Math.random() - 0.5) * 2 * this.diff.aimError * this.talkAim(who);
    }
    tx = clamp(tx, human ? -3.6 : -5.4, human ? 3.6 : 5.4);

    // Dragging up or down also shortens or deepens a charged shot.
    const depthNudge = human ? input.z * this.playerSide * 1.6 : 0;
    // A lob: the player's light tap from the sand — over a net-hugging CPU —
    // or, for the deep-court defender, its whole game: nearly everything
    // that crosses comes back high and slow. In the air the player spikes
    // like the CPU does — every airborne contact attacks, the meter only
    // buying pace on top — so a light tap never downgrades a jump hit into
    // a lob. An armed super is never downgraded into one either.
    const lob = (human && charge < LOB_CHARGE && a.position.y <= 0.3) ||
      (!human && !superShot && this.cpuStyle &&
        Math.random() < this.cpuStyle.lobChance);

    // A launch that met a crossing spike at the net: if this ball now dies
    // on the attacker's side, the touch was a block. Read before the strike
    // below re-tags what the ball is flying as.
    this.blockPending =
      who.launched && b.wasSpike &&
      a.position.y > 0.3 && Math.abs(a.position.z) < 1.3 &&
      pos.y > NET_TOP - 0.6
      ? who.id : null;

    // The CPU's automatic serve passes through this touch on its way over:
    // whoever stands at the line serves in their own way, so the roster
    // athlete's signature shapes the launch here too.
    const serving = this.autoServeLive === who;
    const sig = serving ? this.serveSignature(who) : null;
    let T;
    let tz;
    if (lob) {
      // Lob: a light tap of jump floats the ball high and slow — over a CPU
      // that hugs the net.
      T = 1.8 + Math.random() * 0.2;
      tz = -who.side * (3.6 + Math.random() * 2.0) + depthNudge;
    } else if ((spike && human) || superShot) {
      // The spike: flat, fast and hard to return. The player's airborne
      // contact attacks on the same terms as the CPU's own jump hit — an
      // uncharged jump spikes with the AI's own power, and the meter only
      // buys extra pace and depth on top of it.
      T = (0.84 - 0.24 * charge + Math.random() * 0.12) * (sig ? sig.arcJump : 1);
      tz = -who.side * (4.4 + 2.4 * charge + Math.random() * 1.4) + depthNudge;
    } else if (spike) {
      T = (0.78 + Math.random() * 0.15) * (sig ? sig.arcJump : 1);
      tz = -who.side * (4.2 + Math.random() * 2.2);
    } else {
      T = (1.45 + Math.random() * 0.3) * (sig ? sig.arcFloat : 1);
      tz = -who.side * (2.6 + Math.random() * 4.4);
    }
    tz = clamp(tz, -7.2, 7.2);
    // The CPU's aim error carries depth too: a sloppy level pushes returns
    // and serves long past the baseline, a sharp one never does. The server's
    // signature loosens or tightens its aim with the level, and the human's
    // depth stays exactly where the drag put it.
    if (!human) {
      tz += (Math.random() - 0.5) * 2 * this.diff.aimError * 0.9 * (sig ? sig.aim : 1);
    }
    // The drill ladder reads the kind of the player's last shot off this: a
    // flat attack, or a steered rally touch. Serves tag themselves in the
    // launch maths below.
    if (who.id === 'player') {
      this.lastShot = superShot || (spike && !lob) ? 'spike' : 'steer';
    }

    // Ballistic solve: pick a flight time, aim at the floor, and take the
    // launch velocity that lands there. The incoming drop is remembered
    // first — a ball arriving on its way down is a late contact — and the
    // spin state starts clean for the new flight.
    const dropping = b.vel.y < 0;
    this.resetBallSpin();
    b.vel.set(
      (tx - pos.x) / T,
      (-pos.y + 0.5 * G * T * T) / T,
      (tz - pos.z) / T
    );
    const h = Math.hypot(b.vel.x, b.vel.z);
    const maxH = superShot
      ? SUPER_MAXH
      : spike && human ? 14 + 8 * charge : spike ? 14 : 10;
    if (h > maxH) {
      b.vel.x *= maxH / h;
      b.vel.z *= maxH / h;
    }
    // A side that pushed the pace in the team talk hits a touch harder.
    b.vel.multiplyScalar(this.talkPace(who));
    // The striker's spin, read off the drag across the flight — human
    // touches only: the CPU's returns keep the behaviour they have always
    // had. Applied once the shot's own spin axis is set below.
    let spin = null;
    if (human && input) {
      const dx = tx - pos.x;
      const dz = tz - pos.z;
      const len = Math.hypot(dx, dz) || 1;
      spin = this.readSideSpin(input, dx / len, dz / len);
    }
    // The CPU's automatic serve leaves as this bump — the radar reads it
    // here, at the moment it leaves the hand, and the ace window opens.
    if (serving) {
      this.autoServeLive = false;
      // The CPU's own serve tags the rally's pace the same as a struck one.
      this.rallyServeKmh = serveKmh(b.vel);
      this.showServeSpeed(who, serveKmh(b.vel));
    }
    // Every rally touch reads its pace too: the readout pops beside the
    // striker — hot on a spike, gentle on a bump or lob — while the serve
    // itself stays the radar pill's alone.
    if (!serving) {
      this.showRallyPace(who, serveKmh(b.vel), (spike && !lob) || superShot);
    }

    b.lastTouch = who.id;
    // The serve itself keeps the ace window open; any later touch closes it.
    this.serveLive = serving ? who.id : null;
    b.sinceTouch = 0;
    b.contactPause = 0.028;
    b.pop = 1;

    // Contact feedback: the ball squashes along the hit and takes spin, the
    // striker's arm swings through it, and the slap cracks harder the harder
    // the ball was hit. A full-meter spike even kicks the camera.
    b.squashDir.copy(b.vel).normalize();
    this.tmp2.copy(b.vel).setY(0);
    if (this.tmp2.lengthSq() > 0.001) this.tmp2.normalize();
    if (superShot) {
      // The super strike: the loudest hit in the game — a blazing trail, the
      // camera kicked hard, the moment in slow motion, the crowd on its feet.
      b.spinAxis.copy(this.tmpUp).cross(this.tmp2);
      b.spinRate = 14;
      b.wasSpike = true;
      triggerSwing(a, 'spike', pos);
      playSlap(1.2);
      playZap();
      this.crowdRoar(1);
      this.camKick = 1;
      this.spawnFlash(pos);
      this.trailT = 1.3;
      this.slowT = 1.15;
      this.setMsg('SUPER STRIKE!');
      // The burn queues its rally's replay: the sideline slow motion runs
      // again at the rally's end, with the strike's own moment stamped in
      // the recording so the blazing trail burns a second time.
      this.superReplay = true;
      this.superStamp = true;
      // The match's first super strike is kept for the shot of the match.
      if (!this.superMoment) this.superMoment = { id: who.id };
      // A super strike from the near side earns a word from the opponent.
      if (human) this.opponentReact('super');
      haptic('superstrike');
    } else if (lob) {
      // Backspin on a lob: it hangs and floats — and contacted low, it also
      // drags against its own pace, sitting down short after the net.
      if (human && pos.y < 1.1) b.backDrag = 0.3;
      b.spinAxis.copy(this.tmp2).cross(this.tmpUp);
      b.spinRate = 5;
      b.wasSpike = false;
      triggerSwing(a, 'tip', pos);
      playBump(0.45);
    } else if (spike) {
      // Topspin on a drive: it dips late, like a genuinely hit ball.
      b.spinAxis.copy(this.tmpUp).cross(this.tmp2);
      b.spinRate = 7 + (human ? charge * 9 : 6);
      b.wasSpike = true;
      triggerSwing(a, 'spike', pos);
      playSlap(human ? 0.65 + charge * 0.45 : 0.85);
      this.camKick = Math.min(1, 0.45 + (human ? charge : 0.6));
      // A hard strike flashes: the burst at contact and a burning trail on
      // the ball — the supersonic moment. A full meter earns it, and so does
      // any of the CPU's flat drives.
      if (!lob && (human ? charge >= 0.8 : true)) this.spawnFlash(pos);
      // The script's big moment: a hard spike struck on a set-point or
      // deciding-set rally plays out in slow motion.
      const deciding = this.tieBreak;
      if (
        (this.setPointSide() || deciding) &&
        (!human || charge >= 0.75) &&
        this.slowT <= 0
      ) {
        this.slowT = 1.15;
        this.setMsg('SLOW MOTION!');
      }
      // The crowd rises for the big ones: a charged spike lifts them off the
      // sand, and on a set-point rally even an ordinary attack gets a roar.
      if (human && charge >= 0.7) this.crowdRoar(0.4 + 0.4 * charge);
      else if (this.setPointSide() || deciding) this.crowdRoar(0.45);
    } else {
      // A low, late contact digs the ball up with backspin: it sits down
      // short after crossing instead of sailing deep off the dig.
      if (human && pos.y < 1.1 && dropping) {
        b.backDrag = 0.3;
        b.spinAxis.copy(this.tmp2).cross(this.tmpUp);
        b.spinRate = 6;
      } else {
        b.spinAxis.copy(this.tmpUp).cross(this.tmp2);
        b.spinRate = 2.5;
      }
      b.wasSpike = false;
      triggerSwing(a, 'bump', pos);
      playBump(0.65);
    }

    // The sidespin goes on last, leaning the ball's own rotation toward the
    // vertical so the curve it will fly with shows in the spin itself.
    if (spin) {
      this.applySideSpin(
        spin, Math.hypot(b.vel.x, b.vel.z),
        b.spinAxis.x, b.spinAxis.y, b.spinAxis.z
      );
    }
    // The serve wears its athlete's signature on top: extra topspin on the
    // laser and the dip serve, the float's hang, and the banana's own bend.
    if (serving) {
      this.applyServeSignature(b, sig, (spike && !lob) || superShot);
    }

    this.touches[this.sideOf(who)]++;
    this.rallyLen++;
    // Ten touches in one rally: a milestone badge, toasted the moment it
    // lands.
    if (this.rallyLen >= 10 && recordMilestone('rally10')) {
      this.showBadgeToast('rally10');
    }
    // Twelve touches kept alive in one rally: the weekly rally goal reads
    // every touch at or past its mark.
    if (this.rallyLen >= 12 &&
        recordWeeklyBest('rally', this.rallyLen)) {
      this.showGoalToast('rally');
    }
    // The drill ladder reads every touch: the passing drill may pass here,
    // mid-rally, the moment the mark is reached.
    if (this.ladder) this.drillTouch();
    // Every touch earns a little super: four solid touches and the flame
    // button is ready to arm.
    who.superMeter = Math.min(1, who.superMeter + SUPER_GAIN);
    if ((spike && !lob) || superShot) this.stats.spikes[this.sideOf(who)]++;
    if (this.touches[this.sideOf(who)] > 3) {
      this.award(this.otherSide(this.sideOf(who)), 'TOO MANY TOUCHES —');
      return;
    }

    // The slap: two crisp transients a beat apart, like palm on leather —
    // unless the super strike just played its own, much bigger one.
    if (!superShot) haptic(lob || !spike ? 'bump' : 'slap');
  }

  /// Where a dive goes: along the drag if one is live, otherwise straight at
  /// the spot the falling ball is about to reach.
  diveDir(w, input) {
    const mag = Math.hypot(input.x, input.z);
    if (mag > 0.15) {
      return { x: input.x / mag, z: input.z / mag };
    }
    const pos = this.ball.mesh.position;
    const dy = Math.max(0, pos.y - 0.8);
    const t = (this.ball.vel.y + Math.sqrt(this.ball.vel.y * this.ball.vel.y + 2 * G * dy)) / G;
    const a = w.athlete;
    const dx = pos.x + this.ball.vel.x * t - a.position.x;
    const dz = pos.z + this.ball.vel.z * t - a.position.z;
    const len = Math.hypot(dx, dz) || 1;
    return { x: dx / len, z: dz / len };
  }

  /// The dive: a full-length lunge at the dropping ball. It hops, flies flat
  /// along the chosen direction, and anything the body meets on the way is
  /// dug — then the athlete pays for it, lying on the sand while they pick
  /// themselves up.
  startDive(w, dir) {
    if (w.dive || w.getUp > 0) return;
    const a = w.athlete;
    if (a.position.y > 0.05) return;
    if (this.state !== 'rally' || this.ball.landed) return;
    w.dive = { t: DIVE_T, vx: dir.x * DIVE_SPEED, vz: dir.z * DIVE_SPEED };
    w.vy = DIVE_VY;
    // A dive throws a low spray of sand out behind the lunge.
    this.spawnSpray(
      a.position.x - dir.x * 0.3, a.position.z - dir.z * 0.3, 10,
      { spread: 1.2, up: 0.9, size: 1.1, dirX: dir.x, dirZ: dir.z }
    );
    playWhoosh();
    haptic('dive');
  }

  /// Runs a dive from take-off to the sand, and the slow getting-up that
  /// follows it. Returns true when the dive owns the athlete this frame, so
  /// normal movement waits.
  updateDiveState(w, dt) {
    const a = w.athlete;
    if (w.dive) {
      w.dive.t -= dt;
      w.vy -= G * dt;
      a.position.x = clamp(a.position.x + w.dive.vx * dt, -4.6, 4.6);
      a.position.z = clamp(a.position.z + w.dive.vz * dt, w.zLo, w.zHi);
      a.position.y = Math.max(0, a.position.y + w.vy * dt);
      const prog = 1 - clamp(w.dive.t / DIVE_T, 0, 1);
      setDiveLean(a, Math.sin(Math.min(1, prog * 1.25) * Math.PI / 2));
      // The dive always ends: if the landing never resolves — a dive thrown
      // into a corner the clamp holds him against — the athlete is put back on
      // his feet rather than left lying on the sand for the rest of the match.
      if ((a.position.y <= 0.001 && w.vy <= 0 && w.dive.t < DIVE_T - 0.1) ||
          w.dive.t < -1.2) {
        w.dive = null;
        w.getUp = DIVE_GETUP;
        playFloor();
        this.camKick = Math.max(this.camKick, 0.2);
        haptic('impact');
      }
      w.moveMag = 0;
      w.runMag = Math.max(0, w.runMag - dt * 5);
      // The dive is a flat-out sprint: it spends the legs too.
      this.updateStamina(w, dt, true);
      return true;
    }
    if (w.getUp > 0) {
      w.getUp = Math.max(0, w.getUp - dt);
      setDiveLean(a, w.getUp / DIVE_GETUP);
      w.vy = 0;
      w.moveMag = 0;
      w.runMag *= Math.exp(-dt * 6);
      // Picking themselves up is standing: the legs refill.
      this.updateStamina(w, dt, false);
      return true;
    }
    return false;
  }

  /// The strike button: an on-demand power hit. The moment the ball comes
  /// within reach, a tap sends a flat, hard attack steered by the drag — the
  /// charge meter still buys extra pace if jump is being held at the time.
  /// Taken light on the team's second touch, the same tap becomes a hand
  /// set instead: a soft overhead pop that hangs high just this side of the
  /// net, waiting for a teammate to run onto it and swing.
  tryStrike(w, input, charge) {
    if (w.strikeCd > 0) return;
    w.strikeCd = STRIKE_CD;
    const b = this.ball;
    const a = w.athlete;
    if (this.state !== 'rally' || b.landed) return;
    const pos = b.mesh.position;
    if (b.sinceTouch < 0.18) return;
    if (b.lastTouch === w.id && b.sinceTouch < 0.5) return;
    const dy = pos.y - (a.position.y + 1.35);
    const d2 = (pos.x - a.position.x) ** 2 + dy * dy + (pos.z - a.position.z) ** 2;
    if (d2 > (REACH * 1.3) ** 2 || !canStrikeBall(a, pos)) {
      // A whiff: the swing goes through empty air with a soft whoosh.
      playWhoosh();
      return;
    }
    // The rally stays live and the counters tick exactly as for an auto hit.
    // An armed super fires here too: the meter empties into one strike at
    // super strength, with the full fanfare.
    const armed = !!w.superArmed;
    if (armed) {
      w.superArmed = false;
      w.superMeter = 0;
    }
    // The hand set: a human striker's light tap once the team has already
    // touched the ball — and always from the sand, because in the air every
    // contact attacks. A held charge still drives.
    const human = w.id === 'player' ||
      (this.twoPlayer && w.id === 'cpu') || (this.coop && w.id === 'partner');
    const handSet = !armed && human && a.position.y <= 0.3 &&
      this.touches[this.sideOf(w)] >= 1 && charge < LOB_CHARGE;
    if (handSet) {
      // Popped high and gentle, drifting down just this side of the net —
      // close enough to swing at, and a fault if it dies there untouched,
      // exactly like the real second touch. The drag steers it along the net
      // and nudges its depth like any other touch.
      const T = 1.55 + Math.random() * 0.3;
      const tx = clamp(
        input.x * this.playerSide * 5 + (Math.random() - 0.5) * 0.8, -3.4, 3.4
      );
      const tz = w.side * clamp(
        0.9 + Math.random() * 1.2 + input.z * this.playerSide * 1.6, 0.5, 3.4
      );
      this.resetBallSpin();
      b.vel.set(
        (tx - pos.x) / T,
        (-pos.y + 0.5 * G * T * T) / T,
        (tz - pos.z) / T
      );
      const h = Math.hypot(b.vel.x, b.vel.z);
      if (h > 7) {
        b.vel.x *= 7 / h;
        b.vel.z *= 7 / h;
      }
      // A light turn, like an overhead pass revolving on its way up.
      this.tmp2.copy(b.vel).setY(0);
      if (this.tmp2.lengthSq() > 0.001) this.tmp2.normalize();
      b.spinAxis.copy(this.tmpUp).cross(this.tmp2);
      b.spinRate = 3;
      b.wasSpike = false;
      b.lastTouch = w.id;
      this.serveLive = null;
      b.sinceTouch = 0;
      b.contactPause = 0.028;
      b.pop = 1;
      b.squashDir.copy(b.vel).normalize();
      // The set reads its pace like any touch — popped high and gentle.
      this.showRallyPace(w, serveKmh(b.vel), false);
      // The tag that tells a teammate's brain there is a set to read.
      b.handSet = true;
      triggerSwing(a, 'tip', pos);
      playBump(0.5);
      haptic('bump');
      if (w.id === 'player') this.lastShot = 'steer';
    } else {
      const pw = armed ? SUPER_CHARGE : Math.max(charge, 0.4);
      this.serveLaunch(w, input, pw, true, false);
      if (armed) {
        // The super fanfare on top of the launch's own flash: the trail burns
        // longer, the moment plays out in slow motion, the crowd gets loud.
        this.trailT = 1.3;
        this.slowT = 1.15;
        this.setMsg('SUPER STRIKE!');
        // The burn queues its rally's replay: the sideline slow motion runs
        // again at the rally's end, with the strike's own moment stamped in
        // the recording so the blazing trail burns a second time.
        this.superReplay = true;
        this.superStamp = true;
        // The match's first super strike is kept for the shot of the match.
        if (!this.superMoment) this.superMoment = { id: w.id };
        // A super strike fired from the near side earns a word from the
        // opponent — the strike move can carry an armed super too.
        if (w.id === 'player') this.opponentReact('super');
        playZap();
        this.crowdRoar(1);
        haptic('superstrike');
      }
    }
    // A strike is an attack, never a block: any pending block read is stale.
    this.blockPending = null;
    this.touches[this.sideOf(w)]++;
    this.rallyLen++;
    // Ten touches in one rally: a milestone badge, toasted the moment it
    // lands.
    if (this.rallyLen >= 10 && recordMilestone('rally10')) {
      this.showBadgeToast('rally10');
    }
    // Twelve touches kept alive in one rally: the weekly rally goal reads
    // every touch at or past its mark.
    if (this.rallyLen >= 12 &&
        recordWeeklyBest('rally', this.rallyLen)) {
      this.showGoalToast('rally');
    }
    // The drill ladder reads every touch here too.
    if (this.ladder) this.drillTouch();
    // Every touch earns a little super: four solid touches and the flame
    // button is ready to arm.
    w.superMeter = Math.min(1, w.superMeter + SUPER_GAIN);
    // The set is not a spike: only the drive lands in the spike tally.
    if (!handSet) this.stats.spikes[this.sideOf(w)]++;
    if (this.touches[this.sideOf(w)] > 3) {
      this.award(this.otherSide(this.sideOf(w)), 'TOO MANY TOUCHES —');
    }
  }

  updateAthleteMotion(who, dt) {
    const a = who.athlete;
    const pos = this.ball.mesh.position;
    const near =
      (pos.x - a.position.x) ** 2 + (pos.z - a.position.z) ** 2 < 9 &&
      pos.y - a.position.y < 3.6;
    const preparingServe = (this.state === 'serve' || this.state === 'serveReady') &&
      this.serverAth === who;
    const liveBall = !this.ball.landed &&
      (preparingServe || this.state === 'rally' || (this.state === 'toss' && this.tossAth === who));
    // While the machine runs, the athlete beside it is a spectator: he
    // watches the feeds without reaching for balls that are not his to play.
    const watching = this.drill && who.id === 'cpu';
    const incoming = !watching && liveBall && near &&
      (this.ball.lastTouch !== who.id || this.ball.sinceTouch > 0.5 || this.state === 'toss');
    updateAthlete(a, dt, {
      speed: who.runMag,
      dir: who.dir,
      airborne: a.position.y > 0.05,
      reach: incoming,
      ballPosition: incoming ? pos : null
    });
  }

  /// A fresh touch, a clean flight: the in-flight spin state resets at every
  /// launch, so each shot's curve is its own.
  resetBallSpin() {
    this.ball.curve.set(0, 0, 0);
    this.ball.backDrag = 0;
    this.ball.flightT = 0;
    // A fresh touch ends any hand set the ball was carrying.
    this.ball.handSet = false;
  }

  /// The sidespin a human touch puts on the ball, read off the drag: how far
  /// it swipes across the shot's flight, past a small dead zone so ordinary
  /// steering never bends a shot by accident. Fills the shared scratch with
  /// the signed magnitude — positive meaning the drag leaned toward the
  /// flight's left-hand side — and that sideways direction itself.
  readSideSpin(input, dirX, dirZ) {
    const cross = input.x * this.playerSide * -dirZ +
      input.z * this.playerSide * dirX;
    spinRead.mag = Math.abs(cross) > SPIN_DEAD
      ? (Math.abs(cross) - SPIN_DEAD) / (1 - SPIN_DEAD) : 0;
    spinRead.signed = cross < 0 ? -spinRead.mag : spinRead.mag;
    spinRead.perpX = -dirZ;
    spinRead.perpZ = dirX;
    return spinRead;
  }

  /// Puts the read spin on the ball: the sideways acceleration it will carry
  /// through its flight, scaled with the pace of the shot — a driven ball
  /// bends harder than a float — and the ball's own rotation leaned from the
  /// strike's spin toward the vertical, the harder the sidespin, the more it
  /// turns like a top. The sense of the lean is the one whose Magnus turn
  /// matches the curve.
  applySideSpin(spin, speed, ax, ay, az) {
    const b = this.ball;
    if (spin.mag <= 0) return;
    const a = spin.mag * (0.55 + speed * 0.1);
    b.curve.set(spin.perpX * spin.signed * a, 0, spin.perpZ * spin.signed * a);
    const w = Math.min(0.78, 0.3 + spin.mag * 0.55);
    b.spinAxis.set(ax * (1 - w), ay * (1 - w) + (spin.signed < 0 ? w : -w),
      az * (1 - w));
    b.spinAxis.normalize();
    b.spinRate = Math.max(b.spinRate, 7 + 7 * spin.mag);
  }

  updateBall(dt) {
    const b = this.ball;
    const pos = b.mesh.position;
    b.sinceTouch += dt;
    // A tiny, time-based contact hold makes the visible palm and the launch
    // share a frame even on a fast shot. It is not a new control delay.
    const held = Math.min(b.contactPause, dt);
    b.contactPause -= held;
    const flightDt = dt - held;

    if (this.state === 'serve' || this.state === 'serveReady') {
      // The ball rides above the server until the countdown ends — or, on the
      // player's serve, until they toss it up themselves.
      const s = this.serverAth || this.player;
      pos.set(s.athlete.position.x, s.athlete.position.y + 1.45, s.athlete.position.z - s.side * 0.4);
      b.vel.set(0, 0, 0);
      b.spinRate = 0;
      b.pop = 0;
    } else {
      const prevZ = pos.z;
      b.vel.y -= G * flightDt;
      pos.addScaledVector(b.vel, flightDt);
      // While the serve toss is up, remember how high it got.
      if (this.state === 'toss') this.tossApex = Math.max(this.tossApex, pos.y);

      // The breeze nudges the ball sideways the whole way it flies — serves
      // drift, lobs sail, and the aim has to play the wind, not the map.
      if (!b.landed && pos.y > BALL_R + 0.05) {
        pos.x += this.wind.x * this.wind.strength * flightDt;
        pos.z += this.wind.z * this.wind.strength * flightDt;
      }

      // Spin in the air: a sidespun shot bends across its flight, the
      // sideways displacement growing with the square of the time away the
      // way a real curve ball breaks late. A backspin float drags against
      // its own pace instead, sitting down short of where it was aimed.
      if (!b.landed && pos.y > BALL_R + 0.05) {
        if (b.curve.lengthSq() > 0.000001) {
          b.flightT += flightDt;
          pos.x += b.curve.x * b.flightT * flightDt;
          pos.z += b.curve.z * b.flightT * flightDt;
        }
        if (b.backDrag > 0) {
          const dragK = Math.max(0, 1 - b.backDrag * flightDt);
          b.vel.x *= dragK;
          b.vel.z *= dragK;
        }
      }

      // The net blocks anything under its top band that tries to cross.
      if (prevZ * pos.z <= 0 && Math.abs(pos.x) < NET_HALF_W && pos.y < NET_TOP) {
        pos.z = Math.sign(prevZ || 1) * (BALL_R + 0.03);
        b.vel.z *= -0.32;
        b.vel.x *= 0.6;
        b.vel.y *= 0.8;
        this.netWobble = 1;
        // The mesh catches the ball: deaden it, flatten it against the tape,
        // and let the net rattle.
        b.squashDir.set(0, 0, -Math.sign(prevZ || 1));
        b.pop = 0.55;
        b.spinRate *= 0.3;
        haptic('tick');
        playNet();
      }

      // Crossing the net cleanly resets the touch count for the receiving side.
      const sign = pos.z > 0 ? 1 : -1;
      if (Math.abs(pos.z) > 1 && sign !== b.sideSign) {
        b.sideSign = sign;
        this.touches[sign === this.playerSide ? 'player' : 'cpu'] = 0;
        // One crossing in four against the beginner CPU is misjudged
        // outright. Never in practice, where the drill is the point.
        this.cpuFumble = !this.practice && this.diff.id === 'easy' &&
          Math.random() < 0.25;
      }

      // The floor. The first touch decides the point; after that the ball just
      // bounces out the pause for looks.
      if (pos.y < BALL_R) {
        pos.y = BALL_R;
        const vy0 = b.vel.y;
        if (this.state === 'toss' && !b.landed) {
          // The toss hit the sand unstruck: the serve never happened and the
          // point goes to the CPU.
          b.landed = true;
          // No serve was struck in this point, so no pace tags it — the
          // shot-of-the-match pool must never read the last rally's speed.
          this.rallyServeKmh = null;
          // The tosser's side loses it — whichever athlete held the toss, on
          // either team.
          this.award(this.otherSide(this.sideOf(this.tossAth)), 'FAULT!');
        }
        if (this.state === 'rally' && !b.landed) {
          b.landed = true;
          // The kind of this point starts clean: only a landing that reads
          // as an ace or a block tags it.
          this.lastPointKind = null;
          // The serving target challenge: a player shot dying on the far
          // court is an attempt, and one inside the ring is a hit.
          if (this.practice && b.lastTouch === 'player' && pos.z * this.playerSide < 0) {
            this.targetHit(pos.x, pos.z);
          }
          const inX = Math.abs(pos.x) <= HALF_W + 0.2;
          const inZ = Math.abs(pos.z) >= 0.2 && Math.abs(pos.z) <= HALF_L + 0.2;
          const truth = inX && inZ;
          // The placement heatmap: a human striker's shot dying in bounds
          // on the far court drops into the match's grid — the player, or
          // player two's own body in the shared-screen modes.
          if (
            truth && pos.z * this.playerSide < 0 &&
            (b.lastTouch === 'player' ||
              (this.twoPlayer && b.lastTouch === 'cpu') ||
              (this.coop && b.lastTouch === 'partner'))
          ) {
            this.recordHeatShot(pos.x, pos.z);
          }
          // And the far side's own placements: their shots dying in bounds
          // on the near court fill the rival grid — everyone but the near
          // team counts, and the practice machine is nobody's opponent.
          if (
            truth && pos.z * this.playerSide > 0 &&
            b.lastTouch && b.lastTouch !== 'machine' &&
            this.sideOfId(b.lastTouch) === 'cpu'
          ) {
            this.recordRivalHeatShot(pos.x, pos.z);
          }
          // Every shot that dies on the court leaves its chalk mark on the
          // sand — either half — so placement reads on the court itself.
          if (truth) this.spawnLandingMark(pos.x, pos.z);
          // How far the mark sits from the nearest court line: inside, the
          // run to the closer of sideline or baseline; outside, the overshoot.
          const dx = Math.abs(pos.x) - HALF_W;
          const dz = Math.abs(pos.z) - HALF_L;
          const lineDist = dx >= 0 && dz >= 0 ? Math.hypot(dx, dz)
            : dx >= 0 ? dx : dz >= 0 ? dz : Math.min(-dx, -dz);
          const inWinner = pos.z * this.playerSide > 0 ? 'cpu' : 'player';
          const outWinner = this.otherSide(this.sideOfId(b.lastTouch));
          // A mark within half a metre of a line can be sent to review — one
          // challenge a set — and the tighter to the line, the likelier the
          // line judge misread it. The call is what scores until reviewed.
          const reviewable = !this.practice && this.challengesLeft > 0 &&
            lineDist <= CHALLENGE_DIST;
          let calledIn = truth;
          if (reviewable) {
            const errP = CHALLENGE_ERR +
              (CHALLENGE_ERR_MAX - CHALLENGE_ERR) * (1 - lineDist / CHALLENGE_DIST);
            if (Math.random() < errP) calledIn = !calledIn;
          }
          const calledWinner = calledIn ? inWinner : outWinner;
          if (reviewable) {
            this.startCallReview(truth, calledIn, calledWinner, pos.x, pos.z);
          } else {
            this.tagPoint(calledWinner);
            this.award(calledWinner, calledIn ? '' : 'OUT!');
          }
        }
        b.vel.y = Math.abs(b.vel.y) * 0.4;
        b.vel.x *= 0.7;
        b.vel.z *= 0.7;
        if (b.vel.y < 1.4) b.vel.y = 0;
        // A sand landing flattens the ball on its underside with a soft thud.
        b.squashDir.set(0, 1, 0);
        b.pop = Math.max(b.pop, Math.min(0.7, Math.abs(vy0) * 0.05));
        b.spinRate *= 0.4;
        if (Math.abs(vy0) > 2) playFloor();
      }
    }

    // Squash along the direction it was hit, bulging across it, while the spin
    // from the strike keeps turning the ball over in the air.
    b.pop = Math.max(0, b.pop - dt * 5);
    if (b.spinRate !== 0) {
      b.mesh.rotateOnWorldAxis(b.spinAxis, b.spinRate * dt);
    }
    if (b.pop > 0.001) {
      this.tmpQ.copy(b.mesh.quaternion).invert();
      this.tmp.copy(b.squashDir).applyQuaternion(this.tmpQ);
      const k = 1 - 0.42 * b.pop;
      const bulge = 0.2 * b.pop;
      b.mesh.scale.set(
        1 + (k - 1) * this.tmp.x * this.tmp.x + bulge * (1 - this.tmp.x * this.tmp.x),
        1 + (k - 1) * this.tmp.y * this.tmp.y + bulge * (1 - this.tmp.y * this.tmp.y),
        1 + (k - 1) * this.tmp.z * this.tmp.z + bulge * (1 - this.tmp.z * this.tmp.z)
      );
    } else if (b.mesh.scale.x !== 1) {
      b.mesh.scale.set(1, 1, 1);
    }
  }

  // ---------------------------------------------------------------- review

  /// The ace and block tags for a landing that just decided a point: an
  /// untouched serve landing for a point is an ace, a launch that stopped a
  /// crossing spike dead is a block — credited to whoever the point finally
  /// went to, which a review can overturn. The guards make the tags no-ops
  /// wherever they do not apply.
  tagPoint(winner) {
    if (
      this.serveLive && this.serveLive === this.ball.lastTouch &&
      this.sideOfId(this.ball.lastTouch) === winner
    ) {
      this.stats.aces[winner]++;
      this.lastPointKind = 'ace';
    }
    if (this.blockPending && this.sideOfId(this.blockPending) === winner) {
      this.stats.blocks[winner]++;
      this.lastPointKind = 'block';
    }
  }

  /// The booth's offer: the mark sat within half a metre of a line, and the
  /// call that just decided the point can be sent to review. The offer goes
  /// to the side the call favoured — they hold the point, and reviewing it
  /// puts that point on the line. A human decides with a pill; the CPU
  /// chews it over for a beat and usually lets it go.
  startCallReview(truth, calledIn, calledWinner, markX, markZ) {
    const human = calledWinner === 'player' || this.twoPlayer;
    this.callReview = {
      trueIn: truth, calledIn, calledWinner, markX, markZ,
      cpuAt: human ? null : 1.3
    };
    this.state = 'challengeWait';
    this.timer = CHALLENGE_WAIT;
    this.setMsg('CLOSE CALL AT THE LINE!');
    if (human) this.challengeBtn.style.display = 'block';
    haptic('tick');
  }

  /// Nobody took the offer: the call stands and the point is awarded as
  /// called.
  resolveCall() {
    this.challengeBtn.style.display = 'none';
    const rv = this.callReview;
    this.callReview = null;
    this.tagPoint(rv.calledWinner);
    this.award(rv.calledWinner, rv.calledIn ? '' : 'OUT!');
  }

  /// The pill was tapped: the challenge is spent and the mark goes under the
  /// overhead camera.
  takeChallengeOffer() {
    if (!this.callReview) return;
    this.startChallenge();
  }

  /// The review itself: the challenge is spent, the mark — a bright disc
  /// ringed in gold — is laid on the sand where the ball touched, and the
  /// rally's close replays in slow motion from a camera above the mark.
  startChallenge() {
    const buf = this.recBuf;
    const last = buf[buf.length - 1];
    if (!last) {
      this.resolveCall();
      return;
    }
    const rv = this.callReview;
    this.challengeBtn.style.display = 'none';
    this.challengesLeft--;
    this.refreshChallengePill();
    this.state = 'challenge';
    this.markGroup = new THREE.Group();
    const disc = new THREE.Mesh(
      new THREE.CircleGeometry(0.14, 24),
      new THREE.MeshBasicMaterial({
        color: 0xf2f2f2, transparent: true, opacity: 0.92, depthWrite: false
      })
    );
    disc.rotation.x = -Math.PI / 2;
    const ring = new THREE.Mesh(
      new THREE.RingGeometry(0.22, 0.3, 36),
      new THREE.MeshBasicMaterial({
        color: 0xffd24a, transparent: true, opacity: 0.95,
        side: THREE.DoubleSide, depthWrite: false
      })
    );
    ring.rotation.x = -Math.PI / 2;
    this.markGroup.add(disc, ring);
    this.markGroup.renderOrder = 3;
    this.markGroup.position.set(rv.markX, 0.035, rv.markZ);
    this.root.add(this.markGroup);
    this.chalStage = 'replay';
    this.chalT = Math.max(buf[0].t, last.t - 1.5);
    this.chalEnd = last.t;
    this.chalI = 0;
    while (this.chalI < buf.length - 2 && buf[this.chalI + 1].t < this.chalT) {
      this.chalI++;
    }
    // The cut overhead is instant, the way a broadcast review cuts.
    const cam = this.game.camera;
    cam.position.set(rv.markX, 9.4, rv.markZ + 3.0);
    cam.lookAt(rv.markX, 0, rv.markZ);
    this.chalBanner = addText('CHALLENGE', {
      left: '50%',
      top: 'calc(env(safe-area-inset-top) + 92px)',
      transform: 'translateX(-50%)',
      padding: '4px 14px',
      borderRadius: '6px',
      backgroundColor: 'rgba(228, 178, 34, 0.92)',
      color: '#231503',
      fontSize: '13px',
      fontWeight: '800',
      letterSpacing: '4px'
    });
    this.setMsg('THE MARK IS BEING CHECKED…');
    playWhoosh();
  }

  /// The overhead review: the rally's close plays out in slow motion from
  /// above the mark — the ball landing on the drawn spot — and then the
  /// ruling, IN or OUT, holds the screen before the point is settled.
  updateChallenge(dt) {
    this.updateWind(dt);
    if (this.chalStage === 'ruling') {
      this.chalT += dt;
      if (this.chalT >= 2.3) this.finishChallenge();
      return;
    }
    const rv = this.callReview;
    const buf = this.recBuf;
    this.chalT += dt * 0.33; // third speed, slower than the sideline replay
    if (this.chalT >= this.chalEnd) {
      this.chalStage = 'ruling';
      this.chalT = 0;
      const inMark = rv.trueIn;
      this.rulingText = addText(inMark ? 'IN' : 'OUT', {
        left: '50%',
        top: '40%',
        transform: 'translate(-50%, -50%)',
        fontSize: '58px',
        fontWeight: '800',
        letterSpacing: '8px',
        color: inMark ? '#ffd24a' : '#ff6a4d',
        textShadow: '0 4px 18px rgba(20, 40, 60, 0.75)'
      });
      this.setMsg(inMark ? 'THE MARK SAYS IN!' : 'THE MARK SAYS OUT!');
      playCheer(false, 1.2);
      this.crowdWaveStart(0.9);
      haptic('point');
      return;
    }
    while (this.chalI < buf.length - 2 && buf[this.chalI + 1].t < this.chalT) {
      this.chalI++;
    }
    const fa = buf[this.chalI];
    const fb = buf[this.chalI + 1];
    const al = clamp((this.chalT - fa.t) / Math.max(0.0001, fb.t - fa.t), 0, 1);
    // The ball: flight, spin and squash replayed as they happened.
    const mesh = this.ball.mesh;
    mesh.position.set(
      mix(fa.b[0], fb.b[0], al), mix(fa.b[1], fb.b[1], al), mix(fa.b[2], fb.b[2], al)
    );
    mesh.scale.set(
      mix(fa.b[3], fb.b[3], al), mix(fa.b[4], fb.b[4], al), mix(fa.b[5], fb.b[5], al)
    );
    this.tmpQ.set(fa.b[6], fa.b[7], fa.b[8], fa.b[9]);
    this.tmpQ2.set(fb.b[6], fb.b[7], fb.b[8], fb.b[9]);
    mesh.quaternion.slerpQuaternions(this.tmpQ, this.tmpQ2, al);
    for (const [w, k] of this.replayActors()) {
      this.replayAthlete(w.athlete, fa[k], fb[k], al);
    }
    // The locked overhead shot, easing the last bit onto the mark.
    const cam = this.game.camera;
    const k = Math.min(1, dt * 2.5);
    cam.position.x += (rv.markX - cam.position.x) * k;
    cam.position.y += (9.4 - cam.position.y) * k;
    cam.position.z += (rv.markZ + 3.0 - cam.position.z) * k;
    cam.lookAt(rv.markX, 0, rv.markZ);
  }

  /// The ruling is in: the mark lifts, and the point is awarded to whoever
  /// it says owns it — kept when the call was confirmed, handed over when
  /// the review overturned it.
  finishChallenge() {
    if (this.markGroup) {
      this.markGroup.traverse((o) => {
        if (o.geometry) o.geometry.dispose();
        if (o.material) o.material.dispose();
      });
      this.root.remove(this.markGroup);
      this.markGroup = null;
    }
    this.chalBanner?.remove();
    this.rulingText?.remove();
    this.chalBanner = null;
    this.rulingText = null;
    const rv = this.callReview;
    this.callReview = null;
    const confirmed = rv.trueIn === rv.calledIn;
    const finalWinner = confirmed ? rv.calledWinner : this.otherSide(rv.calledWinner);
    // The point was already shown settling on the review: no second replay
    // of the same rally.
    this.skipReplayOnce = true;
    this.tagPoint(finalWinner);
    this.award(
      finalWinner,
      confirmed ? 'CHALLENGE WON —' : 'CHALLENGE LOST —'
    );
    // The review settled the point on the court already shown — its rally
    // still banks into the shot-of-the-match pool for the gold card.
    this.bankShotReplay();
  }

  /// The challenge pill: how many reviews remain this set — bright while one
  /// is in hand, dimmed once it is spent.
  refreshChallengePill() {
    if (!this.challengePill) return;
    this.challengePill.textContent = `CHALLENGE · ${this.challengesLeft}`;
    this.challengePill.style.opacity = this.challengesLeft > 0 ? '0.95' : '0.45';
  }

  // ---------------------------------------------------------------- replay

  /// One frame of the rolling record: the ball's transform, squash and spin,
  /// plus both athletes — root transform and the full eased pose — so the
  /// replay reproduces the rally exactly instead of approximating it.
  recordFrame(dt) {
    // The replay playback interpolates between recorded frames, so sampling
    // the rally at 30Hz instead of every frame is visually identical — and
    // halves both the per-frame snap work and the allocation churn the
    // ring's fresh pose arrays create on a phone.
    this.recBudget = (this.recBudget || 0) + dt;
    if (this.recBudget < 0.033) return;
    dt = this.recBudget;
    this.recBudget = 0;
    this.recT += dt;
    // The super strike's moment in the recording, stamped on the first frame
    // after the burn — the replay re-ignites the trail right there.
    if (this.superStamp) {
      this.superRecT = this.recT;
      this.superStamp = false;
    }
    const b = this.ball.mesh;
    const buf = this.recBuf;
    const frame = {
      t: this.recT,
      b: [b.position.x, b.position.y, b.position.z,
        b.scale.x, b.scale.y, b.scale.z,
        b.quaternion.x, b.quaternion.y, b.quaternion.z, b.quaternion.w],
      p: this.snapAthlete(this.player.athlete),
      c: this.snapAthlete(this.cpu.athlete)
    };
    // Doubles records the whole foursome: the replay shows the full rally.
    if (this.doubles) {
      frame.d = this.snapAthlete(this.partner.athlete);
      frame.e = this.snapAthlete(this.cpu2.athlete);
    }
    buf.push(frame);
    // A ring over the recent past: only the last few seconds are kept.
    while (buf.length > 2 && buf[0].t < this.recT - 3.35) buf.shift();
  }

  snapAthlete(a) {
    const u = a.userData;
    return {
      x: a.position.x, y: a.position.y, z: a.position.z, ry: a.rotation.y,
      pose: captureAthletePose(a),
      bob: u.bob
    };
  }

  /// A frame of the rolling record copied for the shot-of-the-match pool:
  /// the ring buffer reuses its frame objects every rally, so a banked
  /// recording has to own its own copies of every number it replays from.
  cloneRecFrame(f) {
    const out = {
      t: f.t,
      b: f.b.slice(),
      p: this.cloneRecSnap(f.p),
      c: this.cloneRecSnap(f.c)
    };
    if (f.d) out.d = this.cloneRecSnap(f.d);
    if (f.e) out.e = this.cloneRecSnap(f.e);
    return out;
  }

  cloneRecSnap(s) {
    return {
      x: s.x, y: s.y, z: s.z, ry: s.ry, bob: s.bob,
      pose: {
        bones: s.pose.bones.slice(),
        offset: s.pose.offset.slice(),
        yaw: s.pose.yaw
      }
    };
  }

  /// The shot-of-the-match pool banks the rally under way: its closing
  /// seconds exactly as the replay plays them, tagged with the rally's touch
  /// count, the pace its serve left at and whether a super strike burned in
  /// it — the three keys the gold moment finds its own clip by.
  bankShotReplay(allowServe = false) {
    const buf = this.recBuf;
    if ((!this.rallyLen && !allowServe) || !buf.length ||
        buf[buf.length - 1].t - buf[0].t < 0.8) return;
    const cut = buf[buf.length - 1].t - 3.0;
    this.shotPool.push({
      frames: buf.filter((f) => f.t >= cut).map((f) => this.cloneRecFrame(f)),
      touches: this.rallyLen,
      serveKmh: this.rallyServeKmh,
      super: !!this.lastRallySuper
    });
  }

  /// The career replay: this rally's closing seconds, decimated to a storing
  /// frame rate and rounded into plain arrays that survive a JSON round
  /// trip, with both athletes' colours carried so the playback dresses them
  /// exactly as they played. Bone poses store their quaternion channels
  /// only — live play never moves a bone off its rest position, so the
  /// playback rebuilds positions from its own rig.
  rallyRecording() {
    const buf = this.recBuf;
    if (buf.length < 4) return null;
    const last = buf[buf.length - 1];
    if (last.t - buf[0].t < 0.8) return null; // too little lived to keep
    const t0 = buf[0].t;
    const frames = [];
    for (let i = 0; i < buf.length; i += 2) frames.push(this.packRecFrame(buf[i], t0));
    const tail = this.packRecFrame(last, t0);
    if (tail.t > frames[frames.length - 1].t) frames.push(tail);
    return {
      frames,
      pc: { ...playerColors('p1') },
      cc: { ...(this.twoPlayer ? playerColors('p2') : this.cpuStats.colors) }
    };
  }

  packRecFrame(f, t0) {
    return {
      t: r3(f.t - t0),
      b: f.b.map(r4),
      p: this.packRecSnap(f.p),
      c: this.packRecSnap(f.c)
    };
  }

  packRecSnap(s) {
    return {
      x: r3(s.x), y: r3(s.y), z: r3(s.z), ry: r3(s.ry),
      pose: {
        q: packArr(s.pose.bones),
        offset: s.pose.offset.map(r3),
        yaw: r3(s.pose.yaw)
      }
    };
  }

  /// Starts the replay of the rally that just ended: the final three seconds
  /// from a low camera on the side line, a broadcast banner, a soft whoosh.
  beginReplay() {
    const buf = this.recBuf;
    const last = buf[buf.length - 1];
    if (!last || last.t - buf[0].t < 0.8) return; // too little lived to show
    // The replay banks its rally into the shot-of-the-match pool on the way
    // in — the gold moment the recap names plays back from the match's own
    // reel when it points at this rally. An ace replay is the serve moment's
    // own clip: the pace it banks under is the serve's.
    this.bankShotReplay(this.replayCall === 'ACE!');
    // The match-point spotlight stands down for the replay too: the
    // broadcast owns the screen, and the beam waits for the next serve.
    this.spotI = 0;
    if (this.spotGroup) this.spotGroup.visible = false;
    // A milestone banner up in the far stand comes down on the cut: the
    // broadcast owns the screen for the replay's length.
    if (this.bannerT >= 0) {
      this.bannerT = -1;
      this.bannerGroup.visible = false;
      this.bannerHold = null;
      this.bannerHoldLevel = 0;
    }
    // A changeover can land between the recording and this replay — a set
    // point always earns one — so the frames show the old ends. Remember it:
    // the live facing and ends go back on the moment the replay is over.
    this.replayStale = Math.abs(last.p.ry - this.player.athlete.rotation.y) > 0.1;
    this.replayState = this.state;
    this.state = 'replay';
    this.replayT = Math.max(buf[0].t, last.t - 3.0);
    this.replayEnd = last.t;
    this.replayI = 0;
    this.replaySide = last.b[0] >= 0 ? 1 : -1;
    // This replay carries the super strike's burn when the rally it closed
    // held one: the trail re-ignites at the strike's own recorded moment.
    this.replaySuper = this.superQueued;
    this.superQueued = false;
    this.superReplayDone = false;
    // The cut is instant, the way a broadcast replay cuts — to the low
    // side-line shot as always, or, on the net-cam pick, to a camera hung
    // on the post the play dies toward, above its pennant, looking down
    // the tape.
    if (replayNetCam()) {
      this.game.camera.position.set(
        this.replaySide * (NET_HALF_W + 0.3), 3.1, 0
      );
    } else {
      this.game.camera.position.set(this.replaySide * 6.4, 1.4, last.b[2]);
    }
    this.replayBanner = addText('REPLAY', {
      left: '50%',
      top: 'calc(env(safe-area-inset-top) + 92px)',
      transform: 'translateX(-50%)',
      padding: '4px 14px',
      borderRadius: '6px',
      backgroundColor: 'rgba(206, 38, 52, 0.85)',
      color: '#ffffff',
      fontSize: '13px',
      fontWeight: '800',
      letterSpacing: '4px'
    });
    // The booth's call rides over the banner for a point won clean — ACE!
    // or WHAT A BLOCK! — for a rally that held a super strike — SUPER
    // STRIKE! — whoever played it.
    if (this.replayCall) {
      this.replayCallText = addText(this.replayCall, {
        left: '50%',
        top: 'calc(env(safe-area-inset-top) + 62px)',
        transform: 'translateX(-50%)',
        fontSize: '19px',
        fontWeight: '800',
        letterSpacing: '3px',
        color: '#ffd24a',
        textShadow: '0 2px 8px rgba(20,40,60,0.65)'
      });
      this.replayCall = null;
    }
    playWhoosh();
  }

  /// Hands control back to the match: the serve countdown picks up where it
  /// paused, and the main camera eases home from the side line.
  endReplay() {
    if (this.replayBanner) {
      this.replayBanner.remove();
      this.replayBanner = null;
    }
    if (this.replayCallText) {
      this.replayCallText.remove();
      this.replayCallText = null;
    }
    // The shot-of-the-match replay hands the screen back to the recap: the
    // card and its pills return exactly where the player left them.
    if (this.shotReplay) {
      this.shotReplay = false;
      this.shotCloseBtn?.remove();
      this.shotCloseBtn = null;
      this.shotFrames = null;
      if (this.recapCard) this.recapCard.style.display = 'block';
      this.rematchBtn.style.display = 'block';
      this.menuBtn.style.display = 'block';
      if (this.shotBtn) this.shotBtn.style.display = 'block';
      this.state = 'over';
      haptic('tick');
      return;
    }
    this.state = this.replayState;
    // The replay drove both athletes off the recording — which, on a
    // changeover, was shot before the ends swapped. Without this, the whole
    // next set is played with backs to the net and a strike check that
    // refuses every bump: the live facing goes back, and a stale changeover
    // replay also hands everyone their new end again.
    this.faceSides();
    if (this.replayStale) {
      for (const w of this.allTeam()) {
        w.athlete.position.copy(w.home);
        w.vy = 0;
      }
    }
    this.replayStale = false;
  }

  /// The shot-of-the-match replay: the recording banked during the match
  /// plays over the dimmed court from the picked replay angle — SHOT OF
  /// THE MATCH riding the banner where the career reel rides its touch
  /// count — with a close button waiting to hand the screen back to the
  /// recap.
  beginShotReplay() {
    const frames = this.shotFrames;
    if (!frames || !frames.length) return;
    const last = frames[frames.length - 1];
    this.replayState = 'over';
    this.state = 'replay';
    this.replayT = frames[0].t;
    this.replayEnd = last.t;
    this.replayI = 0;
    this.replaySide = last.b[0] >= 0 ? 1 : -1;
    this.replaySuper = false;
    this.superReplayDone = false;
    this.replayStale = false;
    // The cut is instant, the way a broadcast replay cuts — to whichever
    // angle the settings pick: the low side-line shot, or the net cam hung
    // on the post looking down the tape.
    const cam = this.game.camera;
    if (replayNetCam()) {
      cam.position.set(
        this.replaySide * (NET_HALF_W + 0.3), 3.1, 0
      );
    } else {
      cam.position.set(this.replaySide * 6.4, 1.4, last.b[2]);
    }
    this.replayBanner = addText('REPLAY', {
      left: '50%',
      top: 'calc(env(safe-area-inset-top) + 92px)',
      transform: 'translateX(-50%)',
      padding: '4px 14px',
      borderRadius: '6px',
      backgroundColor: 'rgba(206, 38, 52, 0.85)',
      color: '#ffffff',
      fontSize: '13px',
      fontWeight: '800',
      letterSpacing: '4px'
    });
    // SHOT OF THE MATCH rides the banner where the career reel rides
    // its touch count: the gold moment's line over the broadcast band.
    this.replayCallText = addText('SHOT OF THE MATCH', {
      left: '50%',
      top: 'calc(env(safe-area-inset-top) + 62px)',
      transform: 'translateX(-50%)',
      fontSize: '19px',
      fontWeight: '800',
      letterSpacing: '3px',
      color: '#ffd24a',
      textShadow: '0 2px 8px rgba(20,40,60,0.65)'
    });
    this.shotCloseBtn = addButton({
      label: 'Close the replay',
      onPress: () => this.endReplay(),
      style: {
        position: 'absolute',
        width: '150px',
        height: '46px',
        left: 'calc(50% - 75px)',
        bottom: 'calc(env(safe-area-inset-bottom) + 48px)',
        borderRadius: '999px',
        backgroundColor: 'rgba(10, 18, 30, 0.55)',
        border: '1.5px solid rgba(255, 255, 255, 0.55)',
        color: '#ffffff',
        fontSize: '12px',
        fontWeight: '800',
        letterSpacing: '2px'
      }
    });
    this.shotCloseBtn.textContent = 'CLOSE';
    this.shotReplay = true;
    playWhoosh();
  }

  updateReplay(dt) {
    // The shot-of-the-match replay runs from its own banked frames; every
    // other replay runs from the rolling record.
    const buf = this.shotReplay ? this.shotFrames : this.recBuf;
    this.replayT += dt * 0.25; // quarter speed
    if (this.replayT >= this.replayEnd) {
      this.endReplay();
      return;
    }
    // The two recorded frames the playhead sits between.
    while (this.replayI < buf.length - 2 && buf[this.replayI + 1].t < this.replayT) {
      this.replayI++;
    }
    const fa = buf[this.replayI];
    const fb = buf[this.replayI + 1];
    const al = clamp((this.replayT - fa.t) / Math.max(0.0001, fb.t - fa.t), 0, 1);

    // The ball: flight, spin and squash all replayed as they happened.
    const mesh = this.ball.mesh;
    mesh.position.set(mix(fa.b[0], fb.b[0], al), mix(fa.b[1], fb.b[1], al), mix(fa.b[2], fb.b[2], al));
    mesh.scale.set(mix(fa.b[3], fb.b[3], al), mix(fa.b[4], fb.b[4], al), mix(fa.b[5], fb.b[5], al));
    this.tmpQ.set(fa.b[6], fa.b[7], fa.b[8], fa.b[9]);
    this.tmpQ2.set(fb.b[6], fb.b[7], fb.b[8], fb.b[9]);
    mesh.quaternion.slerpQuaternions(this.tmpQ, this.tmpQ2, al);

    for (const [w, k] of this.replayActors()) {
      this.replayAthlete(w.athlete, fa[k], fb[k], al);
    }

    // The super strike's burn, again: at the strike's own recorded moment
    // the flash bursts and the blazing trail lights up once more, burning
    // along the slow-motion flight from the sideline camera.
    if (this.replaySuper && !this.superReplayDone &&
        this.superRecT != null && this.replayT >= this.superRecT) {
      this.superReplayDone = true;
      this.flashT = 0;
      this.flashPos.copy(mesh.position);
      this.flashGroup.position.copy(mesh.position);
      this.flashGroup.visible = true;
      this.trailT = 1.3;
      this.trailTimer = 0;
    }
    // The flash rig runs through the replay: embers drop along the replayed
    // flight and fade, exactly as they did live.
    this.updateFlash(dt);

    // The two broadcast angles: the low side-line shot, at chest height,
    // drifting along the touchline with the ball as it always has — or the
    // net cam, hung still on its post and panning gently down the tape
    // after the play, its look point biased toward the tape so the white
    // band stays in frame.
    const cam = this.game.camera;
    const k = Math.min(1, dt * 3);
    if (replayNetCam()) {
      cam.position.x +=
        (this.replaySide * (NET_HALF_W + 0.3) - cam.position.x) * k;
      cam.position.y += (3.1 - cam.position.y) * k;
      cam.position.z += (0 - cam.position.z) * k;
      cam.lookAt(
        mix(mesh.position.x, -this.replaySide * 4.2, 0.45),
        Math.max(1.0, mesh.position.y * 0.55),
        clamp(mesh.position.z * 0.55, -4.2, 4.2)
      );
    } else {
      cam.position.x += (this.replaySide * 6.4 - cam.position.x) * k;
      cam.position.y += (1.4 + mesh.position.y * 0.08 - cam.position.y) * k;
      cam.position.z += (clamp(mesh.position.z * 0.85, -7.4, 7.4) - cam.position.z) * k;
      cam.lookAt(
        mesh.position.x * 0.6,
        Math.max(0.9, mesh.position.y * 0.55),
        mesh.position.z * 0.8
      );
    }
    // The breeze never stops for a replay: the flags and the haze keep
    // breathing behind the slow motion.
    this.updateWind(dt);
  }

  replayAthlete(a, fa, fb, al) {
    a.position.set(mix(fa.x, fb.x, al), mix(fa.y, fb.y, al), mix(fa.z, fb.z, al));
    a.rotation.y = mix(fa.ry, fb.ry, al);
    applyPose(a, fa.pose, fb.pose, al);
  }

  /// The athletes the replay drives, paired with their slot in each recorded
  /// frame — two in singles, the full foursome in doubles.
  replayActors() {
    const list = [[this.player, 'p'], [this.cpu, 'c']];
    if (this.doubles) list.push([this.partner, 'd'], [this.cpu2, 'e']);
    return list;
  }

  updateStates(dt) {
    // A queued replay runs before the serve countdown resumes.
    if ((this.state === 'point' || this.state === 'set') && this.replayPending) {
      this.replayPending = false;
      this.beginReplay();
      return;
    }
    if (this.state === 'point') {
      this.timer -= dt;
      if (this.timer <= 0) {
        // In the drill the machine reloads and feeds the next ball; the
        // normal flow re-serves.
        if (this.drill && this.nextServer === 'machine') this.machineFeed();
        else this.startServe(this.nextServer);
      }
    } else if (this.state === 'set') {
      // The longer pause after a set, while the sides swap over.
      this.timer -= dt;
      if (this.timer <= 0) this.startServe(this.nextServer, true);
    } else if (this.state === 'serve') {
      this.timer -= dt;
      if (this.timer <= 0) {
        if (this.serverAth === this.player || this.twoPlayer ||
            (this.coop && this.serverAth === this.partner)) {
          // The controlled serve: the ball waits in the server's hand until
          // they tap jump to toss it up. In the shared-screen modes every
          // human serve is struck by hand.
          this.state = 'serveReady';
          this.setMsg(`${this.serveMessage(this.server)} — TAP JUMP TO TOSS`);
        } else if (Math.random() < (this.cpuStyle
          ? Math.min(1, this.diff.jumpServe + this.cpuStyle.serveJump)
          : this.diff.jumpServe)) {
          // On the higher difficulties the CPU shows off: it tosses the ball
          // up like the player can and strikes near the top of the toss —
          // flat and fast when the timing holds, a float when it mistimes.
          this.startTossCpu(this.serverAth);
          this.cpuServeJumped = false;
          this.cpuServeT = clamp(
            TOSS_V / G + (Math.random() - 0.5) * 2 * this.diff.mistime * 2.5,
            0.12, 0.8
          );
        } else {
          // The CPU serves automatically: the whistle sets the rally going,
          // and the radar waits at the bump that carries the serve out.
          this.state = 'rally';
          this.autoServeLive = this.serverAth;
          playWhistle();
          this.ball.vel.set(0, -0.5, 0);
          this.ball.lastTouch = null;
          this.touches = { player: 0, cpu: 0 };
          this.setMsg('');
        }
      }
    } else if (this.state === 'challengeWait') {
      // The booth's offer is on the table: the CPU chews it over for a beat,
      // and a human offer expires when the window closes — either way the
      // call stands unless the review is taken.
      const rv = this.callReview;
      this.timer -= dt;
      if (rv.cpuAt != null) {
        rv.cpuAt -= dt;
        if (rv.cpuAt <= 0) {
          if (Math.random() < CHALLENGE_CPU) this.startChallenge();
          else this.resolveCall();
        }
      } else if (this.timer <= 0) {
        this.resolveCall();
      }
    }
  }

  /// The match clock: seconds on court roll up into a mm:ss pill. Slow motion
  /// doesn't stretch it and it freezes at the final point. The blitz counts
  /// the same seconds down instead.
  updateClock(dt) {
    if (this.state !== 'over') this.clock += dt;
    if (this.blitz) {
      this.updateBlitzClock();
      return;
    }
    const s = Math.floor(this.clock);
    if (s !== this.clockShown) {
      this.clockShown = s;
      const m = Math.floor(s / 60);
      this.timeText.textContent =
        `${String(m).padStart(2, '0')}:${String(s % 60).padStart(2, '0')}`;
    }
  }

  /// The blitz clock: the three minutes count down beside the score, the
  /// last ten seconds burning red. At the horn the match goes to whoever
  /// leads — unless the scores sit level, in which case the next point takes
  /// it. A live rally plays itself out before the horn settles anything.
  updateBlitzClock() {
    const left = Math.max(0, this.blitzT - this.clock);
    const s = Math.ceil(left);
    if (s !== this.clockShown) {
      this.clockShown = s;
      const m = Math.floor(s / 60);
      this.timeText.textContent =
        `${String(m).padStart(2, '0')}:${String(s % 60).padStart(2, '0')}`;
      this.timeText.style.color =
        s > 0 && s <= 10 ? '#ff8a7a' : 'rgba(255,255,255,0.92)';
    }
    // Sudden death runs without a clock; the horn has already blown once.
    if (this.blitzOver || this.blitzSD) return;
    if (left > 0) {
      // Half time: the match's one swap of ends, taken at the first dead
      // ball past the halfway mark so a live rally is never interrupted.
      if (!this.blitzHalf && left <= this.blitzT / 2 &&
          (this.state === 'serve' || this.state === 'serveReady' ||
            this.state === 'point' || this.state === 'set')) {
        this.blitzHalf = true;
        this.playerSide *= -1;
        this.applySides();
        for (const w of this.allTeam()) {
          w.athlete.position.copy(w.home);
          w.vy = 0;
        }
        this.camSwing = true;
        playCheer(false, 1.1);
        this.crowdWaveStart(0.8);
        this.setMsg('HALF TIME — SWITCHING SIDES!');
        haptic('tick');
      }
      return;
    }
    // The horn: mid-rally it waits for the point to die; between points it
    // settles the match on the spot.
    if (this.state === 'rally' || this.state === 'toss') {
      if (!this.blitzExpired) {
        this.blitzExpired = true;
        playSting();
        this.crowdRoar(1);
        this.setMsg('THE HORN!');
      }
      return;
    }
    const st = this.state;
    if (st === 'serve' || st === 'serveReady' || st === 'point' || st === 'set') {
      if (this.score.player === this.score.cpu) this.hornLevel();
      else this.endBlitzMatch(this.score.player > this.score.cpu ? 'player' : 'cpu');
    }
  }

  /// Level at the horn: sudden death — the tally names it, the booth calls
  /// it, and the very next point takes the match.
  hornLevel() {
    this.blitzSD = true;
    this.refreshTally();
    playSting();
    this.crowdRoar(1);
    this.setMsg('LEVEL AT THE HORN — SUDDEN DEATH! NEXT POINT TAKES IT!');
    haptic('point');
  }

  /// The blitz match ends at the horn — or on the sudden-death point: the
  /// celebration, the match log, the heat grids banking and the career tally
  /// all run as any match end does, with the blitz score as the headline.
  endBlitzMatch(winner) {
    this.blitzOver = true;
    this.state = 'over';
    playCheer(true);
    this.crowdWaveStart(1);
    this.matchWinner = winner;
    this.overT = 0;
    // The blitz's final rally banks its recording for the gold card too —
    // the horn's sudden-death ace included, the serve's own clip.
    this.bankShotReplay(this.rallyLen === 0);
    recordMatchLog({
      mode: 'BLITZ',
      opp: this.cpuStats.name.toUpperCase(),
      score: `${this.score.player}–${this.score.cpu}`,
      won: winner === 'player',
      aces: this.stats.aces.cpu,
      spikes: this.stats.spikes.cpu,
      date: dateKey()
    });
    recordHeatShots(this.heat);
    recordRivalHeatShots(this.heatRival);
    playFanfare();
    const titleBefore = playerTitle();
    this.shot = this.pickShotOfMatch();
    recordMatch(
      'cpu',
      winner === 'player',
      this.stats.points.player,
      this.stats.longestRally,
      this.stats.aces.player,
      this.stats.blocks.player,
      this.stats.clutch.won,
      this.stats.clutch.lost,
      this.stats.serveRun.best,
      this.stats.comebacks,
      this.shot ? 1 : 0
    ).forEach((id) => this.showBadgeToast(id));
    // The weekly goals read the blitz result the same way: a win banks
    // toward the wins goal.
    if (winner === 'player' && recordWeeklyStat('wins')) {
      this.showGoalToast('wins');
    }
    // The recruit's crossing, blitz flavour: the same in-play gold toast
    // when the horn settled the match on the win that signed her.
    if (this.novaChar && !this.novaBefore && winner === 'player' &&
        athleteUnlocked(this.novaChar)) {
      this.showToast(
        `RECRUIT SIGNED · ${this.novaChar.name} JOINS THE ROSTER`
      );
      takeAthleteToast(true);
    }
    const titleAfter = playerTitle();
    if (titleAfter.id !== titleBefore.id) this.showTitleToast(titleAfter);
    this.pendingHeadline = winner === 'player'
      ? `${playerName('p1')} WINS THE BLITZ ${this.score.player}–${this.score.cpu}!`
      : `CPU WINS THE BLITZ ${this.score.cpu}–${this.score.player}`;
    this.setMsg(this.pendingHeadline);
  }

  /// The rally counter beside the score: one number for every consecutive
  /// touch since the last dead ball. Each new touch pops it, and the longer
  /// the rally runs the bigger and warmer it burns — cool blue at two
  /// touches, fully lit orange by nine, where the commentator has already
  /// called it. The moment the ball dies it vanishes.
  updateRallyHud(dt) {
    // In the drill the streak stays on show while the machine reloads: the
    // run is still alive until a ball actually gets past the player.
    const live =
      (this.state === 'rally' || (this.drill && this.state === 'point')) &&
      this.rallyLen > 0;
    this.rallyText.style.opacity = live ? '1' : '0';
    if (!live) {
      this.rallyShown = 0;
      this.rallyPop = 0;
      return;
    }
    if (this.rallyLen !== this.rallyShown) {
      this.rallyShown = this.rallyLen;
      this.rallyPop = 1;
      // In practice the counter is the survival streak: the run of touches
      // kept alive against the CPU.
      this.rallyText.textContent = `${this.practice ? 'STREAK' : 'RALLY'} ${this.rallyLen}`;
      const t = clamp((this.rallyLen - 2) / 7, 0, 1);
      this.rallyText.style.fontSize = `${(13 + 7 * t).toFixed(1)}px`;
      this.rallyText.style.color = `rgb(${Math.round(0x9f + (0xff - 0x9f) * t)}, ${Math.round(0xd8 + (0x6a - 0xd8) * t)}, ${Math.round(0xff + (0x4d - 0xff) * t)})`;
    }
    if (this.rallyPop > 0) {
      this.rallyPop = Math.max(0, this.rallyPop - dt * 4);
      this.rallyText.style.transform =
        `scale(${(1 + 0.2 * this.rallyPop).toFixed(3)})`;
    }
  }

  /// The drama bed: the crowd is a living thing now — settling while a serve
  /// is prepared, swelling as a rally builds, surging on set point and
  /// through the tie-break, restless in the gaps between points. The
  /// heartbeat takes over on the big points, and a long, even battle earns
  /// the commentator's line.
  updateDrama(dt) {
    const deciding = this.tieBreak;
    const drama = this.state === 'rally' && (this.setPointSide() || deciding);
    // Match point: the standing state the whole arena reads — the murmur
    // swell, the chant and the terrace spotlight all hang off it, whatever
    // the rally is doing. Practice keeps its scoreboard dark and the blitz
    // plays no sets, so neither ever stands on match point.
    const mpUp = !this.practice && !this.blitz && this.isMatchPoint();
    const mpSide = mpUp ? this.setPointSide() : null;
    // The booth keeps quiet a while after each momentum call.
    this.momentumCallT = Math.max(0, this.momentumCallT - dt);

    // The murmur's level and character are read off the rally state every
    // frame, but only actual changes reach the audio graph — and each change
    // still glides in over half a second, so the crowd fades rather than
    // switches.
    let level;
    let bright;
    if (this.state === 'rally') {
      const build = clamp((this.rallyLen - 2) / 8, 0, 1);
      if (drama) {
        // The big points: the crowd surges and stays on its feet.
        level = 0.15 + 0.02 * build;
        bright = 0.7 + 0.3 * build;
      } else {
        // An ordinary rally: the longer it runs, the louder the arena gets.
        level = 0.05 + 0.07 * build;
        bright = 0.55 * build;
      }
    } else if (this.state === 'toss') {
      // The toss hangs in the air: the arena holds its breath.
      level = 0.025;
      bright = 0;
    } else if (this.state === 'serve' || this.state === 'serveReady') {
      // Waiting on the serve: the crowd settles.
      level = 0.035;
      bright = 0;
    } else if (this.state === 'over') {
      level = 0.02;
      bright = 0;
    } else {
      // Between points: a low, restless murmur that never quite sits still.
      level = 0.05 + 0.008 * Math.sin(this.clock * 0.9);
      bright = 0.05;
    }
    // The momentum reads into the crowd: whichever side owns the bar, the
    // arena gets slightly louder behind them — the ambience and the readout
    // tell the same story.
    level = Math.min(0.17, level + Math.abs(this.momentum) * 0.02);
    bright = Math.min(1, bright + Math.abs(this.momentum) * 0.15);
    // Match point stands: the arena raises its voice outright — the murmur
    // swells between points as much as through them, and the chant rises
    // behind it.
    if (mpUp) {
      level = Math.min(0.19, level + 0.05);
      bright = Math.min(1, bright + 0.2);
    }
    const l = Math.round(level * 400) / 400;
    const b = Math.round(bright * 10) / 10;
    // The chant rides on top of the murmur: its loudness is the size of the
    // surge, and its pitch tint follows the side the crowd is chanting for.
    // On match point it swells outright and beats for whoever stands one
    // point from taking the match, momentum or no momentum.
    let ch = Math.abs(this.momentum) * 0.6;
    let tn = this.momentum;
    if (mpUp) {
      ch = Math.max(ch, 0.5);
      tn = mpSide === 'player'
        ? Math.max(tn, 0.8)
        : Math.min(tn, -0.8);
    }
    ch = Math.round(Math.min(0.6, ch) * 50) / 50;
    tn = Math.round(tn * 10) / 10;
    // The crowd chants the name of whoever it is behind: the pulse beats in
    // that name's rhythm — a short name slow and heavy, a long one fast —
    // and an empty field keeps the steady heave-ho it has always beaten.
    const chantSide = mpUp
      ? (mpSide === 'player' ? 'p1' : 'p2')
      : (this.momentum >= 0 ? 'p1' : 'p2');
    const chantName = selectedName(chantSide);
    const rr = chantName ? Math.round(chantRate(chantName) * 10) / 10 : 2.4;
    if (l !== this.murmurLevel || b !== this.murmurBright ||
        ch !== this.murmurChant || tn !== this.murmurTint ||
        rr !== this.murmurRate) {
      this.murmurLevel = l;
      this.murmurBright = b;
      this.murmurChant = ch;
      this.murmurTint = tn;
      this.murmurRate = rr;
      murmur(l, b, ch, tn, rr);
    }
    // The stands read the same state the ambience does: how loud the crowd
    // is is how much the figures sway and lift in the terraces — and while
    // the match stands on match point they stay up between points too.
    this.crowdLiftTarget = drama ? 1 :
      mpUp ? 0.6 :
      this.state === 'rally' ? 0.25 + 0.75 * clamp((this.rallyLen - 2) / 8, 0, 1) :
      this.state === 'over' ? 0.25 : this.state === 'toss' ? 0.08 : 0.14;

    if (drama) {
      this.heartT -= dt;
      if (this.heartT <= 0) {
        this.heartT = this.setPointSide() ? 0.92 : 1.15;
        playHeartbeat(this.setPointSide() ? 1 : 0.7);
      }
    } else {
      this.heartT = 0.5;
    }

    // The calls from the script: a shout as the rally builds, then the
    // commentator's line once it has become a real battle. Each call fades
    // again so the next one can land.
    if (this.state === 'rally' && !this.hypeSaid) {
      const call =
        this.rallyLen === 4 ? 'UP!' :
        this.rallyLen === 6 ? 'KEEP IT ALIVE!' :
        this.rallyLen >= 9 ? 'NEITHER TEAM IS GIVING AN INCH!' : null;
      if (call) {
        if (this.rallyLen >= 9) this.hypeSaid = true;
        this.hypeT = 1.0;
        this.setMsg(call);
      }
    }
    if (this.hypeT > 0) {
      this.hypeT -= dt;
      if (this.hypeT <= 0 && this.state === 'rally') this.setMsg('');
    }
  }

  /// The celebration: the winner hops on the spot while the ball rests where
  /// it landed, and after a short pause to take the final point in, the recap
  /// card drops over the dimmed court.
  updateFinale(dt) {
    if (this.state !== 'over') return;
    this.overT += dt;
    for (const w of this.matchWinner === 'player' ? this.nearTeam() : this.farTeam()) {
      w.athlete.position.y = Math.abs(Math.sin(this.overT * 5)) * 0.55;
    }
    if (!this.recapShown && this.overT >= 2.2) {
      this.recapShown = true;
      if (this.cupMatch) {
        // The cup owns the flow: a win moves the bracket on — or lifts the
        // trophy — while a loss ends the run back at the title.
        if (this.matchWinner === 'player') {
          if (this.cupMatch.round >= 3) completeCup();
          else advanceCup();
        } else {
          endCup();
        }
        this.game.start(BootScene);
      } else if (this.dailyMatch) {
        // The daily owns the flow too: the one attempt banks its result for
        // the day, and the title reopens the card to show what happened.
        finishDaily(this.matchWinner === 'player');
        this.game.start(BootScene);
      } else if (this.ladderMatch) {
        // The ladder owns the flow: the result moves the rank one rung — up
        // for a win, down for a loss, never below the first — and the title
        // reopens the ladder at the new rank.
        finishLadder(this.matchWinner === 'player');
        this.game.start(BootScene);
      } else if (this.seriesWon) {
        this.showSeriesCard();
      } else {
        this.showRecap(this.pendingHeadline);
      }
    }
    // The series card is brief: it sends the player back to the title on
    // its own a few seconds after it lands.
    if (this.seriesCardT > 0) {
      this.seriesCardT -= dt;
      if (this.seriesCardT <= 0) this.game.start(BootScene);
    }
  }

  /// Keeps the breeze alive: the pennants stream downwind and flutter with
  /// its strength, and the sand haze drifts across the court the same way,
  /// wrapping round to the upwind side when a wisp leaves the play area.
  updateWind(dt) {
    this.windT += dt;
    const w = this.wind;
    const heading = Math.atan2(-w.z, w.x);
    for (let i = 0; i < this.pennants.length; i++) {
      const p = this.pennants[i];
      p.rotation.y =
        heading + Math.sin(this.windT * (5.5 + i * 1.3) + i * 2.1) * 0.32 * w.strength;
      p.rotation.z = Math.sin(this.windT * 8.5 + i * 1.7) * 0.1 * w.strength;
      p.scale.x = 0.45 + 0.55 * Math.min(1, w.strength);
      p.scale.y = 0.82 + 0.18 * Math.min(1, w.strength);
    }
    // The haze re-poses at 30Hz like the crowd: every second call banks its
    // dt, so the wisps drift in time while the instance rebuild runs at half
    // the frame rate.
    this.hazeBudget = (this.hazeBudget || 0) + dt;
    this.hazeTick = ((this.hazeTick || 0) + 1) % 2;
    if (!this.hazeTick) return;
    dt = this.hazeBudget;
    this.hazeBudget = 0;
    for (let i = 0; i < this.hazeSeeds.length; i++) {
      const s = this.hazeSeeds[i];
      s.d += w.strength * (1.2 + s.sp) * dt;
      if (s.d > 15) {
        s.d -= 30;
        s.lane = Math.random() * 18 - 9;
      }
      this.dummy.position.set(
        w.x * s.d - w.z * s.lane,
        0.14 + Math.sin(this.windT * 1.4 + s.ph) * 0.06,
        w.z * s.d + w.x * s.lane
      );
      this.dummy.rotation.set(-Math.PI / 2, 0, heading);
      this.dummy.scale.set(1.5, 1, 1);
      this.dummy.updateMatrix();
      this.haze.setMatrixAt(i, this.dummy.matrix);
    }
    this.haze.instanceMatrix.needsUpdate = true;
  }

  /// The hard-strike flash rig: one additive shockwave sphere, a burst of
  /// speed lines radiating from the contact point, and a pool of embers the
  /// ball drags behind it while the trail burns — the supersonic moment.
  buildFlash() {
    this.flashGroup = new THREE.Group();
    this.flashGroup.visible = false;
    this.root.add(this.flashGroup);

    this.flashRing = new THREE.Mesh(
      new THREE.SphereGeometry(0.5, 20, 14),
      new THREE.MeshBasicMaterial({
        color: 0xcfe8ff, transparent: true, opacity: 0,
        blending: THREE.AdditiveBlending, depthWrite: false, fog: false
      })
    );
    this.flashGroup.add(this.flashRing);

    const lineGeo = new THREE.BoxGeometry(0.03, 0.03, 1);
    this.flashLineMat = new THREE.MeshBasicMaterial({
      color: 0xfff3c8, transparent: true, opacity: 0,
      blending: THREE.AdditiveBlending, depthWrite: false, fog: false
    });
    this.flashLines = [];
    this.flashLineDir = [];
    const axisZ = new THREE.Vector3(0, 0, 1);
    for (let i = 0; i < 10; i++) {
      const m = new THREE.Mesh(lineGeo, this.flashLineMat);
      const d = new THREE.Vector3(
        Math.random() * 2 - 1,
        Math.random() * 1.4 - 0.2,
        Math.random() * 2 - 1
      ).normalize();
      m.quaternion.setFromUnitVectors(axisZ, d);
      this.flashGroup.add(m);
      this.flashLines.push(m);
      this.flashLineDir.push(d);
    }

    this.trail = [];
    const ghostGeo = new THREE.SphereGeometry(BALL_R * 0.6, 10, 8);
    for (let i = 0; i < 18; i++) {
      const g = new THREE.Mesh(ghostGeo, new THREE.MeshBasicMaterial({
        color: 0xffe9b0, transparent: true, opacity: 0,
        blending: THREE.AdditiveBlending, depthWrite: false, fog: false
      }));
      g.visible = false;
      g.userData.life = 0;
      this.root.add(g);
      this.trail.push(g);
    }
    this.flashPos = new THREE.Vector3();
  }

  /// Lights the flash up at the contact point.
  spawnFlash(pos) {
    this.flashT = 0;
    this.flashPos.copy(pos);
    this.flashGroup.position.copy(pos);
    this.flashGroup.visible = true;
    this.trailT = 0.7;
    this.trailTimer = 0;
    playZap();
  }

  /// Runs the flash: the ring blows out and fades, the speed lines streak
  /// away from the contact point, and while the trail burns, embers drop
  /// along the ball's flight and each fades in under half a second.
  updateFlash(dt) {
    if (this.trailT > 0) {
      this.trailT -= dt;
      this.trailTimer -= dt;
      const bp = this.ball.mesh.position;
      while (this.trailTimer <= 0 && this.trailT > 0) {
        this.trailTimer += 0.028;
        const g = this.trail[this.trailI];
        this.trailI = (this.trailI + 1) % this.trail.length;
        g.position.copy(bp);
        g.userData.life = 1;
        g.visible = true;
      }
    }
    for (const g of this.trail) {
      if (!g.visible) continue;
      g.userData.life -= dt * 2.6;
      if (g.userData.life <= 0) {
        g.visible = false;
        continue;
      }
      const l = g.userData.life;
      g.scale.setScalar(0.55 * l + 0.1);
      g.material.opacity = 0.5 * l;
    }

    if (this.flashT < 1) {
      this.flashT = Math.min(1, this.flashT + dt / 0.38);
      const e = this.flashT;
      const ease = 1 - (1 - e) * (1 - e);
      this.flashRing.scale.setScalar(0.25 + 2.4 * ease);
      this.flashRing.material.opacity = 0.85 * (1 - e);
      for (let i = 0; i < this.flashLines.length; i++) {
        const li = this.flashLines[i];
        const le = clamp(e * 1.25 - i * 0.02, 0, 1);
        li.position.copy(this.flashLineDir[i]).multiplyScalar(0.5 + 2.6 * ease);
        li.scale.set(1, 1, 0.3 + 1.7 * le);
      }
      this.flashLineMat.opacity = 0.9 * (1 - e);
      if (this.flashT >= 1) {
        this.flashGroup.visible = false;
        this.flashRing.material.opacity = 0;
        this.flashLineMat.opacity = 0;
      }
    }
  }

  // ---------------------------------------------------------------- marks

  /// The landing marks: a small pool of flat chalk-white discs laid where a
  /// shot dies on the court, at the review mark's height — above the court
  /// lines, under nothing — one shared geometry and one material a disc,
  /// the oldest reused first so a dozen is all there ever is. Purely visual:
  /// they take no part in the ball's flight or anyone's reach.
  buildMarks() {
    this.marks = [];
    this.markI = 0;
    const geo = new THREE.CircleGeometry(0.12, 20);
    for (let i = 0; i < 12; i++) {
      const m = new THREE.Mesh(geo, new THREE.MeshBasicMaterial({
        color: 0xf5f1e6, transparent: true, opacity: 0, depthWrite: false
      }));
      m.rotation.x = -Math.PI / 2;
      m.renderOrder = 3;
      m.visible = false;
      m.userData.life = 0;
      this.root.add(m);
      this.marks.push(m);
    }
  }

  /// A shot has died in bounds: the next pooled disc takes the spot, bright
  /// and fresh, and starts its fade.
  spawnLandingMark(x, z) {
    const m = this.marks[this.markI];
    this.markI = (this.markI + 1) % this.marks.length;
    m.position.set(x, 0.035, z);
    m.userData.life = 1;
    m.visible = true;
  }

  /// The fade: a few seconds of life per mark, easing out, then the disc
  /// waits in the pool for the next landing to reuse it.
  updateMarks(dt) {
    for (const m of this.marks) {
      if (!m.visible) continue;
      m.userData.life -= dt / MARK_LIFE;
      if (m.userData.life <= 0) {
        m.visible = false;
        continue;
      }
      m.material.opacity = 0.6 * m.userData.life;
    }
  }

  /// The sand spray: one instanced mesh of small grain quads, pooled, tinted
  /// per theme — pale sand outdoors, blue floor dust under the indoor roof.
  /// Hard moves kick it up: a dive, a launch's shove and landing, and the
  /// strides of a long rally.
  buildSpray() {
    const geo = new THREE.PlaneGeometry(0.075, 0.075);
    const mat = new THREE.MeshBasicMaterial({
      color: 0xffffff,
      transparent: true,
      opacity: 0.7,
      depthWrite: false,
      side: THREE.DoubleSide,
      fog: false
    });
    this.sprayMesh = new THREE.InstancedMesh(geo, mat, SPRAY_MAX);
    this.sprayMesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    this.sprayMesh.frustumCulled = false;
    // Indoors the grains ride above the polished floor's draw order, so the
    // see-through surface cannot dim them.
    this.sprayMesh.renderOrder = this.theme.indoor ? 3 : 2;
    this.sprayBase = new THREE.Color(this.theme.indoor ? 0x9fc4e0 : 0xf3e6cf);
    this.sprayCol = new THREE.Color();
    for (let i = 0; i < SPRAY_MAX; i++) this.sprayMesh.setColorAt(i, this.sprayBase);
    this.spray = [];
    for (let i = 0; i < SPRAY_MAX; i++) {
      this.spray.push({
        life: 0, max: 1, x: 0, y: 0, z: 0,
        vx: 0, vy: 0, vz: 0, size: 1, rot: 0, spin: 0
      });
    }
    this.sprayNext = 0;
    this.sprayDummy = new THREE.Object3D();
    this.sprayLive = false;
    // Every grain starts hidden: a zero-scale matrix draws nothing.
    this.hideSpray();
    this.root.add(this.sprayMesh);
  }

  hideSpray() {
    const d = this.sprayDummy;
    d.scale.setScalar(0);
    d.position.set(0, -20, 0);
    d.updateMatrix();
    for (let i = 0; i < SPRAY_MAX; i++) this.sprayMesh.setMatrixAt(i, d.matrix);
    this.sprayMesh.instanceMatrix.needsUpdate = true;
  }

  /// A burst of grains at the surface: `n` of them burst out in every
  /// direction, thrown up a little and (with dirX/dirZ) back behind the move
  /// that kicked them.
  spawnSpray(x, z, n, opts = {}) {
    if (!this.sprayMesh) return;
    const spread = opts.spread ?? 0.6;
    const up = opts.up ?? 1.2;
    const dirX = opts.dirX ?? 0;
    const dirZ = opts.dirZ ?? 0;
    const back = opts.back ?? 0.5;
    const size = opts.size ?? 1;
    for (let k = 0; k < n; k++) {
      const g = this.spray[this.sprayNext];
      this.sprayNext = (this.sprayNext + 1) % SPRAY_MAX;
      const a = Math.random() * Math.PI * 2;
      const r = Math.random();
      g.x = x + Math.cos(a) * r * spread * 0.35;
      g.z = z + Math.sin(a) * r * spread * 0.35;
      g.y = 0.04 + Math.random() * 0.06;
      g.vx = Math.cos(a) * r * spread * 2.2 - dirX * back;
      g.vz = Math.sin(a) * r * spread * 2.2 - dirZ * back;
      g.vy = up * (0.5 + Math.random() * 0.7);
      g.max = 0.42 + Math.random() * 0.35;
      g.life = g.max;
      g.size = size * (0.7 + Math.random() * 0.8);
      g.rot = Math.random() * Math.PI;
      g.spin = (Math.random() - 0.5) * 9;
    }
  }

  /// The grains in flight: thrown outward, pulled down, skipping once off the
  /// surface as they lose their bite, and shrinking away inside a second.
  updateSpray(dt) {
    if (!this.sprayMesh) return;
    const d = this.sprayDummy;
    let live = false;
    for (let i = 0; i < SPRAY_MAX; i++) {
      const g = this.spray[i];
      if (g.life > 0) {
        live = true;
        g.life -= dt;
        const t = Math.max(0, g.life / g.max);
        g.vy -= SPRAY_G * dt;
        g.x += g.vx * dt;
        g.y += g.vy * dt;
        g.z += g.vz * dt;
        if (g.y < 0.02) {
          g.y = 0.02;
          g.vy *= -0.25;
          g.vx *= 0.6;
          g.vz *= 0.6;
        }
        g.rot += g.spin * dt;
        d.position.set(g.x, g.y, g.z);
        // The grains lie almost flat on the surface, drifting and turning as
        // they fall — a low kicked-up sheet rather than a puffball.
        d.rotation.set(-Math.PI / 2 + 0.25, 0, g.rot);
        d.scale.setScalar(g.size * t);
        d.updateMatrix();
        this.sprayMesh.setMatrixAt(i, d.matrix);
      } else if (g.life > -1) {
        // Just died: drop its matrix out of the picture once.
        g.life = -2;
        d.position.set(0, -20, 0);
        d.rotation.set(0, 0, 0);
        d.scale.setScalar(0);
        d.updateMatrix();
        this.sprayMesh.setMatrixAt(i, d.matrix);
      }
    }
    if (live || this.sprayLive) {
      this.sprayMesh.instanceMatrix.needsUpdate = true;
      this.sprayLive = live;
    }
  }

  /// One reflection frame, node for node: the root transform, the visual's
  /// lean and facing, and every bone of the skeleton — the mirror rig has
  /// the same bones in the same order, being the same model.
  syncMirror(m, src) {
    m.position.copy(src.position);
    m.rotation.copy(src.rotation);
    const md = m.userData;
    const sd = src.userData;
    md.visual.position.copy(sd.visual.position);
    md.visual.rotation.copy(sd.visual.rotation);
    const n = Math.min(md.bones.length, sd.bones.length);
    for (let i = 0; i < n; i++) {
      const b = md.bones[i];
      const s = sd.bones[i];
      b.position.copy(s.position);
      b.quaternion.copy(s.quaternion);
      b.scale.copy(s.scale);
    }
  }

  /// Copies the live world into the mirror world. Runs before the frame's
  /// simulation, so the image lags a single frame; the machine, when there
  /// is one, follows the recoil and the drill toggle like the athletes do.
  updateReflections() {
    if (!this.mirrorRoot) return;
    this.syncMirror(this.player.mirror, this.player.athlete);
    this.syncMirror(this.cpu.mirror, this.cpu.athlete);
    this.cpu.mirror.visible = this.cpu.athlete.visible;
    if (this.doubles) {
      this.syncMirror(this.partner.mirror, this.partner.athlete);
      this.syncMirror(this.cpu2.mirror, this.cpu2.athlete);
      this.partner.mirror.visible = this.partner.athlete.visible;
      this.cpu2.mirror.visible = this.cpu2.athlete.visible;
    }
    const b = this.ball.mesh;
    const bm = this.ball.mirror;
    bm.position.copy(b.position);
    bm.quaternion.copy(b.quaternion);
    bm.scale.copy(b.scale);
    if (this.machineMirror) {
      this.machineMirror.position.copy(this.machineGroup.position);
      this.machineMirror.visible = this.machineGroup.visible;
    }
  }

  /// The pre-match flyover: the camera starts high behind the net and sweeps
  /// down on a slow arc into its playing position over about three seconds —
  /// the match's one establishing shot, run at the top of every match and
  /// never between sets. Nothing simulates while it flies; the breeze keeps
  /// breathing and the opening call — the court theme and the wind — sits on
  /// screen as usual. Any tap on the court cuts the rest short.
  updateFlyover(dt) {
    this.flyT -= dt;
    const done = this.flyT <= 0;
    if (done) this.flyT = 0;
    const t = clamp(1 - this.flyT / FLY_T, 0, 1);
    const e = t * t * (3 - 2 * t); // smoothstep, so the arc eases in and out
    const cam = this.game.camera;
    // The sweep lands in whichever camera the match plays in: the usual
    // behind-the-player spot, or the broadcast pedestal when the toggle is
    // on — the sweep ends where the first serve will be watched from.
    const bc = broadcastCamera();
    const bp = this.broadcastPose();
    cam.position.set(
      mix(4.4, bc ? bp.x : 0, e),
      mix(8.8, bc ? bp.y : this.camBase.y, e),
      mix(-this.playerSide * 2.8, bc ? 0 : this.playerSide * this.camBase.z, e)
    );
    cam.lookAt(
      mix(2.2, 0, e),
      mix(0.4, bc ? 1.2 : 1.5, e),
      mix(-this.playerSide * 2.4, bc ? 0 : -this.playerSide * 1.6, e)
    );
    // The team sheet rides the sweep: it slides in as the camera lifts off —
    // the first frame commits the off-screen start, so the transition runs —
    // and it slides away the moment the camera lands.
    if (!this.introShown) {
      this.introShown = true;
      this.introCard.style.transform = 'translate(0, -50%)';
      this.introCard.style.opacity = '1';
    }
    // The breeze never stops for a camera move: the flags and the haze keep
    // living behind the sweep, and the stands stay alive with them.
    this.updateWind(dt);
    this.updateCrowd(dt);
    if (done) {
      // The camera has landed: the team sheet slides away with the sweep.
      this.introCard.style.transform = 'translate(-230px, -50%)';
      this.introCard.style.opacity = '0';
      // Stray taps on the control buttons while the sweep ran must not fire
      // the moment play resumes.
      this.wantJump = this.wantDive = this.wantStrike = false;
      this.wantLaunch = this.wantSuper = false;
      this.wantJump2 = this.wantDive2 = this.wantStrike2 = false;
      this.wantLaunch2 = this.wantSuper2 = false;
      // The arena greets the player by name as the camera lands.
      this.callPlayerName();
    }
  }

  /// The people say the player's name aloud: the typed name from the title
  /// screen, spoken in the device's own voice over the crowd. An empty name
  /// field keeps the arena quiet — there is no name to call.
  callPlayerName() {
    const name = playerName('p1');
    if (name) speakName(name);
  }

  // ------------------------------------------------------------ huddle

  /// One line summing the set just played, for the huddle's booth call: the
  /// finished score the right way round for the side that took it, softened to
  /// "they edge it" when it was a two-point set.
  setSummary(winner, comeback) {
    const parts = (this.setScores[this.setScores.length - 1] || '0–0')
      .split('–');
    const p = Number(parts[0]) || 0;
    const c = Number(parts[1]) || 0;
    const line = winner === 'player'
      ? (this.twoPlayer
        ? `${playerName('p1')} TAKE IT ${p}–${c}!`
        : `YOU TAKE IT ${p}–${c}!`)
      : this.twoPlayer
        ? `${playerName('p2')} TAKE IT ${c}–${p}!`
        : Math.abs(p - c) <= 1
          ? `THEY EDGE IT ${c}–${p}`
          : `THEY TAKE IT ${c}–${p}`;
    return (comeback ? 'WHAT A COMEBACK! ' : '') + line;
  }

  /// The end-of-set huddle: both teams walk to the tape and group up with a
  /// small bounce while the booth sums the set just played over a short
  /// whistle, then walk out to the ends the next set is played from. It owns
  /// the frame for a few seconds and a tap skips it, exactly like the
  /// pre-match sweep. In doubles all four athletes huddle at their own sides.
  beginHuddle(summary) {
    const side = this.playerSide;
    const members = [];
    const group = (team, z) => {
      team.forEach((w, i) => {
        members.push({
          w,
          spot: new THREE.Vector3((i - (team.length - 1) / 2) * 1.15, 0, z)
        });
      });
    };
    group(this.nearTeam(), side * 1.45);
    group(this.farTeam(), -side * 1.45);
    this.huddle = { t: 0, members };
    this.state = 'set';
    this.timer = 0;
    this.setMsg(summary);
    playWhistle(0.32);
    // The set-break team talk: a small card slides up over the huddle with
    // two tactics for the next set.
    this.showTeamTalk();
  }

  /// The huddle itself: everyone walks in to their spot on their own side of
  /// the tape, bounces together while the booth speaks, then walks back out.
  updateHuddle(dt) {
    const h = this.huddle;
    h.t += dt;
    const holdEnd = HUDDLE_GATHER + HUDDLE_HOLD;
    const walkingHome = h.t > holdEnd;
    for (const m of h.members) {
      const a = m.w.athlete;
      const target = walkingHome ? m.w.home : m.spot;
      const dx = target.x - a.position.x;
      const dz = target.z - a.position.z;
      const dist = Math.hypot(dx, dz);
      if (dist > 0.04) {
        const step = Math.min(dist, dt * 3.4);
        a.position.x += (dx / dist) * step;
        a.position.z += (dz / dist) * step;
        m.w.dir.x = dx / dist;
        m.w.dir.z = dz / dist;
        m.w.runMag = Math.min(1, 0.35 + dist);
      } else {
        m.w.runMag = 0;
      }
      // Grouped at the tape: the whole huddle bounces together, once.
      const bounce = h.t > HUDDLE_GATHER && !walkingHome
        ? Math.max(0, Math.sin((h.t - HUDDLE_GATHER) * 6.5)) * 0.055
        : 0;
      a.position.y = bounce;
      this.updateAthleteMotion(m.w, dt);
    }
    // The world keeps breathing behind the huddle.
    this.updateWind(dt);
    this.updateCrowd(dt);
    this.updateMarks(dt);
    this.updateSpray(dt);
    if (h.t >= holdEnd + HUDDLE_BACK) this.finishHuddle();
  }

  /// The huddle breaks: everyone stands on their new end and the serve
  /// countdown, held at zero through the break, runs straight on.
  finishHuddle() {
    if (!this.huddle) return;
    this.huddle = null;
    this.hideTeamTalk();
    for (const w of this.allTeam()) {
      w.athlete.position.copy(w.home);
      w.athlete.position.y = 0;
      w.vy = 0;
      w.runMag = 0;
      w.dir.x = 0;
      w.dir.z = 0;
      setDiveLean(w.athlete, 0);
    }
    this.setMsg('');
    this.state = 'set';
    this.timer = 0.05;
  }

  // ------------------------------------------------------------ team talk

  /// The set-break team talk: a small card slides up over the huddle with two
  /// tactics for the near team — PUSH THE PACE, quicker feet and harder shots,
  /// or HOLD THE LINE, a tighter aim and a longer reach at the ball. One tap
  /// picks one and dismisses the card; leaving it alone picks nothing. The CPU
  /// picks its own on the same beat, at random.
  showTeamTalk() {
    this.hideTeamTalk();
    const last = this.setScores[this.setScores.length - 1] || '0–0';
    const card = addText('', {
      left: '50%',
      bottom: 'calc(env(safe-area-inset-bottom) + 128px)',
      width: 'min(300px, 88vw)',
      height: '190px',
      transform: 'translate(-50%, 8px)',
      borderRadius: '18px',
      backgroundColor: 'rgba(8, 14, 26, 0.9)',
      border: '1px solid rgba(255, 214, 110, 0.3)',
      opacity: '0',
      transition: 'opacity 0.3s ease, transform 0.3s ease',
      pointerEvents: 'none'
    });
    card.appendChild(addText('SET BREAK', {
      left: '0',
      right: '0',
      top: '12px',
      textAlign: 'center',
      fontSize: '12px',
      fontWeight: '800',
      letterSpacing: '3px',
      color: '#ffd24a'
    }));
    card.appendChild(addText(`THAT SET WENT ${last}`, {
      left: '0',
      right: '0',
      top: '30px',
      textAlign: 'center',
      fontSize: '9px',
      fontWeight: '700',
      letterSpacing: '1px',
      color: 'rgba(255, 255, 255, 0.5)'
    }));
    const option = (top, id, label, desc) => {
      const btn = addButton({
        label,
        onPress: () => this.pickTeamTalk(id),
        style: {
          position: 'absolute',
          left: '10px',
          right: '10px',
          top: `${top}px`,
          width: 'auto',
          height: '46px',
          borderRadius: '12px',
          backgroundColor: 'rgba(255, 255, 255, 0.06)',
          border: '1px solid rgba(255, 210, 74, 0.35)',
          pointerEvents: 'auto'
        }
      });
      btn.appendChild(addText(label, {
        left: '12px',
        right: '8px',
        top: '7px',
        textAlign: 'left',
        fontSize: '11px',
        fontWeight: '800',
        letterSpacing: '1px',
        color: '#ffd24a'
      }));
      btn.appendChild(addText(desc, {
        left: '12px',
        right: '8px',
        top: '23px',
        textAlign: 'left',
        fontSize: '9px',
        fontWeight: '600',
        color: 'rgba(255, 255, 255, 0.6)'
      }));
      return btn;
    };
    this.talkPaceBtn = option(46, 'pace', 'PUSH THE PACE',
      'QUICKER FEET, HARDER SHOTS');
    this.talkLineBtn = option(100, 'line', 'HOLD THE LINE',
      'TIGHTER AIM, A LONGER REACH');
    const skip = addButton({
      label: 'Skip the team talk',
      onPress: () => this.hideTeamTalk(),
      style: {
        position: 'absolute',
        left: 'calc(50% - 52px)',
        top: '154px',
        width: '104px',
        height: '28px',
        borderRadius: '999px',
        backgroundColor: 'rgba(10, 18, 30, 0.4)',
        border: '1px solid rgba(255, 255, 255, 0.35)',
        color: '#ffffff',
        fontSize: '9px',
        fontWeight: '700',
        letterSpacing: '1px',
        pointerEvents: 'auto'
      }
    });
    skip.textContent = 'SKIP';
    card.appendChild(this.talkPaceBtn);
    card.appendChild(this.talkLineBtn);
    card.appendChild(skip);
    this.talkCard = card;
    this.talkSkip = skip;
    // The slide up — and the CPU's own pick, on the same beat.
    this.talkT = setTimeout(() => {
      if (this.talkCard !== card) return;
      card.style.opacity = '1';
      card.style.transform = 'translate(-50%, 0)';
    }, 30);
    this.cpuTalk = Math.random() < 0.5 ? 'pace' : 'line';
  }

  /// The tactic chosen: it stands for the next set, and the card steps aside.
  pickTeamTalk(id) {
    this.teamTalk = id;
    this.setMsg(id === 'pace' ? 'PUSH THE PACE!' : 'HOLD THE LINE!');
    this.hideTeamTalk();
    haptic('tick');
  }

  hideTeamTalk() {
    clearTimeout(this.talkT);
    this.talkT = null;
    this.talkCard?.remove();
    this.talkSkip?.remove();
    this.talkPaceBtn?.remove();
    this.talkLineBtn?.remove();
    this.talkCard = null;
    this.talkSkip = null;
    this.talkPaceBtn = null;
    this.talkLineBtn = null;
  }

  /// Which tactic stands for an athlete's side: the near team's picked talk,
  /// or the CPU's random one for the far side.
  talkKind(who) {
    const side = who === 'cpu' || who === 'cpu2' ? 'cpu' : 'player';
    return side === 'cpu' ? this.cpuTalk : this.teamTalk;
  }

  /// The talk's share of the pace: a side that pushed the pace runs and
  /// strikes a touch quicker for the set.
  talkSpeed(who) {
    return this.talkKind(who) === 'pace' ? 1.08 : 1;
  }

  talkPace(who) {
    return this.talkKind(who) === 'pace' ? 1.06 : 1;
  }

  /// ...and the line's share: a side holding the line reaches a touch further
  /// and reads the play sooner, with its aim held tighter.
  talkReach(who) {
    return this.talkKind(who) === 'line' ? 1.1 : 1;
  }

  talkAim(who) {
    return this.talkKind(who) === 'line' ? 0.5 : 1;
  }

  // ------------------------------------------------------------ victory lap

  /// The victory lap: on a won match the near team jogs out along their own
  /// baseline and back, bouncing with the crowd on its feet, while the losers
  /// walk to the net. It holds the frame for a couple of seconds, a tap skips
  /// it, and the recap (or whichever flow owns the match) takes over the
  /// moment it ends. A lost match never runs it.
  startVictoryLap() {
    const side = this.playerSide;
    const members = [];
    // The winners jog out along their own baseline, each to a spot of his own
    // so a doubles pair never runs into itself; the beaten side walks in to
    // the tape and stays there.
    const near = this.nearTeam();
    near.forEach((w, i) => {
      members.push({
        w,
        kind: 'win',
        home: w.home.clone(),
        out: new THREE.Vector3(side * (2.2 + i * 1.5), 0, w.home.z)
      });
    });
    const far = this.farTeam();
    far.forEach((w, i) => {
      members.push({
        w,
        kind: 'lose',
        home: w.home.clone(),
        out: new THREE.Vector3((i - (far.length - 1) / 2) * 1.1, 0, -side * 1.8)
      });
    });
    this.victoryLap = { t: 0, members };
    this.crowdWaveStart(1);
  }

  /// The lap itself: out along the baseline, back to the home spots.
  updateVictoryLap(dt) {
    const lap = this.victoryLap;
    lap.t += dt;
    const goingOut = lap.t < 1.2;
    for (const m of lap.members) {
      const a = m.w.athlete;
      const target = goingOut ? m.out : (m.kind === 'win' ? m.home : m.out);
      const dx = target.x - a.position.x;
      const dz = target.z - a.position.z;
      const dist = Math.hypot(dx, dz);
      if (dist > 0.05) {
        const step = Math.min(dist, dt * 3.4);
        a.position.x += (dx / dist) * step;
        a.position.z += (dz / dist) * step;
        m.w.dir.x = dx / dist;
        m.w.dir.z = dz / dist;
        m.w.runMag = Math.min(1, 0.45 + dist);
      } else {
        m.w.runMag = 0;
      }
      // The winners bounce as they jog; the beaten side just walks.
      a.position.y = m.kind === 'win'
        ? Math.abs(Math.sin(lap.t * 6.5)) * 0.12
        : 0;
      this.updateAthleteMotion(m.w, dt);
    }
    // The arena keeps living behind the celebration.
    this.updateWind(dt);
    this.updateCrowd(dt);
    this.updateMarks(dt);
    this.updateSpray(dt);
    if (lap.t >= 2.4) this.finishVictoryLap();
  }

  /// The lap breaks: everyone stands, and the finale takes the match on from
  /// where it was held — the recap (or the mode's own flow) right away.
  finishVictoryLap() {
    if (!this.victoryLap) return;
    this.victoryLap = null;
    for (const w of this.allTeam()) {
      w.athlete.position.y = 0;
      w.vy = 0;
      w.runMag = 0;
      w.dir.x = 0;
      w.dir.z = 0;
    }
    // The celebration the finale would have played out has already happened.
    this.overT = 2.2;
  }

  // ------------------------------------------------------------ coin toss

  /// The toss's call pills: they rise the moment the flyover lands — HEADS
  /// and TAILS beside a caption naming whoever holds the call. In a
  /// two-player match player two calls it; in doubles the call picks which
  /// team serves first.
  showTossPills() {
    const t = this.coinToss;
    const caption = t.caller === 'cpu'
      ? `${playerName('p2') || 'P2'} CALLS THE COIN`
      : 'CALL THE COIN · WINNER SERVES FIRST';
    t.pills = addText(caption, {
      left: '0', right: '0', textAlign: 'center',
      bottom: 'calc(env(safe-area-inset-bottom) + 218px)',
      fontSize: '11px', fontWeight: '800', letterSpacing: '2px',
      color: '#ffd24a', textShadow: '0 1px 4px rgba(20,40,60,0.6)'
    });
    const pill = (label, far) => addButton({
      label: `Call ${label}`,
      onPress: () => this.resolveTossCall(label),
      style: {
        position: 'absolute',
        width: '64px', height: '40px',
        left: far ? 'calc(50% + 10px)' : 'calc(50% - 74px)',
        bottom: 'calc(env(safe-area-inset-bottom) + 168px)',
        borderRadius: '999px',
        backgroundColor: '#1d6fb8', color: '#ffffff',
        fontSize: '12px', fontWeight: '800', letterSpacing: '1px'
      }
    });
    t.headsBtn = pill('heads', false);
    t.headsBtn.textContent = 'HEADS';
    t.tailsBtn = pill('tails', true);
    t.tailsBtn.textContent = 'TAILS';
  }

  hideTossPills() {
    const t = this.coinToss;
    t.headsBtn?.remove();
    t.tailsBtn?.remove();
    t.pills?.remove();
    t.headsBtn = t.tailsBtn = t.pills = null;
  }

  /// The call lands: heads or tails is drawn on the spot, the pills step
  /// aside, and the coin leaves the referee's hand — up over the net,
  /// tumbling, to come down where the whole court can read it.
  resolveTossCall(call) {
    const t = this.coinToss;
    if (!t || t.phase !== 0) return;
    t.call = call;
    t.result = Math.random() < 0.5 ? 'heads' : 'tails';
    this.hideTossPills();
    haptic('tick');
    playWhoosh();
    this.spawnCoin();
    t.phase = 1;
    t.t = 0;
  }

  /// The coin itself: a small gold disk over the net — the winning face
  /// painted on one cap, the other on the reverse — built here and disposed
  /// the moment play begins.
  spawnCoin() {
    const face = (label) => {
      const c = document.createElement('canvas');
      c.width = c.height = 64;
      const x = c.getContext('2d');
      x.fillStyle = '#e4b53a';
      x.beginPath();
      x.arc(32, 32, 32, 0, Math.PI * 2);
      x.fill();
      x.fillStyle = '#8a6110';
      x.font = '900 30px Menlo, Consolas, monospace';
      x.textAlign = 'center';
      x.textBaseline = 'middle';
      x.fillText(label, 32, 34);
      const tex = new THREE.CanvasTexture(c);
      tex.colorSpace = THREE.SRGBColorSpace;
      return tex;
    };
    const geo = new THREE.CylinderGeometry(0.22, 0.22, 0.045, 28);
    const mats = [
      new THREE.MeshStandardMaterial({ color: 0xa8842c, roughness: 0.35, metalness: 0.45 }),
      new THREE.MeshStandardMaterial({ map: face('H'), roughness: 0.45 }),
      new THREE.MeshStandardMaterial({ map: face('T'), roughness: 0.45 })
    ];
    const coin = new THREE.Mesh(geo, mats);
    coin.position.set(0, 1.6, 0);
    // The flight is solved like every other arc: the launch velocity that
    // sets the coin down flat on the sand exactly when the tumble ends.
    const T = 1.35;
    coin.userData.vy = (0.045 - 1.6 + 0.5 * G * T * T) / T;
    // A touch of drift toward the near court: the coin comes down just this
    // side of the net, clear of the tape.
    coin.userData.vz = 0.6;
    this.root.add(coin);
    this.coinToss.coin = coin;
  }

  updateCoinToss(dt) {
    const t = this.coinToss;
    if (!t) return;
    // The breeze and the crowd keep breathing behind the toss.
    this.updateWind(dt);
    this.updateCrowd(dt);
    if (t.phase === 1) {
      const m = t.coin;
      m.userData.vy -= G * dt;
      m.position.y += m.userData.vy * dt;
      m.position.z += m.userData.vz * dt;
      m.rotation.x -= 13 * dt;
      if (m.userData.vy < 0 && m.position.y <= 0.045) {
        // Down it comes: the coin lies flat with the winning face up, the
        // winner is read off it, and the call is announced the way the booth
        // announces everything else.
        m.position.y = 0.045;
        m.rotation.x = t.result === 'heads' ? 0 : Math.PI;
        m.rotation.z = 0;
        t.phase = 2;
        t.t = 0;
        haptic('tick');
        const winner = t.call === t.result ? t.caller
          : t.caller === 'player' ? 'cpu' : 'player';
        t.winner = winner;
        this.server = winner;
        // Doubles: the winning team serves through its own first server, and
        // the other side's rotation still opens with theirs.
        this.serverAth = this.nextServerAth(winner);
        this.setMsg(`${t.result.toUpperCase()} — ${this.serveMessage(winner)}`);
      }
    } else if (t.phase === 2) {
      t.t += dt;
      if (t.t >= 1.5) this.finishCoinToss();
    }
  }

  /// The toss is read: the coin is gathered up, the pills are gone, and the
  /// match opens with the winning side serving.
  finishCoinToss() {
    const t = this.coinToss;
    this.coinToss = null;
    if (t.coin) {
      this.root.remove(t.coin);
      t.coin.geometry.dispose();
      (Array.isArray(t.coin.material) ? t.coin.material : [t.coin.material])
        .forEach((m) => {
          if (m.map) m.map.dispose();
          m.dispose();
        });
    }
    this.hideTossPills();
    this.state = 'serve';
    this.timer = 1.2;
  }

  updateCamera(dt) {
    const cam = this.game.camera;
    const targetA = this.playerSide > 0 ? 0 : Math.PI;
    if (this.camSwing) {
      // The changeover: the camera sweeps round the sideline at a raised
      // height instead of cutting straight through the net.
      const speed = 2.2;
      const d = targetA - this.camA;
      this.camA += clamp(d, -speed * dt, speed * dt);
      if (Math.abs(targetA - this.camA) < 0.005) {
        this.camA = targetA;
        this.camSwing = false;
      }
      const lift = Math.sin((1 - Math.abs(d) / Math.PI) * Math.PI) * 1.9;
      cam.position.set(
        Math.sin(this.camA) * this.camBase.z,
        this.camBase.y + lift,
        Math.cos(this.camA) * this.camBase.z
      );
      cam.lookAt(0, 1.5, 0);
      return;
    }
    // The broadcast toggle is read every frame: flipping it swaps the view
    // on the spot, in any mode, and the rig eases across instead of cutting.
    if (broadcastCamera()) {
      this.updateBroadcastCamera(dt);
      return;
    }
    const k = Math.min(1, dt * 3);
    cam.position.x += (this.ball.mesh.position.x * 0.2 - cam.position.x) * k;
    cam.position.y += (this.camBase.y - cam.position.y) * k;
    cam.position.z += (this.playerSide * this.camBase.z - cam.position.z) * k;
    cam.lookAt(0, 1.5, -this.playerSide * 1.6);
    // A hard slap kicks the camera a touch — the impact travels through you.
    if (this.camKick > 0) {
      this.camKick = Math.max(0, this.camKick - dt * 3.5);
      if (shakeOn()) cam.position.y += Math.sin(this.camKick * 24) * this.camKick * 0.1;
      cam.lookAt(0, 1.5, -this.playerSide * 1.6);
    }
  }

  /// The broadcast pedestal for the panel's shape: high on the sideline and
  /// far enough back that the whole court fits the frame — tighter in
  /// landscape, pulled further back and higher over a tall panel.
  broadcastPose() {
    const aspect = this.viewW / this.viewH;
    if (aspect < 0.75) return { x: 15.2, y: 9.6 };
    if (aspect < 1.25) return { x: 13.4, y: 8.4 };
    return { x: 11.8, y: 7.4 };
  }

  /// The broadcast view: a high camera on the sideline that barely moves —
  /// a small drift along the touchline and a shallow tilt — while the pan
  /// follows the ball across the whole court. The slow-motion replays keep
  /// their own low sideline shot and the flyover lands on this pedestal
  /// when the toggle is on.
  updateBroadcastCamera(dt) {
    const cam = this.game.camera;
    const p = this.ball.mesh.position;
    const portrait = this.viewW / this.viewH < 0.75;
    const bp = this.broadcastPose();
    const k = Math.min(1, dt * 3.2);
    cam.position.x += (bp.x - cam.position.x) * k;
    cam.position.y += (bp.y - cam.position.y) * k;
    cam.position.z += (clamp(p.z * 0.22, -2.4, 2.4) - cam.position.z) * k;
    // The look point does the following: across the whole court after the
    // ball, biased toward the near court on a tall panel so the play fills
    // the frame the way a tight broadcast does.
    const lk = Math.min(1, dt * 5);
    this.bcLook.x += (clamp(p.x * 0.72, -3.6, 3.6) - this.bcLook.x) * lk;
    this.bcLook.y += (1.05 + p.y * 0.12 - this.bcLook.y) * lk;
    this.bcLook.z += (clamp(
      p.z * 0.52 + (portrait ? this.playerSide * 1.6 : 0), -5.6, 5.6
    ) - this.bcLook.z) * lk;
    cam.lookAt(this.bcLook.x, this.bcLook.y, this.bcLook.z);
    // A hard strike still lands: the operator's bump, a touch smaller here.
    if (this.camKick > 0) {
      this.camKick = Math.max(0, this.camKick - dt * 3.5);
      if (shakeOn()) cam.position.y += Math.sin(this.camKick * 24) * this.camKick * 0.07;
      cam.lookAt(this.bcLook.x, this.bcLook.y, this.bcLook.z);
    }
  }

  /// The meter readout: a bar beside the jump button that only shows while a
  /// charge is live, colouring from lob-green to spike-red as it fills.
  updateMeter() {
    this.setMeter(this.meterTrack, this.meterFill, this.charging, this.charge);
    if (this.meterTrack2) {
      this.setMeter(this.meterTrack2, this.meterFill2, this.charging2, this.charge2);
    }
  }

  setMeter(track, fill, charging, charge) {
    const show = charging || charge > 0.02;
    const op = show ? '1' : '0';
    track.style.opacity = op;
    fill.style.opacity = op;
    fill.style.height = `${Math.round(102 * charge)}px`;
    fill.style.backgroundColor =
      charge < LOB_CHARGE ? '#8fd06a' :
      charge < 0.75 ? '#ffd24a' : '#ff6a4d';
  }

  /// The stamina bars: one beside each side's charge meter, redrawn only
  /// when the level actually moves a hundredth — the fill stepping from green
  /// through amber to red as the tank empties.
  updateStaminaHud() {
    this.setStaminaBar(this.stamFill, this.player.stamina);
    if (this.stamFill2) {
      const w2 = this.coop ? this.partner : this.cpu;
      this.setStaminaBar(this.stamFill2, w2.stamina);
    }
  }

  setStaminaBar(fill, s) {
    const v = Math.round(s * 100) / 100;
    if (fill._stam === v) return;
    fill._stam = v;
    fill.style.height = `${Math.round(104 * v)}px`;
    fill.style.backgroundColor =
      v > 0.5 ? '#7ddb6a' : v > 0.25 ? '#ffd24a' : '#ff6a4d';
  }

  /// The launch button sits dimmed while its cooldown runs, so the move reads
  /// as spent until the legs are ready again.
  updateActionButtons() {
    const dim = (btn, cd) => { if (btn) btn.style.opacity = cd > 0 ? '0.35' : '1'; };
    const w2 = this.coop ? this.partner : this.cpu;
    dim(this.launchBtn, this.player.launchCd);
    if (this.launchBtn2) dim(this.launchBtn2, w2.launchCd);
    // The super button brightens as the meter fills and burns gold while it
    // is armed, waiting for the next touch.
    const superStyle = (btn, w) => {
      if (!btn) return;
      btn.style.opacity = w.superMeter >= 1 || w.superArmed ? '1' : '0.35';
      btn.style.backgroundColor = w.superArmed
        ? 'rgba(255, 190, 40, 0.8)'
        : 'rgba(212, 140, 24, 0.5)';
    };
    superStyle(this.superBtn, this.player);
    if (this.superBtn2) superStyle(this.superBtn2, w2);
  }

  /// Mirrors the shot maths of a charged strike: same steering, same depth
  /// nudge, so the arrow on the sand never lies about where the ball goes —
  /// and, since the breeze carries every shot sideways for the whole of its
  /// flight, the arrow reads the live wind too. Its tip is offset toward
  /// where the drift will actually put the ball down, sized by the hang time
  /// the charge implies: a lob's long float sails further than a spike's
  /// quick crossing, and on the serve a float hangs longer than a jump
  /// serve. It is read fresh every frame, so a weather shift between sets
  /// moves the bend the moment the air moves — and under the indoor roof
  /// there is no breeze at all, so the arrow stays straight on the mark.
  updateAim() {
    const show = this.charging && (this.state === 'rally' || this.state === 'toss');
    this.aimArrow.visible = show;
    this.spinHint.visible = false;
    if (!show) return;
    const a = this.player.athlete;
    const steer = 6.5 + 9 * this.charge;
    const tx = clamp(this.input.x * this.playerSide * steer, -3.6, 3.6);
    const base = this.charge < LOB_CHARGE ? 4.4 : 4.4 + 2.4 * this.charge;
    const tz = -this.playerSide * base + this.input.z * this.playerSide * 1.6;
    // The honest landing: the aim, plus the drift the breeze lays on over
    // the flight this charge implies — the same sideways push updateBall
    // applies every frame the ball is in the air, so the two agree.
    const hang = this.state === 'toss'
      ? (this.charge >= 0.5 ? 0.72 - 0.2 * this.charge : 1.6)
      : this.charge < LOB_CHARGE ? 1.9 : 0.9 - 0.24 * this.charge;
    const drift = this.wind.strength * hang;
    const lx = tx + this.wind.x * drift;
    const lz = tz + this.wind.z * drift;
    this.aimArrow.position.set(a.position.x, 0.04, a.position.z);
    this.aimArrow.rotation.y = Math.atan2(lx - a.position.x, lz - a.position.z);
    this.aimArrow.scale.set(0.9 + this.charge * 0.5, 1, 0.9 + this.charge * 1.5);
    // The curve hint rides the bent arrow: swiping the drag across the
    // flight bends the shot — a faint angled tick off the arrow's tip names
    // the side the ball will break to, and brightens with how hard it will
    // bend. The spin itself is read off the flight the drag is sending, not
    // the drifted path, because that is the flight the swipe crosses.
    const dx = tx - a.position.x;
    const dz = tz - a.position.z;
    const len = Math.hypot(dx, dz) || 1;
    const spin = this.readSideSpin(this.input, dx / len, dz / len);
    if (spin.mag > 0.001) {
      const s = spin.signed < 0 ? -1 : 1;
      const ldx = lx - a.position.x;
      const ldz = lz - a.position.z;
      const llen = Math.hypot(ldx, ldz) || 1;
      this.spinHint.visible = true;
      this.spinHint.position.set(
        a.position.x + (ldx / llen) * 1.5 - (ldz / llen) * s * 0.62,
        0.04,
        a.position.z + (ldz / llen) * 1.5 + (ldx / llen) * s * 0.62
      );
      this.spinHint.rotation.y = this.aimArrow.rotation.y - 0.6 * s;
      this.spinHint.material.opacity = 0.14 + 0.3 * spin.mag;
    }
  }

  /// The placement heat grid: one bucket for a human striker's shot that
  /// died in bounds on the far court — six across and six deep over that
  /// half, read the way the camera sees it (left to right across, net to
  /// baseline going away), so the career view is always the same way up
  /// whatever the ends are doing.
  recordHeatShot(x, z) {
    const depth = -z * this.playerSide; // 0 at the net, 8 at the baseline
    const sx = x * this.playerSide;     // screen-left to screen-right
    const col = clamp(
      Math.floor((sx + HALF_W) / (HALF_W * 2 / HEAT_COLS)), 0, HEAT_COLS - 1
    );
    const row = clamp(
      Math.floor(depth / (HALF_L / HEAT_ROWS)), 0, HEAT_ROWS - 1
    );
    this.heat[row * HEAT_COLS + col]++;
  }

  /// The far side's own placement grid: one bucket for a shot of theirs
  /// that died in bounds on the near court — bucketed the same way and read
  /// as the camera sees it, so both grids draw on the one overhead court on
  /// the career screen, net along the bottom, left to right across.
  recordRivalHeatShot(x, z) {
    const depth = z * this.playerSide;  // 0 at the net, 8 at the baseline
    const sx = x * this.playerSide;     // screen-left to screen-right
    const col = clamp(
      Math.floor((sx + HALF_W) / (HALF_W * 2 / HEAT_COLS)), 0, HEAT_COLS - 1
    );
    const row = clamp(
      Math.floor(depth / (HALF_L / HEAT_ROWS)), 0, HEAT_ROWS - 1
    );
    this.heatRival[row * HEAT_COLS + col]++;
  }

  // ---------------------------------------------------------------- target

  /// The target ring: a gold band and a soft additive glow laid flat on the
  /// sand of the far court. Its geometry is a unit ring — the radius lives in
  /// the group's scale, so shrinking a hit is just a smaller scalar.
  buildTarget() {
    const g = new THREE.Group();
    g.renderOrder = 2;
    this.targetRing = new THREE.Mesh(
      new THREE.RingGeometry(0.86, 1, 48),
      new THREE.MeshBasicMaterial({
        color: 0xffd24a, transparent: true, opacity: 0.85,
        side: THREE.DoubleSide, depthWrite: false
      })
    );
    this.targetRing.rotation.x = -Math.PI / 2;
    this.targetGlow = new THREE.Mesh(
      new THREE.RingGeometry(0.68, 1.28, 48),
      new THREE.MeshBasicMaterial({
        color: 0xffd24a, transparent: true, opacity: 0.22,
        side: THREE.DoubleSide, depthWrite: false,
        blending: THREE.AdditiveBlending, fog: false
      })
    );
    this.targetGlow.rotation.x = -Math.PI / 2;
    g.add(this.targetRing, this.targetGlow);
    g.position.y = 0.021;
    this.root.add(g);
    this.targetGroup = g;
  }

  /// A fresh ring for the next attempt: anywhere on the far court, clear of
  /// the net and the sidelines — except in the steering drill, where it waits
  /// out in a corner, because steering the shot wide is the whole point.
  placeTarget() {
    const steer = this.ladder && DRILLS[this.drillIdx].id === 'steer';
    this.targetGroup.position.set(
      steer ? (Math.random() < 0.5 ? -1 : 1) * (1.9 + Math.random() * 1.3)
        : (Math.random() * 2 - 1) * 3.2,
      0.021,
      -(1.4 + Math.random() * (HALF_L - 2.3))
    );
    this.target.pop = 0.6;
  }

  /// The ball dying on the far court off a player touch: one attempt, and a
  /// hit when it comes down inside the ring — which then shrinks for the
  /// next one.
  targetHit(x, z) {
    // In the ladder the dying ball scores the drill instead of the free
    // challenge.
    if (this.ladder) {
      this.drillAttempt(x, z);
      return;
    }
    const t = this.target;
    t.attempts++;
    const dx = x - this.targetGroup.position.x;
    const dz = z - this.targetGroup.position.z;
    if (dx * dx + dz * dz <= t.r * t.r) {
      t.hits++;
      t.r = Math.max(RING_R_MIN, t.r * RING_SHRINK);
      t.pop = 1;
      haptic('point');
      playCheer(false);
      this.crowdWaveStart(0.55);
      this.spawnFlash(this.tmp.set(x, 0.3, z));
    }
    this.refreshTarget();
  }

  /// The pill under the score: the free challenge's hits tally — or, while
  /// the ladder runs, the drill pill, showing the current drill and its
  /// progress. The passing drill reads the live rally; the ring drills read
  /// their hit count out of the shot budget.
  refreshTarget() {
    let text;
    if (this.ladder) {
      const d = DRILLS[this.drillIdx];
      text = d.touches
        ? `${d.name} · TOUCH ${Math.min(this.rallyLen, d.touches)}/${d.touches}`
        : `${d.name} ${this.drillHits}/${this.drillShots}`;
    } else {
      text = `HITS ${this.target.hits}/${this.target.attempts}`;
    }
    if (text !== this.targetPillText) {
      this.targetPillText = text;
      this.targetText.textContent = text;
    }
  }

  /// The ring breathes while it waits, and pops when a shot lands in it.
  updateTarget(dt) {
    const t = this.target;
    if (!t) return;
    t.pop = Math.max(0, t.pop - dt * 2.5);
    const pulse = 1 + 0.045 * Math.sin(this.clock * 3.2) + 0.35 * t.pop;
    this.targetGroup.scale.setScalar(t.r * pulse);
    this.targetGlow.material.opacity =
      clamp(0.22 + 0.1 * Math.sin(this.clock * 3.2) + 0.5 * t.pop, 0, 1);
    this.targetRing.material.opacity = 0.85 - 0.3 * t.pop;
    // The drill pill follows the ladder live: the passing drill's touch
    // count climbs with the rally it is inside.
    this.refreshTarget();
  }

  // ---------------------------------------------------------------- crowd

  /// The stands: low terraces behind both baselines and along both sidelines,
  /// each row a step up and a row further back, filled with simple instanced
  /// spectators — one tapered body and one head per seat. Three instanced
  /// meshes carry the whole crowd: the terrace steps, the bodies and the
  /// heads, each fan tinted from the theme's own crowd palette.
  buildCrowd() {
    const g = new THREE.Group();
    this.crowdGroup = g;
    const rows = [];
    const steps = [];
    for (let r = 0; r < 4; r++) {
      const top = 0.36 * (r + 1);
      const off = 9.9 + r * 1.05;
      // Behind both baselines: a long stand facing the court.
      for (const s of [1, -1]) {
        steps.push({ x: 0, y: top / 2, z: s * off, sx: 17, sy: top, sz: 1.05 });
        for (let x = -7.6; x <= 7.61; x += 0.9) {
          rows.push(this.crowdSeat(
            x + (Math.random() - 0.5) * 0.22, top,
            s * off + (Math.random() - 0.5) * 0.3,
            s > 0 ? Math.PI : 0, 1, 0
          ));
        }
      }
      // Along both sidelines: a deep stand facing across the court.
      for (const s of [1, -1]) {
        steps.push({ x: s * off, y: top / 2, z: 0, sx: 1.05, sy: top, sz: 18.4 });
        for (let z = -7.9; z <= 7.91; z += 0.9) {
          rows.push(this.crowdSeat(
            s * off + (Math.random() - 0.5) * 0.3, top,
            z + (Math.random() - 0.5) * 0.22,
            s > 0 ? -Math.PI / 2 : Math.PI / 2, 0, 1
          ));
        }
      }
    }

    const stepMesh = new THREE.InstancedMesh(
      new THREE.BoxGeometry(1, 1, 1),
      new THREE.MeshStandardMaterial({ color: 0x8d8271, roughness: 0.95 }),
      steps.length
    );
    // Instance matrices place the steps far from the unit-box geometry the
    // cull test would otherwise read.
    stepMesh.frustumCulled = false;
    const d = new THREE.Object3D();
    steps.forEach((s, i) => {
      d.position.set(s.x, s.y, s.z);
      d.scale.set(s.sx, s.sy, s.sz);
      d.updateMatrix();
      stepMesh.setMatrixAt(i, d.matrix);
    });
    g.add(stepMesh);

    const n = rows.length;
    this.crowdBody = new THREE.InstancedMesh(
      new THREE.CylinderGeometry(0.13, 0.165, 0.44, 7),
      new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.95 }),
      n
    );
    this.crowdHead = new THREE.InstancedMesh(
      new THREE.SphereGeometry(0.105, 8, 6),
      new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.9 }),
      n
    );
    this.crowdBody.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    this.crowdHead.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    this.crowdBody.frustumCulled = false;
    this.crowdHead.frustumCulled = false;
    const kit = CROWD_KIT[this.theme.id] || CROWD_KIT.midday;
    const col = new THREE.Color();
    for (let i = 0; i < n; i++) {
      col.setHex(Math.random() < 0.82
        ? kit[(Math.random() * kit.length) | 0]
        : 0x3a4750);
      this.crowdBody.setColorAt(i, col);
      col.setHex(Math.random() < 0.72
        ? CROWD_SKIN[(Math.random() * CROWD_SKIN.length) | 0]
        : CROWD_CAP[(Math.random() * CROWD_CAP.length) | 0]);
      this.crowdHead.setColorAt(i, col);
    }
    if (this.crowdBody.instanceColor) this.crowdBody.instanceColor.needsUpdate = true;
    if (this.crowdHead.instanceColor) this.crowdHead.instanceColor.needsUpdate = true;
    g.add(this.crowdBody, this.crowdHead);
    this.root.add(g);
    this.crowdSeats = rows;
    // Under the floodlights the terraces light up: night and the indoor
    // arena give a share of the fans a glowing phone to hold up.
    if (this.theme.id === 'night' || this.theme.indoor) this.buildPhoneGlow();
  }

  /// One seat: where the fan stands, which way they face, the direction a
  /// sway travels along their row, their angle round the arena for the wave,
  /// and their own bobbing clock.
  crowdSeat(x, y, z, ry, tx, tz) {
    return {
      x, y, z, ry, tx, tz,
      ang: Math.atan2(x, z),
      ph: Math.random() * Math.PI * 2,
      sp: 1.6 + Math.random() * 1.4
    };
  }

  /// The crowd made visible: every fan bobs on their own clock, the whole
  /// terrace sways and lifts with the rally exactly as the murmur does, and
  /// each roar or landed point sends a ring of jumping fans sweeping round
  /// the arena — the wave you can see matching the eruption you hear.
  updateCrowd(dt) {
    const c = this.crowdSeats;
    if (!c) return;
    // The terrace re-poses at 30Hz: every second call banks its dt and hands
    // back — the bob, the sway and the wave stay in time while the per-fan
    // matrix rebuild and the instance uploads run at half the frame rate.
    // The bob is a quarter-hertz sway, so nothing in it can tell.
    this.crowdBudget = (this.crowdBudget || 0) + dt;
    this.crowdTick = ((this.crowdTick || 0) + 1) % 2;
    if (!this.crowdTick) return;
    dt = this.crowdBudget;
    this.crowdBudget = 0;
    this.crowdT += dt;
    this.crowdLift += (this.crowdLiftTarget - this.crowdLift) * Math.min(1, dt * 1.6);
    if (this.crowdWave > 0) {
      this.crowdWave = Math.max(0, this.crowdWave - dt / 1.7);
      this.crowdWaveA += dt * 2.6;
    }
    const t = this.crowdT;
    const lift = this.crowdLift;
    const wave = this.crowdWave;
    const waveA = this.crowdWaveA;
    const d = this.dummy;
    for (let i = 0; i < c.length; i++) {
      const s = c[i];
      const bob = Math.sin(t * s.sp + s.ph) * (0.02 + 0.05 * lift);
      const sway = Math.sin(t * s.sp * 0.6 + s.ph * 1.7) * 0.055 * lift;
      let jump = 0;
      if (wave > 0) {
        const da = Math.abs((((s.ang - waveA) % TAU) + TAU + Math.PI) % TAU - Math.PI);
        jump = Math.exp(-da * da * 10) * wave;
      }
      // A banner holder: while the milestone banner is up in their stand,
      // these fans stay on their feet holding it, lifting with its unfurl.
      if (this.bannerHold && this.bannerHold[i]) {
        jump = Math.max(jump,
          this.bannerHoldLevel * (0.5 + 0.12 * Math.sin(t * s.sp * 1.4 + s.ph)));
      }
      // Kept on the seat for the phone holders: the light sways and lifts
      // with its fan, not on a rhythm of its own.
      s._bob = bob;
      s._sway = sway;
      s._jump = jump;
      d.position.set(
        s.x + s.tx * sway,
        s.y + 0.22 + bob + jump * 0.42,
        s.z + s.tz * sway
      );
      d.rotation.set(0, s.ry, sway * 0.6);
      d.scale.set(1, 1 + jump * 0.3, 1);
      d.updateMatrix();
      this.crowdBody.setMatrixAt(i, d.matrix);
      d.position.y = s.y + 0.53 + bob + jump * 0.55;
      d.scale.set(1, 1, 1);
      d.updateMatrix();
      this.crowdHead.setMatrixAt(i, d.matrix);
    }
    this.crowdBody.instanceMatrix.needsUpdate = true;
    this.crowdHead.instanceMatrix.needsUpdate = true;
    this.updatePhoneGlow();
  }

  /// The phone glow: one instanced mesh of small emissive quads — a phone
  /// screen held up in the dark — one draw call for every light in the
  /// stands. A share of the fans on the night and indoor courts hold one;
  /// the daylight courts keep their plain crowd.
  buildPhoneGlow() {
    const holders = [];
    for (let i = 0; i < this.crowdSeats.length; i++) {
      // Roughly one fan in five, spread by chance through the rows.
      if (Math.random() < 0.2) {
        holders.push({
          seat: i,
          ph: Math.random() * Math.PI * 2,
          sp: 2.2 + Math.random() * 2.6
        });
      }
    }
    this.phoneGlow = new THREE.InstancedMesh(
      new THREE.PlaneGeometry(0.085, 0.15),
      new THREE.MeshBasicMaterial({
        color: 0xffffff,
        transparent: true,
        opacity: 0.9,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
        side: THREE.DoubleSide,
        fog: false
      }),
      holders.length
    );
    this.phoneGlow.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    this.phoneGlow.frustumCulled = false;
    // Indoors the lights ride above the polished court's draw order, so the
    // see-through surface cannot dim them.
    this.phoneGlow.renderOrder = this.theme.indoor ? 3 : 2;
    const col = new THREE.Color();
    for (let i = 0; i < holders.length; i++) {
      col.setRGB(0.62, 0.78, 1.0).multiplyScalar(0.3);
      this.phoneGlow.setColorAt(i, col);
    }
    this.crowdGroup.add(this.phoneGlow);
    this.phoneHolders = holders;
  }

  /// The lights made visible: every phone flickers on its own clock, glows
  /// brighter as the crowd lifts with the rally and flashes as the wave
  /// sweeps past its stand — settling low again while the serve is prepared.
  /// Each light also sways and bobs with the fan holding it.
  updatePhoneGlow() {
    if (!this.phoneHolders) return;
    const t = this.crowdT;
    const lift = this.crowdLift;
    const wave = this.crowdWave;
    const waveA = this.crowdWaveA;
    const base = 0.28 + 0.6 * lift;
    const col = this.phoneCol || (this.phoneCol = new THREE.Color());
    const d = this.dummy;
    for (let i = 0; i < this.phoneHolders.length; i++) {
      const h = this.phoneHolders[i];
      const s = this.crowdSeats[h.seat];
      // The flicker: a fast, irregular shimmer, never the same twice.
      const flick = 0.72 + 0.28 * Math.sin(t * h.sp + h.ph);
      // The wave's flash: the light surges as the eruption passes its stand.
      const da = wave > 0
        ? Math.abs((((s.ang - waveA) % TAU) + TAU + Math.PI) % TAU - Math.PI)
        : 9;
      const bright = base * flick + wave * Math.exp(-da * da * 10) * 0.9;
      col.setRGB(0.62 * bright, 0.78 * bright, 1.0 * bright);
      this.phoneGlow.setColorAt(i, col);
      // Held a touch above the head, tilted back toward the holder's face,
      // swaying and lifting with them.
      d.position.set(
        s.x + s.tx * s._sway + Math.sin(s.ry) * 0.17,
        s.y + 0.88 + s._bob + s._jump * 0.55,
        s.z + s.tz * s._sway + Math.cos(s.ry) * 0.17
      );
      d.rotation.set(-0.55, s.ry, s._sway * 0.6);
      d.scale.set(1, 1, 1);
      d.updateMatrix();
      this.phoneGlow.setMatrixAt(i, d.matrix);
    }
    this.phoneGlow.instanceMatrix.needsUpdate = true;
    this.phoneGlow.instanceColor.needsUpdate = true;
  }

  /// A roar, heard and seen as one event: the audio eruption plays and a
  /// fresh wave of jumping fans starts behind the far baseline and sweeps
  /// round the terraces.
  crowdRoar(power) {
    crowdErupt(power);
    this.crowdWaveStart(clamp(power, 0, 1));
  }

  /// The visual half on its own, for moments that already play their own
  /// cheer — a landed point, a set taken, a target hit: the wave fires
  /// without stacking another eruption on the sound bed.
  crowdWaveStart(power) {
    this.crowdWave = Math.max(this.crowdWave, power);
    this.crowdWaveA = this.playerSide > 0 ? Math.PI : 0;
  }

  /// The milestone banner: a gold cloth hung on a rail above the far stand,
  /// unfurling downward with the new title's or badge's name painted on it —
  /// held up by a handful of the fans below while the wave sweeps, then
  /// rolled back up and gone. Driven off the same celebration moments the
  /// toasts read, and never up during a replay or the flyover.
  buildBanner() {
    const g = new THREE.Group();
    g.visible = false;
    this.root.add(g);
    this.bannerGroup = g;
    // The cloth hangs from its top edge: the geometry is shifted so scaling
    // its height unfurls it downward from the rail instead of from centre.
    const geo = new THREE.PlaneGeometry(7, 0.85);
    geo.translate(0, -0.425, 0);
    this.bannerMat = new THREE.MeshBasicMaterial();
    this.bannerMesh = new THREE.Mesh(geo, this.bannerMat);
    g.add(this.bannerMesh);
  }

  /// A milestone has landed: the cloth is painted with the name, hung on the
  /// far stand's rail, and a handful of fans in the rows beneath it are
  /// picked to hold it up — standing taller while it flies. The wave starts
  /// with it.
  raiseBanner(name) {
    if (!this.bannerGroup || this.flyT > 0 || this.state === 'replay') return;
    // Paint the name: gold cloth, dark letters, hemmed at every edge, the
    // text stepping down a size until it fits the cloth.
    const c = document.createElement('canvas');
    c.width = 512;
    c.height = 96;
    const x = c.getContext('2d');
    x.fillStyle = '#e4b222';
    x.fillRect(0, 0, 512, 96);
    x.fillStyle = 'rgba(35, 21, 3, 0.85)';
    x.fillRect(0, 0, 512, 8);
    x.fillRect(0, 88, 512, 8);
    x.fillRect(0, 0, 8, 96);
    x.fillRect(504, 0, 8, 96);
    x.fillStyle = '#231503';
    x.textAlign = 'center';
    x.textBaseline = 'middle';
    let size = 54;
    x.font = `800 ${size}px -apple-system, system-ui, sans-serif`;
    while (size > 26 && x.measureText(name).width > 452) {
      size -= 4;
      x.font = `800 ${size}px -apple-system, system-ui, sans-serif`;
    }
    x.fillText(name, 256, 52);
    if (this.bannerMat.map) this.bannerMat.map.dispose();
    const tex = new THREE.CanvasTexture(c);
    tex.colorSpace = THREE.SRGBColorSpace;
    this.bannerMat.map = tex;
    this.bannerMat.needsUpdate = true;
    // The far stand faces the camera whichever end the match is at.
    const far = -this.playerSide;
    this.bannerGroup.position.set(0, 2.72, far * 9.32);
    this.bannerGroup.rotation.y = far > 0 ? Math.PI : 0;
    this.bannerGroup.rotation.z = 0;
    this.bannerGroup.visible = true;
    this.bannerT = 0;
    // The holders: fans in the far stand's rows under the cloth, a few per
    // row, picked fresh every time so different faces hold each banner.
    this.bannerHold = new Uint8Array(this.crowdSeats.length);
    let held = 0;
    for (let i = 0; i < this.crowdSeats.length && held < 16; i++) {
      const s = this.crowdSeats[i];
      if (Math.sign(s.z) === far && Math.abs(s.z) > 9.3 &&
          Math.abs(s.x) < 3.6 && Math.random() < 0.22) {
        this.bannerHold[i] = 1;
        held++;
      }
    }
    this.bannerHoldLevel = 0;
    // The celebration in the stands: the wave sweeps as the cloth unfurls.
    this.crowdWaveStart(0.9);
  }

  /// The cloth's life: it unfurls downward over half a second, holds with a
  /// gentle sway while the wave sweeps past, then rolls back up and the fans
  /// sit down again. The holders' lift follows the same envelope.
  updateBanner(dt) {
    if (!this.bannerGroup || this.bannerT < 0) return;
    this.bannerT += dt;
    const UP = 0.45;
    const HOLD = 3.4;
    const DOWN = 0.4;
    const t = this.bannerT;
    let open = 1;
    if (t < UP) {
      const e = t / UP;
      open = 1 - (1 - e) * (1 - e);
    } else if (t < UP + HOLD) {
      this.bannerGroup.rotation.z = Math.sin(t * 2.2) * 0.014;
    } else if (t < UP + HOLD + DOWN) {
      this.bannerGroup.rotation.z = 0;
      open = Math.max(0, 1 - (t - UP - HOLD) / DOWN);
    } else {
      this.bannerT = -1;
      this.bannerGroup.visible = false;
      this.bannerHold = null;
      this.bannerHoldLevel = 0;
      return;
    }
    this.bannerMesh.scale.y = Math.max(0.001, open);
    this.bannerHoldLevel = open;
  }

  // ---------------------------------------------------------- match point

  /// The match-point spotlight: one real spotlight hanging in the terrace,
  /// a visible additive beam cone and the bright pool it lays on the sand.
  /// Built once and left dark — it lives only while the match stands on
  /// match point.
  buildSpotlight() {
    const g = new THREE.Group();
    g.visible = false;
    this.root.add(g);
    this.spotGroup = g;
    this.spotLight = new THREE.SpotLight(0xfff0d0, 0, 45, 0.32, 0.5, 1);
    this.spotTarget = new THREE.Object3D();
    this.spotLight.target = this.spotTarget;
    g.add(this.spotLight, this.spotTarget);
    // The visible beam: a tapered cone stretching from the lamp down to the
    // court — the wide end sits at the sand, the lamp at the narrow one.
    this.spotBeam = new THREE.Mesh(
      new THREE.CylinderGeometry(1, 0.12, 1, 14, 1, true),
      new THREE.MeshBasicMaterial({
        color: 0xfff3cf,
        transparent: true,
        opacity: 0,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
        side: THREE.DoubleSide,
        fog: false
      })
    );
    this.spotBeam.frustumCulled = false;
    this.spotBeam.renderOrder = this.theme.indoor ? 3 : 2;
    g.add(this.spotBeam);
    // The pool of light on the sand under whoever the beam is holding.
    this.spotPool = new THREE.Mesh(
      new THREE.CircleGeometry(1, 28),
      new THREE.MeshBasicMaterial({
        color: 0xfff3cf,
        transparent: true,
        opacity: 0,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
        fog: false
      })
    );
    this.spotPool.rotation.x = -Math.PI / 2;
    this.spotPool.renderOrder = this.theme.indoor ? 3 : 2;
    g.add(this.spotPool);
    this.spotI = 0;
    this.spotT = 0;
    this.spotLock = false;
    this.spotAim = new THREE.Vector3(0, 0, -this.playerSide * 6);
    this.spotApex = new THREE.Vector3(0, 4.8, -this.playerSide * 10.4);
  }

  /// The spotlight's life: while the match stands on match point and live
  /// play is on the court, the beam sweeps the terraces and then locks onto
  /// the serving athlete, tracking them through the rally; the moment a
  /// point lands it eases out. It never runs during a replay or the
  /// flyover — those own the frame before this is ever reached.
  updateSpotlight(dt) {
    const live = this.state === 'serve' || this.state === 'serveReady' ||
      this.state === 'rally' || this.state === 'toss';
    const mp = live && !this.practice && !this.blitz && this.isMatchPoint();
    // In on the serve while match point stands, out the moment it lands.
    this.spotI += ((mp ? 1 : 0) - this.spotI) * Math.min(1, dt * (mp ? 2.2 : 4));
    const g = this.spotGroup;
    if (this.spotI <= 0.003) {
      if (g.visible) g.visible = false;
      this.spotT = 0;
      this.spotLock = false;
      return;
    }
    g.visible = true;
    if (mp) this.spotT += dt;
    if (!this.spotLock && this.spotT < SPOT_SWEEP) {
      // The sweep: the lamp pans along the terrace while its beam swings
      // wide across the court, hunting for the server.
      this.spotApex.set(
        Math.sin(this.spotT * 2.1) * 5.2, 4.8,
        -this.playerSide * (10.2 + Math.sin(this.spotT * 3.3) * 0.8)
      );
      this.spotAim.set(
        Math.sin(this.spotT * 1.7 + 1.1) * 4.6, 0,
        -this.playerSide * mix(2, 7, Math.sin(this.spotT * 0.9) * 0.5 + 0.5)
      );
    } else {
      // The lock: the beam glides onto the serving athlete and tracks them
      // for the rally — and its landing is felt, a kick gated like every
      // camera shake.
      if (!this.spotLock) {
        this.spotLock = true;
        this.camKick = Math.max(this.camKick, shakeOn() ? 0.3 : 0);
      }
      const ath = (this.serverAth || this.player).athlete;
      this.spotApex.lerp(this.tmp.set(
        ath.position.x * 0.6, 4.8,
        ath.position.z + (this.playerSide > 0 ? 6.2 : -6.2)
      ), Math.min(1, dt * 2));
      this.spotAim.lerp(this.tmp2.set(ath.position.x, 0.4, ath.position.z),
        Math.min(1, dt * 5));
    }
    // The rig itself: the light hangs at the apex and aims at the pool.
    const i = this.spotI;
    this.spotLight.position.copy(this.spotApex);
    this.spotLight.intensity = i * 60;
    this.spotTarget.position.copy(this.spotAim);
    // The beam cone stretches apex to aim, wide end on the sand.
    this.tmp.copy(this.spotAim).sub(this.spotApex);
    const len = this.tmp.length();
    this.spotBeam.position.copy(this.spotApex).addScaledVector(this.tmp, 0.5);
    this.spotBeam.quaternion.setFromUnitVectors(this.tmpUp, this.tmp.normalize());
    this.spotBeam.scale.set(1, len, 1);
    this.spotBeam.material.opacity = 0.16 * i;
    // The pool rides the aim on the sand, breathing gently with the beam.
    this.spotPool.position.set(this.spotAim.x, 0.03, this.spotAim.z);
    this.spotPool.scale.setScalar(1 + 0.06 * Math.sin(this.clock * 6));
    this.spotPool.material.opacity = 0.3 * i;
  }

  // ---------------------------------------------------------------- drill

  /// The ball machine: a chunky feeder on wheels at the far baseline — a
  /// dark box body, a red hopper on top and a barrel tipped up toward the
  /// player's court. It only exists in practice and only shows itself while
  /// the drill runs, with the CPU athlete standing beside it working the
  /// feeds.
  buildMachine() {
    const g = new THREE.Group();
    const bodyMat = new THREE.MeshStandardMaterial({
      color: 0x2b3440, roughness: 0.6, metalness: 0.3
    });
    const accentMat = new THREE.MeshStandardMaterial({
      color: 0xd8453f, roughness: 0.55
    });
    const wheelMat = new THREE.MeshStandardMaterial({
      color: 0x11161c, roughness: 0.9
    });
    const body = new THREE.Mesh(new THREE.BoxGeometry(0.72, 0.5, 0.95), bodyMat);
    body.position.y = 0.55;
    body.castShadow = true;
    const hopper = new THREE.Mesh(new THREE.BoxGeometry(0.6, 0.34, 0.5), accentMat);
    hopper.position.set(0, 0.92, -0.12);
    hopper.rotation.x = -0.35;
    hopper.castShadow = true;
    const barrel = new THREE.Mesh(
      new THREE.CylinderGeometry(0.13, 0.16, 0.72, 12),
      bodyMat
    );
    barrel.rotation.x = Math.PI / 2 - 0.5;
    barrel.position.set(0, 0.78, 0.55);
    barrel.castShadow = true;
    for (const [x, z] of [[-0.36, 0.3], [0.36, 0.3], [-0.36, -0.3], [0.36, -0.3]]) {
      const w = new THREE.Mesh(new THREE.CylinderGeometry(0.14, 0.14, 0.08, 12), wheelMat);
      w.rotation.z = Math.PI / 2;
      w.position.set(x, 0.14, z);
      g.add(w);
    }
    g.add(body, hopper, barrel);
    g.position.set(0, 0, -this.playerSide * 8.7);
    g.rotation.y = this.playerSide > 0 ? 0 : Math.PI;
    g.visible = false;
    this.root.add(g);
    this.machineGroup = g;
    // Where the ball leaves the barrel — the feed launches from here.
    this.machineBarrel = new THREE.Vector3(0, 0.98, -this.playerSide * 7.8);
    this.machineRecoil = 0;
  }

  /// A small mechanical recoil on every feed, easing back between balls.
  updateMachine(dt) {
    if (!this.machineGroup || !this.machineGroup.visible) return;
    if (this.machineRecoil > 0) {
      this.machineRecoil = Math.max(0, this.machineRecoil - dt * 3);
      this.machineGroup.position.z =
        -this.playerSide * (8.7 - 0.14 * this.machineRecoil);
    }
  }

  /// The drill switch: the machine takes over the far end — the CPU athlete
  /// steps aside to stand beside it, working the feeds, and the first ball
  /// comes after a beat. Toggled off, he takes his end back and the normal
  /// practice serve flow resumes. Either way the live streak is banked
  /// first: it was kept alive this long.
  toggleDrill() {
    // The ladder and the machine never run together: starting the machine
    // stands the ladder down first, quietly back to the free rally.
    if (this.ladder) this.ladderOff();
    if (this.rallyLen > this.sessionStreak) this.sessionStreak = this.rallyLen;
    recordStreak(this.rallyLen);
    this.rallyLen = 0;
    this.drill = !this.drill;
    this.machineGroup.visible = this.drill;
    // The athlete is never hidden: while the machine feeds he stands beside
    // it like the ball kid working it, and when it stops he walks back to
    // his end. Wherever the rally left him — mid-dive, mid-swing — he takes
    // the new spot standing, pose settled and ready.
    const c = this.cpu;
    c.athlete.visible = true;
    if (this.drill) c.athlete.position.set(2.05, 0, -this.playerSide * 8.2);
    else c.athlete.position.copy(c.home);
    c.vy = 0;
    c.runMag = 0;
    c.moveMag = 0;
    c.dir.x = 0;
    c.dir.z = 0;
    c.dive = null;
    c.getUp = 0;
    c.launched = false;
    resetAthlete(c.athlete);
    setDiveLean(c.athlete, 0);
    this.paceBtn.style.display = this.drill ? 'block' : 'none';
    this.drillBtn.style.backgroundColor = this.drill
      ? 'rgba(29, 111, 184, 0.75)'
      : 'rgba(20, 40, 60, 0.5)';
    this.state = 'point';
    this.setMsg(this.drill
      ? 'BALL MACHINE ON — PASS EVERYTHING BACK'
      : 'BALL MACHINE OFF — BACK TO THE RALLY');
    if (this.drill) {
      this.timer = 1.0;
      this.nextServer = 'machine';
    } else {
      this.timer = 1.1;
      this.nextServer = this.practiceServer;
    }
    haptic('tick');
  }

  /// Slow, medium, fast: the pace pill cycles the feeding rhythm live — the
  /// gap between balls and the height of their arcs both step with it.
  cyclePace() {
    const order = ['slow', 'medium', 'fast'];
    this.pace = order[(order.indexOf(this.pace) + 1) % order.length];
    this.paceBtn.textContent = this.pace.toUpperCase();
    haptic('tick');
  }

  /// The machine feeds: from the barrel it lobs the next ball across at the
  /// chosen pace — a steady arc onto the player's side, varied side to side
  /// so every pass is a fresh read. The feed itself is not a touch: the
  /// rally counter ticks when the player plays the ball, and the streak
  /// carries across feeds until a ball gets past them.
  machineFeed() {
    const pace = DRILL_PACE[this.pace];
    const b = this.ball;
    b.landed = false;
    b.lastTouch = 'machine';
    b.sinceTouch = 9;
    b.contactPause = 0;
    b.mesh.position.copy(this.machineBarrel);
    const side = this.playerSide;
    const tx = (Math.random() * 2 - 1) * 2.6;
    const tz = side * (2.0 + Math.random() * 4.2);
    const T = pace.T * (0.94 + Math.random() * 0.12);
    b.vel.set(
      (tx - b.mesh.position.x) / T,
      (-b.mesh.position.y + 0.5 * G * T * T) / T,
      (tz - b.mesh.position.z) / T
    );
    b.sideSign = -side;
    b.squashDir.copy(b.vel).normalize();
    b.pop = 0.6;
    this.tmp2.copy(b.vel).setY(0);
    if (this.tmp2.lengthSq() > 0.001) this.tmp2.normalize();
    b.spinAxis.copy(this.tmpUp).cross(this.tmp2);
    b.spinRate = 4;
    b.wasSpike = false;
    this.resetBallSpin();
    this.touches = { player: 0, cpu: 0 };
    this.machineRecoil = 1;
    this.state = 'rally';
    this.setMsg('');
    playBump(0.5);
    haptic('tick');
  }

  // ---------------------------------------------------------------- drills

  /// The drill ladder switch. On, it starts — or resumes where it left off —
  /// at its current drill, the machine standing down first if it was running.
  /// Off, the free rally resumes with its own shrinking-ring challenge,
  /// counters reset for a fresh run.
  toggleLadder() {
    if (this.ladder) {
      this.ladderOff();
      this.setMsg('DRILLS OFF — FREE RALLY');
      haptic('tick');
      return;
    }
    if (this.drill) this.toggleDrill();
    this.ladder = true;
    this.target.r = RING_R0;
    this.ladderBtn.style.backgroundColor = 'rgba(29, 111, 184, 0.75)';
    const d = DRILLS[this.drillIdx];
    this.targetGroup.visible = !d.touches;
    if (!d.touches) this.placeTarget();
    this.setMsg(
      `DRILLS — ${this.drillIdx + 1} OF ${DRILLS.length}: ${d.name} — ${d.goal}`
    );
    haptic('tick');
  }

  /// The ladder stands down: the free rally resumes, the ring comes back at
  /// its opening size, and the free challenge's counters start over.
  ladderOff() {
    this.ladder = false;
    this.drillBanner = null;
    this.ladderBtn.style.backgroundColor = 'rgba(20, 40, 60, 0.5)';
    this.targetGroup.visible = true;
    this.target.hits = 0;
    this.target.attempts = 0;
    this.target.r = RING_R0;
    this.refreshTarget();
  }

  /// A ladder attempt: the ball died on the far court off a player touch.
  /// Only the shot the drill asks for counts — a stray touch wastes nothing —
  /// and a hit is a landing inside the still ring.
  drillAttempt(x, z) {
    const d = DRILLS[this.drillIdx];
    if (d.touches) return; // the passing drill is judged on the rally
    if (this.lastShot !== d.accepts) return;
    this.drillShots++;
    const dx = x - this.targetGroup.position.x;
    const dz = z - this.targetGroup.position.z;
    if (dx * dx + dz * dz <= this.target.r * this.target.r) {
      this.drillHits++;
      this.target.pop = 1;
      haptic('point');
      playCheer(false);
      this.crowdWaveStart(0.55);
      this.spawnFlash(this.tmp.set(x, 0.3, z));
    }
    this.checkDrill(d);
  }

  /// The pass mark and the budget: three hits inside five shots passes; five
  /// shots spent short of the mark and the drill simply starts over.
  checkDrill(d) {
    if (this.drillHits >= d.need) {
      this.passDrill();
      return;
    }
    if (this.drillShots >= d.attempts) {
      this.drillHits = 0;
      this.drillShots = 0;
      this.placeTarget();
      this.drillBanner = { text: `NOT QUITE — ${d.goal}`, t: 2.4 };
    }
  }

  /// The passing drill's check: the touch itself is the progress, and a
  /// rally that reaches the mark passes on the spot, mid-rally.
  drillTouch() {
    const d = DRILLS[this.drillIdx];
    if (d.touches && this.rallyLen >= d.touches) this.passDrill();
  }

  /// A drill passed: the star is banked on the career record — a first-time
  /// pass is a career total, a replay just plays — the sting fires, the crowd
  /// waves, and the ladder rolls into the next drill under its banner. The
  /// last drill hands practice back to the free rally.
  passDrill() {
    const d = DRILLS[this.drillIdx];
    recordDrillStar(d.id);
    playBadgeSting();
    haptic('badge');
    this.crowdWaveStart(0.8);
    this.drillHits = 0;
    this.drillShots = 0;
    this.drillIdx++;
    if (this.drillIdx >= DRILLS.length) {
      this.ladderOff();
      this.drillBanner = { text: 'ALL FOUR DRILLS PASSED — FREE RALLY!', t: 3.0 };
      return;
    }
    const next = DRILLS[this.drillIdx];
    this.targetGroup.visible = !next.touches;
    this.target.r = RING_R0;
    if (!next.touches) this.placeTarget();
    this.drillBanner = {
      text: `DRILL PASSED — ${d.name}! NEXT: ${next.name} — ${next.goal}`,
      t: 3.0
    };
    this.refreshTarget();
  }

  /// The drill banner: the ladder's congratulations and restart lines hold
  /// the message strip for a few seconds, outliving whatever the point flow
  /// wrote there the instant the ball died.
  updateDrillBanner(dt) {
    if (!this.drillBanner) return;
    this.drillBanner.t -= dt;
    if (this.drillBanner.t <= 0) {
      this.drillBanner = null;
      return;
    }
    this.msgText.textContent = this.drillBanner.text;
  }

  // ---------------------------------------------------------------- badges

  /// The badge toast: the moment a milestone is earned in play, a small gold
  /// pill slides in under the score — BADGE EARNED · FIRST WIN — with a
  /// cheerful sting and a light buzz, and slides away again after a couple
  /// of seconds.
  showBadgeToast(id) {
    const badge = BADGES.find((b) => b.id === id);
    if (badge) {
      this.showToast(`BADGE EARNED · ${badge.name}`);
      // The stands answer the milestone: the gold banner goes up.
      this.raiseBanner(badge.name);
    }
  }

  /// The title toast: the same gold pill under the score, announcing the
  /// moment a win raises the player's title — NEW TITLE · PRO.
  showTitleToast(title) {
    this.showToast(`NEW TITLE · ${title.name}`);
    // The stands answer the title: the gold banner goes up with its name.
    this.raiseBanner(title.name);
  }

  /// The weekly goal toast: the same gold pill under the score, announcing
  /// the moment a weekly goal completes — GOAL COMPLETE · WIN 3 MATCHES.
  showGoalToast(id) {
    const name = weeklyGoalName(id);
    if (name) this.showToast(`GOAL COMPLETE · ${name}`);
  }

  /// The shared celebration pill: created on the first toast, gold, sliding
  /// in under the score with a cheerful sting and a light buzz, and sliding
  /// away again after a couple of seconds.
  showToast(text) {
    if (!this.badgeToast) {
      this.badgeToast = addText('', {
        left: '50%',
        top: 'calc(env(safe-area-inset-top) + 92px)',
        transform: 'translate(-50%, -14px)',
        padding: '4px 14px',
        borderRadius: '999px',
        backgroundColor: 'rgba(228, 178, 34, 0.95)',
        color: '#231503',
        fontSize: '12px',
        fontWeight: '800',
        letterSpacing: '1.5px',
        whiteSpace: 'nowrap',
        opacity: '0',
        transition: 'transform 0.3s ease, opacity 0.3s ease',
        pointerEvents: 'none'
      });
    }
    this.badgeToast.textContent = text;
    this.badgeToast.style.transform = 'translate(-50%, 0)';
    this.badgeToast.style.opacity = '1';
    this.badgeToastT = 2.2;
    playBadgeSting();
    haptic('badge');
  }

  updateBadgeToast(dt) {
    if (this.badgeToastT <= 0) return;
    this.badgeToastT -= dt;
    if (this.badgeToastT <= 0) {
      this.badgeToast.style.transform = 'translate(-50%, -14px)';
      this.badgeToast.style.opacity = '0';
    }
  }

  // -------------------------------------------------------------- reactions

  /// The opponent's one-liner: the tone is set by their history with the
  /// player — a rival already beaten gives grudging respect, one still ahead
  /// gives needle — and the cooldown keeps the match's own flow in charge of
  /// when anything is said at all.
  opponentReact(kind) {
    if (!this.reactOn || this.reactCd > 0 || this.flyT > 0) return;
    this.reactCd = REACT_CD;
    const lines = REACT_LINES[kind][this.reactBeaten ? 'respect' : 'needle'];
    this.showOpponentLine(lines[(Math.random() * lines.length) | 0]);
  }

  /// The speech pill itself: a small bubble on the far side of the score —
  /// by the opponent's name — tinted with their own kit colour, sliding in
  /// from their edge of the screen and away again a couple of seconds later.
  showOpponentLine(line) {
    if (!this.reactPill) {
      this.reactPill = addText('', {
        right: '16px',
        top: 'calc(env(safe-area-inset-top) + 46px)',
        maxWidth: '200px',
        padding: '4px 11px',
        borderRadius: '12px',
        borderBottomRightRadius: '3px',
        backgroundColor: 'rgba(10, 18, 30, 0.78)',
        border: `1px solid ${this.colCpu}`,
        color: '#ffffff',
        fontSize: '11px',
        fontWeight: '700',
        fontStyle: 'italic',
        letterSpacing: '0.5px',
        lineHeight: '1.3',
        textAlign: 'right',
        opacity: '0',
        transform: 'translate(14px, 0)',
        transition: 'transform 0.3s ease, opacity 0.3s ease',
        pointerEvents: 'none'
      });
    }
    this.reactPill.textContent = line;
    this.reactPill.style.opacity = '1';
    this.reactPill.style.transform = 'translate(0, 0)';
    this.reactPillT = 2.6;
  }

  updateOpponentReact(dt) {
    this.reactCd = Math.max(0, this.reactCd - dt);
    if (!this.reactPillT) return;
    // The pill waits through a slow-motion replay or a line review like
    // everyone else: nothing the opponent says plays over the broadcast.
    if (this.state === 'replay' || this.state === 'challenge') return;
    this.reactPillT -= dt;
    if (this.reactPillT <= 0) {
      this.reactPill.style.opacity = '0';
      this.reactPill.style.transform = 'translate(14px, 0)';
    }
  }

  // ---------------------------------------------------------------- radar

  /// The radar readout: a small pill beside the server's head, on the open
  /// side of the screen, showing the serve's pace in km/h. Gold when the
  /// serve set a new career best, which the record banks on the spot — and
  /// a gold rank line beneath it when the serve merely enters the top five
  /// of the serve speed league, its kit colours riding into the record
  /// with it.
  showServeSpeed(w, kmh) {
    // The match's fastest serve is kept for the shot of the match: the
    // standout moment the recap names in gold at the end.
    if (!this.bestServe || kmh > this.bestServe.kmh) {
      this.bestServe = { kmh, id: w.id };
    }
    // The colours the serve was struck in bank with it: the player's or
    // player two's own picked kit, the partner's, or the roster colours of
    // whichever CPU stood on the far court.
    const kitCol = w.id === 'player' ? playerColors('p1')
      : this.coop && w.id === 'partner' ? playerColors('p2')
      : w.id === 'partner' ? playerColors('partner')
      : this.twoPlayer && w.id === 'cpu' ? playerColors('p2')
      : w.id === 'cpu2' ? this.cpu2Stats.colors
      : this.cpuStats.colors;
    const rank = recordServe(kmh, kitText(kitCol));
    this.speedPop = { w, t: 0, rank };
    this.speedText.textContent = `${kmh} KM/H`;
    this.speedText.style.color = rank === 1 ? '#ffd24a' : '#ffffff';
  }

  updateSpeedPop(dt) {
    const s = this.speedPop;
    if (!s) return;
    s.t += dt;
    if (s.t >= 1.6) {
      this.speedText.style.opacity = '0';
      this.speedRankText.style.opacity = '0';
      this.speedPop = null;
      return;
    }
    // The pill hangs beside the server, drifting gently upward as it fades.
    const a = s.w.athlete;
    this.tmp.set(a.position.x, a.position.y + 2.05, a.position.z).project(this.game.camera);
    const px = (this.tmp.x * 0.5 + 0.5) * this.viewW;
    const py = (-this.tmp.y * 0.5 + 0.5) * this.viewH;
    const x = clamp(px + (px < this.viewW / 2 ? -86 : 86), 52, this.viewW - 52);
    const y = clamp(py - 26 - s.t * 14, 92, this.viewH - 70);
    this.speedText.style.left = `${Math.round(x)}px`;
    this.speedText.style.top = `${Math.round(y)}px`;
    const fadeIn = clamp(s.t / 0.1, 0, 1);
    const fadeOut = clamp((1.6 - s.t) / 0.4, 0, 1);
    this.speedText.style.opacity = Math.min(fadeIn, fadeOut).toFixed(2);
    // The league rank beneath it — 3RD FASTEST EVER — riding the pill's
    // own fade, and gone again the moment the pill is.
    if (s.rank > 1) {
      const ord = ['1ST', '2ND', '3RD', '4TH', '5TH'];
      this.speedRankText.textContent = `${ord[s.rank - 1]} FASTEST EVER`;
      this.speedRankText.style.left = `${Math.round(x)}px`;
      this.speedRankText.style.top = `${Math.round(y + 15)}px`;
      this.speedRankText.style.opacity =
        (Math.min(fadeIn, fadeOut) * 0.95).toFixed(2);
    }
  }

  /// The rally pace readout: a small pill beside the athlete who just struck
  /// the ball, reading the touch's launch pace in km/h the way the serve
  /// radar reads its serve — hot when the touch left hard, gentle when it
  /// floated. It fades after a moment on its own, never touching the serve
  /// pill: the serve is the radar's alone.
  showRallyPace(w, kmh, hot) {
    if (kmh <= 0) return;
    // The match's fastest rally touch — the pace row the recap reads back.
    if (kmh > this.stats.fastestTouch) this.stats.fastestTouch = kmh;
    // The career best banks the moment the touch lands, remembered across
    // sessions like the fastest serve is.
    recordTouch(kmh);
    this.pacePop = { w, t: 0 };
    this.paceText.textContent = `${kmh} KM/H`;
    this.paceText.style.color = hot ? '#ff9e73' : '#cfe8ff';
  }

  updateRallyPacePop(dt) {
    const p = this.pacePop;
    if (!p) return;
    p.t += dt;
    if (p.t >= 1.2) {
      this.paceText.style.opacity = '0';
      this.pacePop = null;
      return;
    }
    // The pill hangs beside the striker, drifting gently upward as it fades.
    const a = p.w.athlete;
    this.tmp.set(a.position.x, a.position.y + 2.05, a.position.z).project(this.game.camera);
    const px = (this.tmp.x * 0.5 + 0.5) * this.viewW;
    const py = (-this.tmp.y * 0.5 + 0.5) * this.viewH;
    const x = clamp(px + (px < this.viewW / 2 ? -86 : 86), 52, this.viewW - 52);
    const y = clamp(py - 44 - p.t * 14, 92, this.viewH - 70);
    this.paceText.style.left = `${Math.round(x)}px`;
    this.paceText.style.top = `${Math.round(y)}px`;
    const fadeIn = clamp(p.t / 0.1, 0, 1);
    const fadeOut = clamp((1.2 - p.t) / 0.35, 0, 1);
    this.paceText.style.opacity = Math.min(fadeIn, fadeOut).toFixed(2);
  }

  // ---------------------------------------------------------------- match flow

  startServe(who, fresh = false) {
    // The tie-break banner lifts once its first serve goes up.
    if (this.tieBanner) {
      this.tieBanner.remove();
      this.tieBanner = null;
    }
    this.server = who;
    // Teams alternate: whoever holds this turn's serve.
    this.serverAth = this.nextServerAth(who);
    this.state = 'serve';
    this.timer = 1.1;
    this.ball.landed = false;
    this.ball.lastTouch = null;
    this.ball.sinceTouch = 9;
    this.ball.contactPause = 0;
    this.ball.sideSign = 0;
    this.resetBallSpin();
    for (const w of this.allTeam()) {
      resetAthlete(w.athlete);
      setDiveLean(w.athlete, 0);
      w.dive = null;
      w.getUp = 0;
      w.launched = false;
      // The break between points: everyone gets their breath back.
      w.stamina = 1;
    }
    this.touches = { player: 0, cpu: 0 };
    this.rallyLen = 0;
    this.hypeSaid = false;
    this.charge = 0;
    this.charge2 = 0;
    this.tossIgnoreRelease = false;
    this.tossIgnoreRelease2 = false;
    this.autoServeLive = false;
    this.rallyServeKmh = null;
    // Any booth call was for the point just played; a fresh serve starts
    // clean — the super strike's replay mark with it.
    this.replayCall = null;
    this.superReplay = false;
    // The receiving team walks home; the server stays where the point ended —
    // except at the start of a set, when everyone resets to their new ends.
    for (const w of who === 'player' ? this.farTeam() : this.nearTeam()) {
      w.athlete.position.copy(w.home);
      w.vy = 0;
    }
    if (fresh) {
      for (const w of this.allTeam()) {
        w.athlete.position.copy(w.home);
        w.vy = 0;
      }
    }
    // The top of a set opens with the booth's wind call before the serve.
    this.setMsg(fresh
      ? `${this.windCall()} — ${this.serveMessage(who)}`
      : this.serveMessage(who));
    // A fresh ring on the far court for the new attempt.
    if (this.practice && this.target) this.placeTarget();
  }

  /// The athlete who serves this turn: in doubles the two teammates trade
  /// their side's service turns — the player and the partner alternate on
  /// the near court, the two opponents on the far one.
  nextServerAth(side) {
    if (!this.doubles) return side === 'player' ? this.player : this.cpu;
    const team = side === 'player' ? this.nearTeam() : this.farTeam();
    const w = team[this.serverRot[side] % team.length];
    this.serverRot[side] = (this.serverRot[side] + 1) % team.length;
    return w;
  }

  /// The controlled serve, step one: a tap of jump tosses the ball straight
  /// up from the hitting hand. What happens next is all timing.
  startToss() {
    const a = this.player.athlete;
    const b = this.ball;
    this.state = 'toss';
    this.tossWho = 'player';
    this.tossAth = this.player;
    b.mesh.position.set(a.position.x, a.position.y + 1.5, a.position.z - this.player.side * 0.4);
    b.vel.set(0, TOSS_V, 0);
    b.lastTouch = 'player';
    b.sinceTouch = 0;
    b.pop = 0;
    b.spinRate = 0;
    this.resetBallSpin();
    this.tossApex = b.mesh.position.y;
    // The toss tap is still held: its release must not count as a strike.
    this.tossIgnoreRelease = true;
    playBump(0.35);
    haptic('bump');
    this.setMsg('');
  }

  /// The controlled serve, step two: jump is released and the tossed ball is
  /// struck from wherever it hangs at that instant. Contact near the top of
  /// the toss with a charged meter sends a flat, fast jump serve; contact on
  /// the way down floats a high, slow ball. Aim follows the drag as in a
  /// rally. If the toss was never struck it has already landed, and the point
  /// went to the CPU.
  /// The controlled serve, step one, for the far athlete: player two in a
  /// shared-screen match, or the CPU when it chooses to jump serve.
  startTossCpu(w = this.cpu) {
    const a = w.athlete;
    const b = this.ball;
    this.state = 'toss';
    this.tossWho = 'cpu';
    this.tossAth = w;
    b.mesh.position.set(a.position.x, a.position.y + 1.5, a.position.z - w.side * 0.4);
    b.vel.set(0, TOSS_V, 0);
    b.lastTouch = w.id;
    b.sinceTouch = 0;
    b.pop = 0;
    b.spinRate = 0;
    this.resetBallSpin();
    this.tossApex = b.mesh.position.y;
    // The toss tap is still held: its release must not count as a strike.
    this.tossIgnoreRelease2 = true;
    playBump(0.35);
    haptic('bump');
    this.setMsg('');
  }

  /// The controlled serve, step two: jump is released and the tossed ball is
  /// struck from wherever it hangs at that instant. Contact near the top of
  /// the toss with a charged meter sends a flat, fast jump serve; contact on
  /// the way down floats a high, slow ball. Aim follows the drag as in a
  /// rally. If the toss was never struck it has already landed, and the point
  /// went to the other side.
  serveStrike() {
    if (this.state !== 'toss' || this.ball.landed || this.tossWho !== 'player') return;
    const pos = this.ball.mesh.position;
    if (!canStrikeBall(this.player.athlete, pos)) return;
    const jumpServe = pos.y >= this.tossApex - 0.8 && this.charge >= 0.5;
    // The rally is live from the instant the ball is struck.
    this.state = 'rally';
    playWhistle();
    this.setMsg('');
    this.serveLaunch(this.player, this.input, this.charge, jumpServe);
  }

  /// The same strike, for the second player's serve.
  serveStrike2() {
    if (this.state !== 'toss' || this.ball.landed || this.tossWho !== 'cpu') return;
    const w = this.coop ? this.partner : this.cpu;
    const pos = this.ball.mesh.position;
    if (!canStrikeBall(w.athlete, pos)) return;
    const jumpServe = pos.y >= this.tossApex - 0.8 && this.charge2 >= 0.5;
    this.state = 'rally';
    playWhistle();
    this.setMsg('');
    this.serveLaunch(w, this.input2, this.charge2, jumpServe);
  }

  /// The serve signature of whoever stands at the line — the roster athlete
  /// they are, on either side of the net. Every roster entry carries one; the
  /// guards only keep a stripped opponent entry from breaking the launch.
  serveSignature(w) {
    const st = w.id === 'player' ? this.playerStats
      : w.id === 'partner' ? (this.partnerStats || this.playerStats)
      : w.id === 'cpu2' ? (this.cpu2Stats || this.cpuStats)
      : this.cpuStats;
    return (st && st.serve) || null;
  }

  /// The signature's flavour on the ball it sends over: the laser carries
  /// barely any rotation, Rex's serves turn over heavily, the float drags
  /// against its own pace and sits down short, and the banana bends mid-air
  /// all on its own — stacked onto whatever the strike already put on the
  /// ball, so the player's own swipe still leads the spin.
  applyServeSignature(b, sig, spike) {
    b.spinRate += spike ? sig.topspin : sig.topspin * 0.5;
    if (sig.backDrag > 0) {
      b.backDrag = Math.max(b.backDrag, sig.backDrag);
      b.spinAxis.copy(this.tmp2).cross(this.tmpUp);
    }
    if (sig.sidespin > 0) {
      const len = Math.hypot(b.vel.x, b.vel.z) || 1;
      const dx = b.vel.x / len, dz = b.vel.z / len;
      const mag = sig.sidespin * (0.55 + len * 0.1);
      b.curve.x += -dz * this.playerSide * mag;
      b.curve.z += dx * this.playerSide * mag;
      // The spin leans toward the vertical so the bend shows in the turnover.
      b.spinAxis.y += this.playerSide * Math.min(0.6, 0.25 + sig.sidespin * 0.5);
      b.spinAxis.normalize();
    }
  }

  /// The launch maths both serves share: from the contact point toward the
  /// opposite court, steered by the striker's drag, the meter buying pace and
  /// depth on a jump serve and the float hanging high instead.
  serveLaunch(w, input, charge, jumpServe, isServe = true) {
    const b = this.ball;
    const pos = b.mesh.position;
    // Whoever stands at the line serves in their own way: the roster
    // athlete's signature shapes the launch, on either side of the net.
    const sig = isServe ? this.serveSignature(w) : null;
    const steer = 6.5 + 9 * charge;
    const tx = clamp(input.x * this.playerSide * steer, -3.6, 3.6) +
      (Math.random() - 0.5) * 0.6 * (sig ? sig.aim : 1);
    const depthNudge = input.z * this.playerSide * 1.6;
    let T;
    let tz;
    if (jumpServe) {
      // Flat and fast: the meter buys pace and depth.
      T = (0.72 - 0.2 * charge) * (sig ? sig.arcJump : 1);
      tz = -w.side * (4.8 + 2.4 * charge);
    } else {
      // A float: struck late or lightly, it hangs high and drifts down.
      T = (1.5 + Math.random() * 0.2) * (sig ? sig.arcFloat : 1);
      tz = -w.side * (3.2 + Math.random() * 2.2);
    }
    tz = clamp(tz, -7.2, 7.2) + depthNudge;

    // Ballistic solve from the contact point, same as every other strike.
    this.resetBallSpin();
    b.vel.set(
      (tx - pos.x) / T,
      (-pos.y + 0.5 * G * T * T) / T,
      (tz - pos.z) / T
    );
    const h = Math.hypot(b.vel.x, b.vel.z);
    // The signature's pace rides the same cap: the laser's flat launch would
    // otherwise hit the return-ability ceiling and lose its depth.
    const maxH = (jumpServe ? 16 + 6 * charge : 9) * (sig ? sig.pace : 1);
    if (h > maxH) {
      b.vel.x *= maxH / h;
      b.vel.z *= maxH / h;
    }
    // The team talk's pace rides the serve too.
    b.vel.multiplyScalar(this.talkPace(w));
    // A human striker bends the serve with a swipe across the flight; the
    // CPU's serve keeps the behaviour it has always had. Applied once the
    // shot's own spin axis is set below.
    const human = w.id === 'player' ||
      (this.twoPlayer && w.id === 'cpu') || (this.coop && w.id === 'partner');
    let spin = null;
    if (human) {
      const dx = tx - pos.x;
      const dz = tz - pos.z;
      const len = Math.hypot(dx, dz) || 1;
      spin = this.readSideSpin(input, dx / len, dz / len);
    }

    b.lastTouch = w.id;
    b.sinceTouch = 0;
    b.contactPause = 0.028;
    b.pop = 1;
    b.squashDir.copy(b.vel).normalize();
    this.tmp2.copy(b.vel).setY(0);
    if (this.tmp2.lengthSq() > 0.001) this.tmp2.normalize();
    if (jumpServe) {
      // Topspin: the serve dips late over the net like a driven ball.
      b.spinAxis.copy(this.tmpUp).cross(this.tmp2);
      b.spinRate = 8 + charge * 8 + (sig ? sig.topspin : 0);
      b.wasSpike = true;
      triggerSwing(w.athlete, 'spike', pos);
      playSlap(0.6 + charge * 0.45);
      this.camKick = Math.min(1, 0.45 + charge * 0.4);
      haptic('slap');
      // A jump serve struck near the top with a full meter flashes too.
      if (charge >= 0.75) this.spawnFlash(pos);
    } else {
      // Backspin: the float hangs and wobbles on its way over — and, struck
      // late and low as it was, it drags against its own pace and sits down
      // short after crossing. The float server's signature hangs the same way.
      b.backDrag = (human ? 0.35 : 0) + (sig ? sig.backDrag : 0);
      b.spinAxis.copy(this.tmp2).cross(this.tmpUp);
      b.spinRate = 4;
      b.wasSpike = false;
      triggerSwing(w.athlete, pos.y - w.athlete.position.y > 1.8 ? 'tip' : 'bump', pos);
      playBump(0.7);
      haptic('bump');
    }
    // The sidespin goes on last, leaning the ball's own rotation toward the
    // vertical so the curve it will fly with shows in the spin itself.
    if (spin) {
      this.applySideSpin(
        spin, Math.hypot(b.vel.x, b.vel.z),
        b.spinAxis.x, b.spinAxis.y, b.spinAxis.z
      );
    }
    // The signature's own flavour rides on top: the laser's extra bite,
    // Rex's heavy topspin turnover, the float's hang, and the banana's
    // bend — stacked on whatever the strike put on the ball, so a human
    // swipe still leads the spin.
    if (sig) this.applyServeSignature(b, sig, jumpServe);
    // The radar gun reads every serve: the pace of the strike off the hand,
    // shown beside the server. A rally strike is not a serve and reads
    // nothing on it — its own pace readout pops beside the striker — and
    // only a serve keeps the ace window open.
    if (isServe) {
      this.serveLive = w.id;
      // The pace this rally's serve left at — every banked recording tags
      // itself with it, so the fastest serve's own rally can be found at
      // the recap.
      this.rallyServeKmh = serveKmh(b.vel);
      this.showServeSpeed(w, this.rallyServeKmh);
    } else {
      this.serveLive = null;
      // A rally strike reads its pace the way a bump does: a driven shot,
      // so it leaves hot.
      this.showRallyPace(w, serveKmh(b.vel), true);
    }
    // The drill ladder reads the kind of the player's last shot off this:
    // a serve counts for the timing drill, a strike for placement.
    if (w.id === 'player') this.lastShot = isServe ? 'serve' : 'spike';
  }

  award(winner, reason) {
    if (this.state === 'over') return;
    // Any dead ball ends both the ace window and any block in progress.
    this.serveLive = null;
    this.blockPending = null;
    if (this.practice) {
      // No scoring: a dead ball resets both athletes home and re-serves, with
      // the serve trading ends so both sides of the game get practised. The
      // streak dies with the ball: the session keeps its best, and the record
      // banks the longest rally ever kept alive against the CPU.
      if (this.rallyLen > this.sessionStreak) this.sessionStreak = this.rallyLen;
      recordStreak(this.rallyLen);
      if (this.drill) {
        // The drill: the machine reloads and feeds again. The streak only
        // dies when a ball gets past the player — a return that lands on the
        // far court keeps the run going.
        const missed = winner === 'cpu';
        if (missed) this.rallyLen = 0;
        this.state = 'point';
        this.timer = DRILL_PACE[this.pace].gap;
        this.nextServer = 'machine';
        this.setMsg(missed
          ? `${reason ? reason + ' ' : ''}MACHINE RELOADS — STREAK RESET`
          : 'CLEAN PASS — MACHINE FEEDS AGAIN');
        haptic('tick');
        return;
      }
      this.practiceServer = this.practiceServer === 'player' ? 'cpu' : 'player';
      for (const w of [this.player, this.cpu]) {
        w.athlete.position.copy(w.home);
        w.vy = 0;
        w.moveMag = 0;
        w.runMag = 0;
        w.dive = null;
        w.getUp = 0;
        setDiveLean(w.athlete, 0);
      }
      this.state = 'point';
      this.timer = 1.1;
      this.nextServer = this.practiceServer;
      this.setMsg(
        `${reason ? reason + ' ' : ''}NO POINT — ${this.practiceServer === 'player' ? 'YOU SERVE' : 'CPU SERVE'}`
      );
      haptic('tick');
      return;
    }
    // A big rally, a set-point rally, a point won clean by an ace or a
    // block — or a super strike burned somewhere in it — earns a slow-motion
    // replay before the next serve: decided here, while the score still
    // reads the moment before the point landed. An ace or a block also
    // queues the booth's one-liner for the banner, the same call for either
    // side — and so does the super strike, whoever played it.
    const kind = this.lastPointKind;
    this.lastPointKind = null;
    // A super strike burned in this rally: its end queues the sideline
    // replay too, whoever played it.
    const superRally = this.superReplay;
    this.superReplay = false;
    // The rally just played is the one every banked recording tags: kept
    // beside the rally so the pool's entries describe their own rally.
    this.lastRallySuper = superRally;
    // A challenge just settled this point on the court already shown: no
    // second replay of the same rally.
    const wantReplay = !this.skipReplayOnce &&
      (this.rallyLen >= 7 || this.setPointSide() !== null || kind !== null ||
        superRally);
    this.superQueued = superRally && wantReplay;
    // The big points are measured as they land: set point, match point —
    // which is the set point that would end the match — and every point of
    // the golden tie-break. Read before the score moves: set point is a
    // state the standing score carries into a rally, not out of it.
    const clutchPoint = this.tieBreak || this.setPointSide() !== null;
    this.skipReplayOnce = false;
    if (kind) {
      this.replayCall = kind === 'ace' ? 'ACE!' : 'WHAT A BLOCK!';
    } else if (superRally) {
      this.replayCall = 'SUPER STRIKE!';
    }
    // A momentum call the swing just queued: spoken at the end of the point
    // line, and dropped again if this point actually took the set.
    const momCall = this.momentumCall;
    this.momentumCall = null;
    this.score[winner]++;
    this.stats.points[winner]++;
    if (clutchPoint) this.stats.clutch[winner]++;
    // The serve runs: consecutive points won on serve, kept per side — in
    // the doubles modes a team's serves count as the one side's run,
    // whoever takes the turn. The serving side's run grows while it keeps
    // winning its own serve; the moment service changes hands the run is
    // over and both sides sit at zero. The best run either side strung
    // together is what the recap reads back.
    if (winner === this.server) {
      this.stats.serveRun[winner]++;
      // The weekly serve-run goal reads the near side's own run as it grows.
      if (winner === 'player' &&
          recordWeeklyBest('serveRun', this.stats.serveRun.player)) {
        this.showGoalToast('serveRun');
      }
      if (this.stats.serveRun[winner] > this.stats.serveRun.best) {
        this.stats.serveRun.best = this.stats.serveRun[winner];
      }
    } else {
      this.stats.serveRun.player = 0;
      this.stats.serveRun.cpu = 0;
    }
    // The opponent reads a run of aces: the second clean serve in a row —
    // and every one after it the cooldown allows — earns a word from across
    // the net. Any point that is not an ace ends the streak.
    if (kind === 'ace' && winner === 'player') {
      this.reactAces++;
      if (this.reactAces >= 2) this.opponentReact('ace');
      // The weekly aces goal reads every ace the near side serves up, the
      // moment it lands.
      if (recordWeeklyStat('aces')) this.showGoalToast('aces');
    } else {
      this.reactAces = 0;
    }
    // The trail each side has had to climb out of this set: the worst of it
    // is kept, so a set taken from three or more points down reads as a
    // comeback when it lands.
    if (this.score.cpu - this.score.player > this.deficitMax.player) {
      this.deficitMax.player = this.score.cpu - this.score.player;
    }
    if (this.score.player - this.score.cpu > this.deficitMax.cpu) {
      this.deficitMax.cpu = this.score.player - this.score.cpu;
    }
    this.stats.longestRally = Math.max(this.stats.longestRally, this.rallyLen);
    // The record rally: a rally longer than any ever played banks its
    // closing seconds as a slow-motion recording the career screen keeps
    // beside its touch count.
    const recSoFar = rallyReplay();
    if (this.rallyLen > 0 && (!recSoFar || this.rallyLen > recSoFar.touches)) {
      recordRallyReplay(this.rallyLen, this.rallyRecording());
    }
    this.bumpMomentum(winner);
    this.refreshScore();
    haptic(this.twoPlayer || winner === 'player' ? 'point' : 'loss');
    // The adaptive level reads every point: a run of three straight shifts
    // the CPU a notch, the score evening out melts the bias back.
    this.updateAdaptation(winner);

    const other = winner === 'player' ? 'cpu' : 'player';

    // The blitz has no sets to take: the running score and the clock decide.
    // The sudden-death point lands and the match ends with it; the horn
    // settling on a level score hands the next point sudden-death power.
    if (this.blitz) {
      if (this.blitzSD) {
        this.endBlitzMatch(winner);
        return;
      }
      if (this.blitzExpired) {
        this.blitzExpired = false;
        if (this.score.player === this.score.cpu) this.hornLevel();
        else {
          this.endBlitzMatch(
            this.score.player > this.score.cpu ? 'player' : 'cpu'
          );
          return;
        }
      }
    }

    // A set is taken at its target points — or at 15, two clear, in the
    // tie-break.
    const tookSet = this.score[winner] >=
      (this.tieBreak ? TIEBREAK_SCORE : this.setPoints) &&
      this.score[winner] - this.score[other] >=
        (this.tieBreak ? TIEBREAK_MARGIN : 1);
    if (tookSet) {
      this.sets[winner]++;
      // The team talk stood for the set just finished: both tactics end here,
      // and a fresh huddle can offer new ones.
      this.teamTalk = null;
      this.cpuTalk = null;
      // The comeback read: the side that just took this set had been three
      // or more points down in it at some stage — the set was stolen from
      // the brink. The booth names it with its own sting and the crowd
      // comes up off the sand, whoever pulled it off.
      const comeback = this.deficitMax[winner] >= 3;
      if (comeback) {
        this.stats.comebacks++;
        playComebackSting();
        this.crowdRoar(1);
        // A set stolen from behind is the hardest thing to swallow: the
        // opponent answers it, if the player is the one who stole it.
        if (winner === 'player') this.opponentReact('comeback');
      }
      // Remember the set as it finished, the player's points first.
      this.setScores.push(this.score.player > this.score.cpu
        ? `${this.score.player}–${this.score.cpu}`
        : `${this.score.cpu}–${this.score.player}`);
      this.score = { player: 0, cpu: 0 };
      // A fresh set starts level: the worst trail of the last one is forgotten.
      this.deficitMax = { player: 0, cpu: 0 };
      this.refreshScore();
      this.refreshTally();
      // A set taken by the player: the arena calls their name for it.
      if (winner === 'player' && this.sets[winner] < this.setsToWin) {
        this.callPlayerName();
      }
      // A fresh set, a fresh review: one challenge back on the table — and
      // the set's timeout back in hand beside it.
      this.challengesLeft = 1;
      this.refreshChallengePill();
      this.timeoutsLeft = 1;
      this.refreshTimeoutPill();
      // A new set starts level: the adaptive bias melts back to even.
      if (this.adapt !== 0) {
        this.adapt = 0;
        this.applyAdapt();
        this.refreshAdapt();
      }
      this.runWho = null;
      this.runLen = 0;
      // The golden tie-break taken: a milestone badge, toasted the moment
      // it lands.
      if (this.tieBreak && winner === 'player' && recordMilestone('tiebreak')) {
        this.showBadgeToast('tiebreak');
      }

      if (this.sets[winner] >= this.setsToWin) {
        this.state = 'over';
        playCheer(true);
        this.crowdWaveStart(1);
        this.matchWinner = winner;
        this.overT = 0;
        // The match is won: the arena calls the winner's name outright.
        if (winner === 'player') this.callPlayerName();
        // A win earns a victory lap: the near team jogs their own baseline and
        // back, the losers walk to the net, and the recap waits for it.
        if (winner === 'player') this.startVictoryLap();
        // The final rally never earns its replay — the match ends on it — so
        // the shot-of-the-match pool banks its recording here instead. An ace
        // landing for the last point is the serve moment's own clip.
        this.bankShotReplay(kind === 'ace');
        // The match log: the result is appended the moment the match ends —
        // the mode, the opponent, the set scores and the date with it.
        recordMatchLog({
          mode: this.dailyMatch ? 'DAILY'
            : this.cupMatch
              ? `${this.cupMatch.doubles ? 'DBL ' : ''}CUP R${this.cupMatch.round}`
            : this.ladderMatch ? `LADDER R${this.ladderMatch.rung}`
            : this.coop ? 'CO-OP'
            : this.doubles ? 'DOUBLES'
            : this.twoPlayer ? 'TWO PLAYERS' : 'VS CPU',
          opp: this.doubles ? 'CPU PAIR'
            : this.twoPlayer ? 'P2' : this.cpuStats.name.toUpperCase(),
          score: this.setScores.join(' · '),
          won: winner === 'player',
          aces: this.stats.aces.cpu,
          spikes: this.stats.spikes.cpu,
          date: dateKey()
        });
        // The placement heat grids bank with the result: both tallies join
        // the career-long ones, and the next match starts fresh.
        recordHeatShots(this.heat);
        recordRivalHeatShots(this.heatRival);
        // The weekly goals read the result the moment it lands: a match win
        // banks toward the wins goal, whatever the mode it was won in.
        if (winner === 'player' && recordWeeklyStat('wins')) {
          this.showGoalToast('wins');
        }
        if (this.cupMatch) {
          // A cup round: no career tally here and no rematch card — the
          // bracket decides what happens after the celebration.
          this.pendingHeadline = winner === 'player'
            ? (this.cupMatch.round >= 3 ? 'YOU WIN THE CUP!' : `ROUND ${this.cupMatch.round} WON!`)
            : `KNOCKED OUT BY ${this.cpuStats.name.toUpperCase()}`;
        } else if (this.dailyMatch) {
          // The daily: the headline says who stood in the way today.
          this.pendingHeadline = winner === 'player'
            ? 'DAILY CHALLENGE WON!'
            : `BEATEN BY ${this.cpuStats.name.toUpperCase()}`;
        } else if (this.ladderMatch) {
          // The ladder: the headline reads the rung just played — a win
          // climbs, a loss slides back one.
          this.pendingHeadline = winner === 'player'
            ? `RUNG ${this.ladderMatch.rung} BEATEN!`
            : `BEATEN BY ${this.cpuStats.name.toUpperCase()}`;
        } else {
          playFanfare();
          // The career tally counts the result the moment the match ends —
          // per mode, with the points player one scored, the longest rally
          // of the match, the aces and blocks, the clutch record — the big
          // points won and lost — the best run of points won on serve, the
          // comeback sets — taken from three or more points down — and
          // whether the match ended with a shot of the match, remembered
          // across sessions.
          // Any badge the match itself earned — a first career win, the
          // tenth — toasts with the celebration.
          // A title the win just raised — ROOKIE through LEGEND — is
          // announced on the same gold toast, remembered with the tally.
          const titleBefore = playerTitle();
          // The shot of the match, picked before the career tally banks it:
          // the standout moment — the fastest serve, the longest rally or a
          // super strike, whichever measured biggest — named in gold on the
          // recap, and counted career long.
          this.shot = this.pickShotOfMatch();
          recordMatch(
            this.doubles ? 'doubles' : this.twoPlayer ? '2p' : 'cpu',
            winner === 'player',
            this.stats.points.player,
            this.stats.longestRally,
            this.stats.aces.player,
            this.stats.blocks.player,
            this.stats.clutch.won,
            this.stats.clutch.lost,
            this.stats.serveRun.best,
            this.stats.comebacks,
            this.shot ? 1 : 0
          ).forEach((id) => this.showBadgeToast(id));
          // The recruit's crossing: this win carried the career past her
          // requirement — she signs onto the roster here, in play, under a
          // gold toast consumed so the title doesn't announce her again.
          if (this.novaChar && !this.novaBefore && winner === 'player' &&
              athleteUnlocked(this.novaChar)) {
            this.showToast(
              `RECRUIT SIGNED · ${this.novaChar.name} JOINS THE ROSTER`
            );
            takeAthleteToast(true);
          }
          const titleAfter = playerTitle();
          if (titleAfter.id !== titleBefore.id) this.showTitleToast(titleAfter);
          this.pendingHeadline = this.coop
            ? (winner === 'player'
              ? `${playerName('p1')} & ${playerName('p2')} WIN THE MATCH ${this.sets[winner]}–${this.sets[other]}!`
              : `${playerName('p1')} & ${playerName('p2')} LOSE THE MATCH ${this.sets[other]}–${this.sets[winner]}`)
            : this.twoPlayer
            ? `${winner === 'player' ? playerName('p1') : playerName('p2')} WINS THE MATCH ${this.sets[winner]}–${this.sets[other]}!`
            : (winner === 'player'
              ? `${playerName('p1')} WINS THE MATCH ${this.sets.player}–${this.sets.cpu}!`
              : `CPU WINS THE MATCH ${this.sets.cpu}–${this.sets.player}`);
        }
        // The series read at the end of each of its matches.
        const seriesLine = this.settleSeries(winner);
        if (seriesLine) this.pendingHeadline = seriesLine;
        // The booth names the comeback even when the set ended the match.
        if (comeback) {
          this.pendingHeadline = 'WHAT A COMEBACK! ' + this.pendingHeadline;
        }
        this.setMsg(this.pendingHeadline);
        return;
      }

      // New set: swap ends of the court; the side that lost it serves first.
      // A split one set short of the match raises the golden tie-break
      // instead of a deciding set: fifteen points, two clear, ends swapping
      // every six — a 2-2 marathon split goes there too.
      this.tieBreak = this.sets.player === this.sets.cpu &&
        this.sets.player === this.setsToWin - 1;
      this.state = 'set';
      playCheer(false, 1.15);
      this.crowdWaveStart(1);
      this.timer = 2.4;
      // A fresh set starts with no match point up — and no booth call
      // spent on it yet.
      this.mpWas = false;
      this.mpSaid = false;
      this.nextServer = other;
      this.playerSide *= -1;
      this.applySides();
      // Everyone takes their new end during the break: the movement clamps
      // already belong to the new sides, so leaving the athletes standing on
      // the old ones would yank them across the net mid-changeover.
      for (const w of this.allTeam()) {
        w.athlete.position.copy(w.home);
        w.vy = 0;
      }
      // The weather shifts with the changeover: whatever the breeze just did
      // is already live on the court and in the air.
      const weather = this.shiftWeather();
      // The camera takes the scenic route round the sideline during the break.
      this.camSwing = true;
      if (this.tieBreak) {
        // The golden set announces itself: a banner over the changeover and
        // its own sting from the booth.
        this.tieBanner = addText('TIE-BREAK', {
          left: '50%',
          top: 'calc(env(safe-area-inset-top) + 120px)',
          transform: 'translateX(-50%)',
          padding: '5px 16px',
          borderRadius: '6px',
          backgroundColor: 'rgba(228, 178, 34, 0.92)',
          color: '#231503',
          fontSize: '14px',
          fontWeight: '800',
          letterSpacing: '4px'
        });
        playSting();
      }
      const summary = this.setSummary(winner, comeback);
      if (this.tieBreak) {
        this.setMsg(
          (comeback ? 'WHAT A COMEBACK! ' : '') +
          (this.twoPlayer
            ? `SET TO ${winner === 'player' ? 'P1' : 'P2'}! `
            : (winner === 'player' ? 'SET TO YOU! ' : 'SET TO CPU — ')) +
          'GOLDEN TIE-BREAK — 15 POINTS, TWO CLEAR' +
          (weather ? ` — ${weather}` : '')
        );
      } else {
        // Both teams meet at the tape for a short huddle before the next
        // serve, the booth summing the set over a whistle.
        this.beginHuddle(summary);
      }
      if (wantReplay) this.replayPending = true;
      return;
    }

    // In the tie-break the ends swap every six points, mid-set.
    let swapNote = '';
    if (this.tieBreak && (this.score.player + this.score.cpu) % TIEBREAK_SWAP === 0) {
      this.playerSide *= -1;
      this.applySides();
      // Everyone walks to their new end during the changeover.
      for (const w of this.allTeam()) {
        w.athlete.position.copy(w.home);
        w.vy = 0;
      }
      this.camSwing = true;
      swapNote = 'SWITCHING SIDES! ';
    }
    this.state = 'point';
    // The cheer follows the rally it rewarded: a fault after one touch
    // barely lifts the crowd off its murmur, a long battle brings a real
    // roar — and the moment match point arrives, the arena erupts outright.
    const mp = this.isMatchPoint();
    playCheer(false, clamp(0.55 + this.rallyLen / 9 + (mp ? 0.35 : 0), 0.55, 1.35));
    if (mp && !this.mpWas) this.crowdRoar(1);
    this.mpWas = mp;
    // The booth's call: the first time a set stands on match point, the
    // arena is told so — once per set, whatever the rally does after it.
    let mpCall = '';
    if (mp && !this.mpSaid) {
      this.mpSaid = true;
      mpCall = 'MATCH POINT!';
    }
    // An ace or a block sends the wave round the stands the moment the
    // point lands — the crowd on its feet for the clean strike, whoever
    // played it.
    if (kind) this.crowdWaveStart(0.85);
    this.timer = 1.7;
    this.nextServer = winner;
    this.setMsg(
      ((this.twoPlayer || winner === 'player') && this.rallyLen >= 4 ? 'YESSS! ' : '') +
      (reason ? reason + ' ' : '') +
      (winner === 'player'
        ? (this.twoPlayer ? 'P1 POINTS! ' : 'YOUR POINT! ')
        : (this.twoPlayer ? 'P2 POINTS! ' : 'CPU SCORES ')) +
      (mpCall ? 'MATCH POINT! ' : '') +
      swapNote +
      (this.setPointSide() && !mpCall ? 'SET POINT! ' : '') +
      (momCall ? ' ' + momCall : '')
    );
    if (wantReplay) this.replayPending = true;
  }

  refreshScore() {
    if (this.practice) {
      // The practice court keeps the scoreboard dark.
      this.scoreText.textContent = 'PRACTICE · NO SCORE';
      return;
    }
    this.scoreText.textContent = this.twoPlayer
      ? `P1 ${this.score.player} · P2 ${this.score.cpu}`
      : `YOU ${this.score.player} · ${this.cupMatch || this.dailyMatch || this.ladderMatch || this.rivalMatch ? this.cpuStats.name.toUpperCase() : 'CPU'} ${this.score.cpu}`;
    this.refreshSetStrip();
  }

  /// The set-by-set strip: every finished set in order, then the live set's
  /// score, all shown in the player's own columns — the player's number first
  /// while the ends sit that way round, and swapped when they change — with
  /// the set under way riding the end in gold. Practice and the blitz keep
  /// their dark scoreboards and get no strip at all.
  refreshSetStrip() {
    if (!this.setStrip || !this.setPills) return;
    const show = !this.practice && !this.blitz && this.state !== 'over' &&
      !!this.score && !!this.setScores;
    this.setStrip.style.display = show ? 'flex' : 'none';
    if (!show) return;
    const flip = this.playerSide < 0;
    const entries = this.setScores.map((s) => {
      const [p, c] = s.split('–').map(Number);
      return flip ? [c, p] : [p, c];
    });
    entries.push(flip
      ? [this.score.cpu, this.score.player]
      : [this.score.player, this.score.cpu]);
    this.setPills.forEach((pill, i) => {
      const e = entries[i];
      if (!e) {
        pill.style.display = 'none';
        return;
      }
      const live = i === entries.length - 1;
      pill.style.display = '';
      pill.textContent = `${e[0]}–${e[1]}`;
      pill.style.color = live ? '#ffd24a' : 'rgba(255, 255, 255, 0.75)';
      pill.style.border = live
        ? '1px solid rgba(255, 210, 74, 0.5)'
        : '1px solid rgba(255, 255, 255, 0.12)';
    });
  }

  refreshTally() {
    if (this.practice) {
      this.setTally.style.opacity = '0';
      return;
    }
    if (this.blitz) {
      // The blitz has no sets: the tally names the format — and sudden death
      // once the horn has levelled it.
      this.setTally.textContent = this.blitzSD
        ? 'BLITZ · SUDDEN DEATH'
        : 'BLITZ · THREE MINUTES';
      return;
    }
    if (this.dailyMatch) {
      // The daily is one set: the tally names the day's challenge instead.
      this.setTally.textContent = 'DAILY CHALLENGE · ONE SET';
      return;
    }
    if (this.cupMatch) {
      // A cup round is one set: the tally names the round instead.
      this.setTally.textContent =
        `${this.cupMatch.doubles ? 'DOUBLES ' : ''}CUP · ROUND ${this.cupMatch.round} OF 3`;
      return;
    }
    if (this.ladderMatch) {
      // A ladder rung is one set: the tally names the rank being played.
      this.setTally.textContent = `LADDER · RANK ${this.ladderMatch.rung} · ONE SET`;
      return;
    }
    this.setTally.textContent = this.tieBreak
      ? `SETS ${this.sets.player}–${this.sets.cpu} · TIE-BREAK`
      : `SETS ${this.sets.player}–${this.sets.cpu}`;
  }

  // ---------------------------------------------------------------- adapt

  /// The adaptive level, one point at a time: a run of three straight points
  /// for either side shifts the CPU's speed, prediction and aim one notch
  /// toward the player being left behind — two notches at most — and the
  /// score evening out melts the bias back to even. The pill beside the
  /// clock names whatever the bias is right now.
  updateAdaptation(winner) {
    if (!this.adaptOn) return;
    if (this.runWho === winner) this.runLen++;
    else {
      this.runWho = winner;
      this.runLen = 1;
    }
    // The score even again: the bias melts away — and no fresh shift is
    // earned by a run that merely levelled the match.
    if (Math.abs(this.score.player - this.score.cpu) <= 1) {
      if (this.adapt !== 0) {
        this.adapt = 0;
        this.applyAdapt();
        this.refreshAdapt();
      }
      return;
    }
    // Three in a row — and every three after that: one notch toward the
    // side being left behind. A light tick marks the shift.
    if (this.runLen >= 3 && this.runLen % 3 === 0) {
      this.adapt = clamp(this.adapt + (winner === 'cpu' ? 1 : -1), -2, 2);
      this.applyAdapt();
      this.refreshAdapt();
      haptic('tick');
    }
  }

  /// Swaps the live difficulty for a biased copy of the chosen one — the
  /// CPU a touch slower, sloppier in its read and wilder in its aim per
  /// notch it is eased, and the reverse per notch it is sharpened.
  applyAdapt() {
    const d = this.baseDiff;
    const a = this.adapt;
    if (a === 0) {
      this.diff = d;
      return;
    }
    this.adaptDiff = {
      ...d,
      speedScale: d.speedScale * (1 - 0.06 * a),
      predict: Math.max(0.18, d.predict * (1 + 0.25 * a)),
      aimError: Math.max(0.08, d.aimError * (1 + 0.3 * a))
    };
    this.diff = this.adaptDiff;
  }

  /// The bias pill: redrawn only when the bias actually changes.
  refreshAdapt() {
    if (!this.adaptPill) return;
    const text = this.adapt > 0 ? 'FAVOURS YOU'
      : this.adapt < 0 ? 'FAVOURS CPU' : 'EVEN';
    if (text === this.adaptShown) return;
    this.adaptShown = text;
    this.adaptPill.textContent = text;
    this.adaptPill.style.color = this.adapt > 0 ? '#ffd24a'
      : this.adapt < 0 ? '#ff8a7a' : 'rgba(255,255,255,0.75)';
  }

  // ---------------------------------------------------------------- momentum

  /// Each point won pushes the bar toward the side that took it — and a long
  /// rally won pushes harder, the fight of the rally being part of the swing.
  /// A point that shoves the bar past the high mark also earns the booth's
  /// one-line call about the swing, queued until the point line is spoken,
  /// on a cooldown so a dominant run never spams it.
  bumpMomentum(winner) {
    const dir = winner === 'player' ? 1 : -1;
    this.momentum = clamp(
      this.momentum + dir * (0.16 + Math.min(0.24, this.rallyLen * 0.03)),
      -1, 1
    );
    this.momentumShown = -1; // force the redraw
    if (this.momentumCallT <= 0 && Math.abs(this.momentum) >= MOMENTUM_CALL) {
      this.momentumCallT = MOMENTUM_CD;
      // The booth reads the swing by the surging side's own typed name —
      // falling back to the plain lines it has always called when a field
      // was left empty. The CPU keeps its own line.
      const n1 = selectedName('p1');
      const n2 = selectedName('p2');
      this.momentumCall = this.momentum > 0
        ? (this.twoPlayer
          ? `THEY CAN'T STOP ${n1 || 'P1'}!`
          : `THE CROWD IS BEHIND ${n1 || 'YOU'} NOW!`)
        : (this.twoPlayer
          ? `THEY CAN'T STOP ${n2 || 'P2'}!`
          : 'THE CROWD IS BEHIND THE CPU NOW!');
    }
  }

  /// The momentum bar, redrawn as it moves: it eases back toward centre as
  /// the points trade — momentum is a feeling, not a tally — and fills from
  /// the middle toward whoever owns the run of play, in their colour.
  updateMomentum(dt) {
    if (!this.momentumFill) return;
    this.momentum -= this.momentum * Math.min(1, dt * 0.05);
    const v = Math.round(Math.abs(this.momentum) * 200) / 200;
    if (v === this.momentumShown) return;
    this.momentumShown = v;
    const show = v >= 0.01;
    this.momentumFill.style.opacity = show ? '1' : '0';
    if (!show) return;
    this.momentumFill.style.width = `${Math.max(3, Math.round(v * 83))}px`;
    // The score reads YOU on the left, so the player's surge grows the fill
    // leftward from the centre notch; the far side grows it rightward.
    this.momentumFill.style.transform = this.momentum > 0
      ? 'translateY(1px) translateX(-100%)'
      : 'translateY(1px)';
    this.momentumFill.style.backgroundColor =
      this.momentum > 0 ? this.colPlayer : this.colCpu;
  }

  setPointSide() {
    // Set point: one point from taking the set — at one under its target,
    // and in the tie-break whenever the next point would land the two-point
    // margin.
    const target = this.tieBreak ? TIEBREAK_SCORE : this.setPoints;
    const margin = this.tieBreak ? TIEBREAK_MARGIN : 1;
    for (const s of ['player', 'cpu']) {
      const o = s === 'player' ? 'cpu' : 'player';
      if (this.score[s] + 1 >= target && this.score[s] - this.score[o] >= margin - 1) {
        return s;
      }
    }
    return null;
  }

  /// Match point: the set point that would end the whole match — held by a
  /// side already a set up, or any set point in the cup's single set.
  isMatchPoint() {
    const s = this.setPointSide();
    if (!s) return false;
    return !!this.cupMatch || !!this.dailyMatch || !!this.ladderMatch ||
      this.sets[s] + 1 >= this.setsToWin;
  }

  /// The one-line call from the booth about the breeze, spoken at the top of
  /// each set — the direction given as the players see it from the camera
  /// end. Under a roof there is no breeze to call.
  windCall() {
    if (this.theme.indoor) return 'CALM AIR INDOORS';
    const w = this.wind;
    const strength =
      w.strength < 0.55 ? 'A GENTLE BREEZE' :
      w.strength < 0.8 ? 'A STEADY BREEZE' : 'A STIFF WIND';
    const dir = Math.abs(w.z) > Math.abs(w.x)
      ? (w.z * this.playerSide > 0 ? 'RUNNING OUT TO SEA' : 'BLOWING IN FROM THE SEA')
      : (w.x * this.playerSide > 0 ? 'CROSSING LEFT TO RIGHT' : 'CROSSING RIGHT TO LEFT');
    return `${strength} ${dir}`;
  }

  /// The weather shift between sets: the drawn breeze can freshen a notch,
  /// ease back, or swing a quarter round the compass — kept inside the range
  /// the opening draw plays in. The booth's one-line call about it comes back
  /// for the set-change message, and the change itself is shown at once: the
  /// pennants restream to the new heading, the haze wisps take their new
  /// lanes, and the ball drifts differently from the very next serve. The
  /// indoor arena stays dead calm, and the daily keeps the wind its whole day
  /// drew — nothing here may touch either.
  shiftWeather() {
    if (this.theme.indoor || this.dailyMatch) return null;
    const w = this.wind;
    const roll = Math.random();
    if (roll < 0.36) {
      // Freshen: a stronger breeze out of the same quarter, never beyond the
      // range the opening draw plays in.
      w.strength = clamp(w.strength * (1.35 + Math.random() * 0.35), 0.18, 1.05);
      return 'THE WIND IS PICKING UP!';
    }
    if (roll < 0.72) {
      // Ease: the breeze dies back — on a light day almost to still air.
      w.strength = clamp(w.strength * (0.4 + Math.random() * 0.3), 0.12, 1.05);
      return w.strength < 0.3
        ? 'THE AIR HAS GONE STILL!'
        : 'THE WIND IS DYING DOWN!';
    }
    // Swing: a quarter turn either way round the compass, strength carried.
    const ang = Math.atan2(w.z, w.x) +
      (Math.random() < 0.5 ? -1 : 1) * (Math.PI / 2);
    w.x = Math.cos(ang);
    w.z = Math.sin(ang);
    return 'THE WIND HAS SWUNG ROUND!';
  }

  serveMessage(who) {
    const base = this.serverAth === this.player
      ? 'YOUR SERVE'
      : this.coop && this.serverAth === this.partner ? 'P2 SERVE'
      : this.twoPlayer ? 'P2 SERVE'
      : this.doubles && this.serverAth === this.partner ? 'PARTNER SERVE'
      : 'CPU SERVE';
    return this.setPointSide() ? `SET POINT — ${base}` : base;
  }

  /// The practice close-out: the close button dims the court and raises a
  /// small card with the survival streak — the best rally of this session and
  /// the longest ever kept alive against the CPU, remembered on the career
  /// record — with KEEP PLAYING and LEAVE pills at the bottom. The rally
  /// waits behind the dim until one or the other is chosen.
  showCloseOut() {
    // The live rally counts too: it has been kept alive this long.
    if (this.rallyLen > this.sessionStreak) this.sessionStreak = this.rallyLen;
    recordStreak(this.rallyLen);
    // The session's placement shots bank with the streak: both heat grids
    // are career long, even on the practice court.
    recordHeatShots(this.heat);
    recordRivalHeatShots(this.heatRival);
    this.closeOut = true;
    this.dim = addText('', {
      left: '0',
      right: '0',
      top: '0',
      bottom: '0',
      backgroundColor: 'rgba(6, 12, 22, 0.55)'
    });
    this.closeCard = addText('', {
      left: '50%',
      top: '50%',
      width: 'min(300px, 84vw)',
      height: '300px',
      transform: 'translate(-50%, -50%)',
      borderRadius: '22px',
      backgroundColor: 'rgba(10, 18, 30, 0.85)',
      border: '1px solid rgba(255, 255, 255, 0.14)'
    });
    this.closeCard.appendChild(addText('PRACTICE OVER', {
      left: '0',
      right: '0',
      top: '26px',
      textAlign: 'center',
      fontSize: '20px',
      fontWeight: '800',
      letterSpacing: '2px',
      color: '#ffffff'
    }));
    [
      ['BEST STREAK THIS SESSION', `${this.sessionStreak}`],
      ['ALL-TIME BEST STREAK', `${careerStats().bestStreak}`]
    ].forEach(([label, value], i) => {
      const y = 84 + i * 62;
      this.closeCard.appendChild(addText(label, {
        left: '0',
        right: '0',
        top: `${y}px`,
        textAlign: 'center',
        fontSize: '11px',
        fontWeight: '700',
        letterSpacing: '2px',
        color: 'rgba(255,255,255,0.6)'
      }));
      this.closeCard.appendChild(addText(value, {
        left: '0',
        right: '0',
        top: `${y + 15}px`,
        textAlign: 'center',
        fontSize: '27px',
        fontWeight: '800',
        color: '#ffd24a'
      }));
    });
    this.closeResumeBtn = addButton({
      label: 'Keep playing',
      onPress: () => this.endCloseOut(),
      style: {
        position: 'absolute',
        width: '132px',
        height: '48px',
        left: 'calc(50% - 138px)',
        bottom: 'calc(50% - 118px)',
        borderRadius: '999px',
        backgroundColor: '#1d6fb8',
        color: '#ffffff',
        fontSize: '13px',
        fontWeight: '700',
        letterSpacing: '1px'
      }
    });
    this.closeResumeBtn.textContent = 'KEEP PLAYING';
    this.closeLeaveBtn = addButton({
      label: 'Leave practice',
      onPress: () => this.game.start(BootScene),
      style: {
        position: 'absolute',
        width: '108px',
        height: '48px',
        left: 'calc(50% + 18px)',
        bottom: 'calc(50% - 118px)',
        borderRadius: '999px',
        backgroundColor: 'rgba(10, 18, 30, 0.4)',
        border: '1.5px solid rgba(255, 255, 255, 0.45)',
        color: '#ffffff',
        fontSize: '13px',
        fontWeight: '700',
        letterSpacing: '1px'
      }
    });
    this.closeLeaveBtn.textContent = 'LEAVE';
    haptic('tick');
  }

  /// Back to the rally: the close-out lifts and play resumes where it paused.
  endCloseOut() {
    this.closeOut = false;
    this.dim?.remove();
    this.closeCard?.remove();
    this.closeResumeBtn?.remove();
    this.closeLeaveBtn?.remove();
    this.dim = null;
    this.closeCard = null;
    this.closeResumeBtn = null;
    this.closeLeaveBtn = null;
    haptic('tick');
  }

  // ---------------------------------------------------------------- pause

  /// The pause: everything stops exactly where it is — the serve countdown
  /// mid-count, the toss hanging in the air, slow motion frozen — and the
  /// crowd murmur fades out under the dim. The card offers resume, a fresh
  /// match of the same mode, or the title screen.
  togglePause() {
    if (this.paused || this.closeOut || this.state === 'over') return;
    this.paused = true;
    // The murmur fades on its own — the audio graph keeps gliding toward
    // zero even while the simulation sleeps. The level is invalidated so the
    // first drama update after the resume sends it again.
    this.murmurLevel = -1;
    murmur(0);
    this.pauseDim = addText('', {
      left: '0',
      right: '0',
      top: '0',
      bottom: '0',
      backgroundColor: 'rgba(6, 12, 22, 0.55)'
    });
    this.pauseCard = addText('', {
      left: '50%',
      top: '50%',
      width: 'min(300px, 84vw)',
      height: '380px',
      transform: 'translate(-50%, -50%)',
      borderRadius: '22px',
      backgroundColor: 'rgba(10, 18, 30, 0.85)',
      border: '1px solid rgba(255, 255, 255, 0.14)'
    });
    this.pauseCard.appendChild(addText('PAUSED', {
      left: '0',
      right: '0',
      top: '30px',
      textAlign: 'center',
      fontSize: '20px',
      fontWeight: '800',
      letterSpacing: '2px',
      color: '#ffffff'
    }));
    this.pauseQuitBtn = addButton({
      label: 'Quit to menu',
      onPress: () => {
        // A daily walked away from has had its one attempt: it banks as a
        // loss, so the day cannot be replayed by leaving. A ladder rung
        // abandoned likewise counts as the loss it usually was — the rank
        // is on the line the whole match.
        if (this.dailyMatch) finishDaily(false);
        else if (this.ladderMatch) finishLadder(false);
        this.game.start(BootScene);
      },
      style: {
        position: 'absolute',
        width: '220px',
        height: '48px',
        left: 'calc(50% - 110px)',
        bottom: 'calc(50% - 66px)',
        borderRadius: '999px',
        backgroundColor: 'rgba(10, 18, 30, 0.4)',
        border: '1.5px solid rgba(255, 255, 255, 0.45)',
        color: '#ffffff',
        fontSize: '13px',
        fontWeight: '700',
        letterSpacing: '1px'
      }
    });
    this.pauseQuitBtn.textContent = 'QUIT TO MENU';
    // The daily has no rematch to offer: its one attempt is the match, so
    // the restart pill stays off the card and the resume moves up.
    if (!this.dailyMatch) {
      this.pauseRestartBtn = addButton({
        label: 'Restart match',
        onPress: () => this.game.start(this.constructor),
        style: {
          position: 'absolute',
          width: '220px',
          height: '48px',
          left: 'calc(50% - 110px)',
          bottom: 'calc(50% - 126px)',
          borderRadius: '999px',
          backgroundColor: 'rgba(10, 18, 30, 0.4)',
          border: '1.5px solid rgba(255, 255, 255, 0.45)',
          color: '#ffffff',
          fontSize: '13px',
          fontWeight: '700',
          letterSpacing: '1px'
        }
      });
      this.pauseRestartBtn.textContent = 'RESTART MATCH';
    }
    this.pauseResumeBtn = addButton({
      label: 'Resume',
      onPress: () => this.endPause(),
      style: {
        position: 'absolute',
        width: '220px',
        height: '48px',
        left: 'calc(50% - 110px)',
        bottom: this.dailyMatch ? 'calc(50% - 126px)' : 'calc(50% - 186px)',
        borderRadius: '999px',
        backgroundColor: '#1d6fb8',
        color: '#ffffff',
        fontSize: '13px',
        fontWeight: '700',
        letterSpacing: '1px'
      }
    });
    this.pauseResumeBtn.textContent = 'RESUME';
    haptic('tick');
  }

  /// Back to the match: the overlay lifts and play picks up on the exact
  /// frame it froze on — whatever the state was, it still is.
  endPause() {
    this.paused = false;
    this.pauseDim?.remove();
    this.pauseCard?.remove();
    this.pauseQuitBtn?.remove();
    this.pauseRestartBtn?.remove();
    this.pauseResumeBtn?.remove();
    this.pauseDim = null;
    this.pauseCard = null;
    this.pauseQuitBtn = null;
    this.pauseRestartBtn = null;
    this.pauseResumeBtn = null;
    haptic('tick');
  }

  /// The timeout: spent from the pill beside the pause, once a set. The
  /// match freezes for a beat — held exactly where it is while the murmur
  /// settles and the booth's call holds the strip — then play picks up on
  /// the frame it froze on. The run of play resets to even with it: the
  /// momentum bar empties, the CPU's run of straight points is forgotten
  /// and the adaptive bias melts back to its chosen level, so a runaway
  /// streak can be stopped once a set.
  callTimeout() {
    if (this.timeoutsLeft <= 0 || this.paused || this.closeOut ||
        this.timeoutT > 0 || this.state === 'over' || this.flyT > 0) return;
    // A replay or a review owns the frame: the timeout waits for real play.
    if (this.state === 'replay' || this.state === 'challenge') return;
    this.timeoutsLeft--;
    this.refreshTimeoutPill();
    this.timeoutT = 2.6;
    // The arena settles: the murmur glides down on its own and stays quiet
    // for the freeze — the drama bed re-sends whatever it reads on resume.
    this.murmurLevel = -1;
    murmur(0);
    this.setMsg('TIMEOUT!');
    playWhistle();
    haptic('tick');
    // The run of play back to even: the momentum bar empties, the CPU's
    // streak counter starts over, and an existing bias melts away.
    this.momentum = 0;
    this.momentumShown = -1;
    this.momentumCall = null;
    this.runWho = null;
    this.runLen = 0;
    if (this.adaptOn && this.adapt !== 0) {
      this.adapt = 0;
      this.applyAdapt();
      this.refreshAdapt();
    }
  }

  /// The timeout pill: bright while the set's timeout is in hand, dimmed
  /// once it is spent — refreshed with each set like the challenge pill.
  refreshTimeoutPill() {
    if (!this.timeoutBtn) return;
    this.timeoutBtn.textContent = `TIMEOUT · ${this.timeoutsLeft}`;
    this.timeoutBtn.style.opacity = this.timeoutsLeft > 0 ? '0.95' : '0.35';
  }

  /// The booth reads the result aloud as the recap comes up: the winner's
  /// name, the set score and one standout line taken from the match's own
  /// numbers — the aces, the longest rally or the shot of the match. It rides
  /// the same voice as the arena's name call, gates on the sound switch and
  /// stays quiet where the host has no speech engine.
  speakMatchSummary() {
    const won = this.matchWinner === 'player';
    const winner = won
      ? (playerName('p1') || 'YOU')
      : this.twoPlayer
        ? (playerName('p2') || 'P2')
        : (this.cpuStats && this.cpuStats.name
          ? this.cpuStats.name.toUpperCase() : 'THE CPU');
    const score = this.setScores.length
      ? this.setScores.map((s) => s.split('–').join(' to ')).join(', ')
      : `${this.score.player} to ${this.score.cpu}`;
    const aces = won ? this.stats.aces.player : this.stats.aces.cpu;
    let standout = '';
    if (aces >= 2) {
      standout = `${aces} aces in the match.`;
    } else if (this.stats.longestRally >= 8) {
      standout = `A longest rally of ${this.stats.longestRally} touches.`;
    } else if (this.shot && this.shot.line) {
      standout = `${this.shot.line}.`;
    }
    const line = `${winner} wins, ${score}. ${standout}`.replace(/\s+/g, ' ').trim();
    speakLine(line);
  }

  /// The match recap: the court dims, and a dark translucent card rises over
  /// it with the result headline large at the top, the stat rows beneath —
  /// small labels over big numbers — and two pills at the bottom: Rematch
  /// filled, Menu outlined. The celebration keeps playing behind the dim.
  showRecap(headline) {
    this.recapShown = true;
    this.setMsg('');
    this.hideTeamTalk();
    // The booth reads the result aloud before the card settles.
    this.speakMatchSummary();
    // The set-by-set strip belongs to the live match: the recap owns the
    // screen from here, so the state machine's own 'over' read hides it.
    this.refreshSetStrip();
    // The shot of the match, picked at the final point: a gold card between
    // the stats and the buttons when something qualified — the card grows
    // to make room for it.
    const shot = this.shot;

    this.dim = addText('', {
      left: '0',
      right: '0',
      top: '0',
      bottom: '0',
      backgroundColor: 'rgba(6, 12, 22, 0.55)'
    });
    // Everything the recap shows — the card and its pills — lives in one
    // full-screen layer, so a panel shorter than the card (a turned
    // landscape stage is) can scale the whole thing down together, pills
    // included.
    this.recapWrap = addText('', {
      left: '0',
      right: '0',
      top: '0',
      bottom: '0'
    });

    const card = addText('', {
      left: '50%',
      top: '50%',
      width: 'min(320px, 86vw)',
      height: shot ? '710px' : '600px',
      transform: 'translate(-50%, -50%)',
      borderRadius: '22px',
      backgroundColor: 'rgba(10, 18, 30, 0.85)',
      border: '1px solid rgba(255, 255, 255, 0.14)'
    });
    // The card is held on the scene: the shot-of-the-match replay steps it
    // aside for the broadcast and brings it back when the replay is done.
    this.recapCard = card;
    this.recapWrap.appendChild(card);
    // A panel shorter than the card — a turned landscape stage is — scales
    // the whole layer down so the pills stay on screen. resize() re-applies.
    this.fitRecap();

    card.appendChild(addText(headline, {
      left: '10px',
      right: '10px',
      top: '28px',
      textAlign: 'center',
      fontSize: '21px',
      fontWeight: '800',
      letterSpacing: '0.5px',
      color: '#ffffff'
    }));

    // The set scores list every set of the match — up to five in the
    // marathon — so that line steps down a size to stay on one line. On a
    // loss the rows step a touch closer together as well, making room under
    // the stats for the coach's line; a win keeps the card exactly as it is.
    const lost = this.matchWinner !== 'player';
    const scoreSize = this.setScores.length > 3 ? '13px'
      : this.setScores.length > 2 ? '17px' : '27px';
    const rows = [
      ['SETS', this.setScores.join('  ·  '), scoreSize],
      ['POINTS WON', `${this.stats.points.player} – ${this.stats.points.cpu}`],
      ['LONGEST RALLY', `${this.stats.longestRally}`],
      ['SPIKES HIT', `${this.stats.spikes.player} – ${this.stats.spikes.cpu}`],
      ['ACES', `${this.stats.aces.player} – ${this.stats.aces.cpu}`],
      ['BLOCKS', `${this.stats.blocks.player} – ${this.stats.blocks.cpu}`],
      // The fastest rally touch beside the aces and blocks: the pace
      // readout's own row, reading '—' until a touch has set it.
      ['FASTEST TOUCH',
        this.stats.fastestTouch ? `${this.stats.fastestTouch} KM/H` : '—'],
      ['CLUTCH', `${this.stats.clutch.won} – ${this.stats.clutch.lost}`],
      ['BEST RUN ON SERVE', `${this.stats.serveRun.best}`],
      ['COMEBACKS', `${this.stats.comebacks}`]
    ];
    // The blitz recap: no sets to read — the running score and the pace of
    // the match, points per minute, take the SETS and COMEBACKS rows.
    if (this.blitz) {
      const perMin = (n) =>
        (n / Math.max(0.01, this.clock / 60)).toFixed(1);
      rows[0] = ['BLITZ SCORE', `${this.score.player} – ${this.score.cpu}`];
      rows[9] = ['POINTS PER MINUTE',
        `${perMin(this.stats.points.player)} – ${perMin(this.stats.points.cpu)}`];
    }
    rows.forEach(([label, value, size], i) => {
      const y = 88 + i * (lost ? 40 : 46);
      card.appendChild(addText(label, {
        left: '0',
        right: '0',
        top: `${y}px`,
        textAlign: 'center',
        fontSize: '11px',
        fontWeight: '700',
        letterSpacing: '2px',
        color: 'rgba(255,255,255,0.6)'
      }));
      card.appendChild(addText(value, {
        left: '0',
        right: '0',
        top: `${y + 15}px`,
        textAlign: 'center',
        fontSize: size || '27px',
        fontWeight: '800',
        color: '#ffffff'
      }));
    });

    // The shot of the match: a gold card naming the standout moment in one
    // line — the fastest serve, the longest rally or a super strike,
    // whichever measured biggest. It only appears when something qualified.
    if (shot) {
      const gold = addText('', {
        left: '14px',
        right: '14px',
        top: `${lost ? 500 : 556}px`,
        height: this.shotRecording() ? '66px' : '58px',
        borderRadius: '12px',
        backgroundColor: 'rgba(255, 210, 74, 0.14)',
        border: '1px solid rgba(255, 210, 74, 0.55)'
      });
      card.appendChild(gold);
      gold.appendChild(addText('SHOT OF THE MATCH', {
        left: '0',
        right: '0',
        top: '9px',
        textAlign: 'center',
        fontSize: '9px',
        fontWeight: '800',
        letterSpacing: '2px',
        color: '#ffd24a'
      }));
      gold.appendChild(addText(shot.line, {
        left: '8px',
        right: '8px',
        top: '27px',
        textAlign: 'center',
        fontSize: '14px',
        fontWeight: '800',
        color: '#ffffff',
        whiteSpace: 'nowrap'
      }));
      // The replay pill: the moment plays back over the dimmed court from
      // the picked replay angle — shown only where that rally actually
      // banked its recording during the match.
      if (this.shotRecording()) {
        this.shotBtn = addButton({
          label: 'Replay the shot of the match',
          onPress: () => this.playShotReplay(),
          style: {
            position: 'absolute',
            width: '104px',
            height: '16px',
            left: 'calc(50% - 52px)',
            top: `calc(50% + ${lost ? 189 : 245}px)`,
            borderRadius: '999px',
            backgroundColor: 'rgba(255, 210, 74, 0.92)',
            color: '#231503',
            fontSize: '9px',
            fontWeight: '800',
            letterSpacing: '2px'
          }
        });
        this.shotBtn.textContent = 'REPLAY';
      }
    }

    // The post-loss coaching tip: one contextual line under the stats —
    // aces conceded point at serve timing, spikes conceded at blocking and
    // positioning, long rallies lost at shot placement, and a plain line
    // when nothing stands out. It rotates across losses so repeat losses
    // are taught something new, and a win never asks for it.
    if (lost) {
      card.appendChild(addText('COACH', {
        left: '0',
        right: '0',
        top: shot ? '576px' : '504px',
        textAlign: 'center',
        fontSize: '11px',
        fontWeight: '700',
        letterSpacing: '2px',
        color: '#ffd24a'
      }));
      card.appendChild(addText(this.coachingTip(), {
        left: '14px',
        right: '14px',
        top: shot ? '592px' : '520px',
        textAlign: 'center',
        fontSize: '12px',
        fontWeight: '600',
        lineHeight: '1.35',
        color: 'rgba(255,255,255,0.9)'
      }));
    }

    this.rematchBtn = addButton({
      label: 'Rematch',
      onPress: () => this.game.start(this.constructor),
      style: {
        position: 'absolute',
        width: '128px',
        height: '50px',
        left: 'calc(50% - 134px)',
        bottom: shot ? 'calc(50% - 333px)' : 'calc(50% - 324px)',
        borderRadius: '999px',
        backgroundColor: '#1d6fb8',
        color: '#ffffff',
        fontSize: '14px',
        fontWeight: '700',
        letterSpacing: '1px'
      }
    });
    this.rematchBtn.textContent = 'REMATCH';
    this.recapWrap.appendChild(this.rematchBtn);

    this.menuBtn = addButton({
      label: 'Menu',
      onPress: () => this.game.start(BootScene),
      style: {
        position: 'absolute',
        width: '128px',
        height: '50px',
        left: 'calc(50% + 6px)',
        bottom: shot ? 'calc(50% - 333px)' : 'calc(50% - 324px)',
        borderRadius: '999px',
        backgroundColor: 'rgba(10, 18, 30, 0.4)',
        border: '1.5px solid rgba(255, 255, 255, 0.45)',
        color: '#ffffff',
        fontSize: '14px',
        fontWeight: '700',
        letterSpacing: '1px'
      }
    });
    this.menuBtn.textContent = 'MENU';
    this.recapWrap.appendChild(this.menuBtn);
  }

  /// The series settled at the end of each of its matches: the score moves
  /// and the pill reads the running MATCHES tally; the second win or loss
  /// settles the whole series and returns the recap headline override — a
  /// SERIES WON headline when the player takes it (the card follows instead
  /// of the recap), a CPU TAKES THE SERIES headline when it drops, and null
  /// while the series runs on.
  settleSeries(winner) {
    if (!this.seriesMatch) return null;
    const res = recordSeriesMatch(winner === 'player');
    if (this.seriesPill) {
      this.seriesPill.textContent = `MATCHES ${res.wins}–${res.losses}`;
      this.seriesPill.style.color = '#ffd24a';
    }
    if (res.res === 'won') {
      this.seriesWon = true;
      this.seriesFinal = { wins: res.wins, losses: res.losses };
      return 'SERIES WON!';
    }
    if (res.res === 'lost') {
      return `CPU TAKES THE SERIES ${res.losses}–${res.wins}`;
    }
    return null;
  }

  /// The series taken: a brief gold card over the dimmed court — the
  /// fanfare already played at the final point, the final MATCHES score
  /// beneath the headline — dismissed by its DONE pill or on its own after
  /// a few seconds, either way back at the title.
  showSeriesCard() {
    this.recapShown = true;
    this.setMsg('');
    this.dim = addText('', {
      left: '0', right: '0', top: '0', bottom: '0',
      backgroundColor: 'rgba(6, 12, 22, 0.55)'
    });
    this.seriesCard = addText('', {
      left: '50%', top: '50%', width: 'min(300px, 84vw)', height: '240px',
      transform: 'translate(-50%, -50%)', borderRadius: '22px',
      backgroundColor: 'rgba(10, 18, 30, 0.85)',
      border: '1px solid rgba(255, 255, 255, 0.14)'
    });
    this.seriesCard.appendChild(addText('SERIES WON!', {
      left: '0', right: '0', top: '34px', textAlign: 'center',
      fontSize: '22px', fontWeight: '800', letterSpacing: '2px', color: '#ffd24a'
    }));
    this.seriesCard.appendChild(addText(
      `MATCHES ${this.seriesFinal.wins}–${this.seriesFinal.losses}`, {
        left: '0', right: '0', top: '84px', textAlign: 'center',
        fontSize: '27px', fontWeight: '800', color: '#ffffff'
      }));
    this.seriesDoneBtn = addButton({
      label: 'Done',
      onPress: () => this.game.start(BootScene),
      style: {
        position: 'absolute', width: '128px', height: '48px',
        left: 'calc(50% - 64px)', bottom: 'calc(50% - 90px)',
        borderRadius: '999px',
        backgroundColor: 'rgba(10, 18, 30, 0.4)',
        border: '1.5px solid rgba(255, 255, 255, 0.45)',
        color: '#ffffff', fontSize: '13px', fontWeight: '700', letterSpacing: '1px'
      }
    });
    this.seriesDoneBtn.textContent = 'DONE';
    this.seriesCardT = 5;
    haptic('win');
  }

  /// The shot of the match: the standout moment, whichever measured biggest
  /// — a super strike a flat mark of its own, the fastest serve scored by
  /// its km/h, the longest rally by ten points a touch. Anything under its
  /// qualifying bar earns nothing, so the card only appears when a moment
  /// deserves it. Each moment carries the key that finds its rally's banked
  /// recording — the super strike's tag, the serve's pace or the rally's
  /// touch count — alongside the line the card reads.
  pickShotOfMatch() {
    const name = (id) =>
      id === 'player' ? (playerName('p1') || 'YOU')
      : id === 'partner' ? (playerName('p2') || 'P2')
      : id === 'cpu2' ? this.cpu2Stats.name.toUpperCase()
      : id === 'cpu' && this.twoPlayer ? (playerName('p2') || 'P2')
      : this.cpuStats.name.toUpperCase();
    const shots = [];
    if (this.superMoment) {
      shots.push({
        score: 105, kind: 'super',
        line: `${name(this.superMoment.id)}'S SUPER STRIKE`
      });
    }
    if (this.bestServe && this.bestServe.kmh >= 110) {
      shots.push({
        score: this.bestServe.kmh,
        kind: 'serve',
        value: this.bestServe.kmh,
        line: `${name(this.bestServe.id)}'S ${this.bestServe.kmh} KM/H SERVE`
      });
    }
    if (this.stats.longestRally >= 8) {
      shots.push({
        score: this.stats.longestRally * 10,
        kind: 'rally',
        value: this.stats.longestRally,
        line: `A ${this.stats.longestRally}-TOUCH RALLY`
      });
    }
    shots.sort((a, b) => b.score - a.score);
    return shots[0] || null;
  }

  /// The banked recording behind the gold moment: the pool entry the picked
  /// key points at — the rally the super strike closed, the fastest serve's
  /// own rally by its pace, or the longest rally by its touch count. Null
  /// when the moment's rally never banked a recording — the pill only rides
  /// the card where one did.
  shotRecording() {
    const s = this.shot;
    if (!s || !s.kind) return null;
    const pool = this.shotPool;
    for (let i = pool.length - 1; i >= 0; i--) {
      const e = pool[i];
      if (s.kind === 'super' ? e.super
        : s.kind === 'serve' ? e.serveKmh === s.value
        : e.touches === s.value) {
        return e;
      }
    }
    return null;
  }

  /// The gold card's REPLAY pill: the moment plays back over the dimmed
  /// court from the picked replay angle — the card steps aside for the
  /// broadcast and returns the moment the replay is done with it.
  playShotReplay() {
    if (this.state === 'replay') return;
    const e = this.shotRecording();
    if (!e) return;
    this.shotFrames = e.frames;
    this.recapCard.style.display = 'none';
    this.rematchBtn.style.display = 'none';
    this.menuBtn.style.display = 'none';
    if (this.shotBtn) this.shotBtn.style.display = 'none';
    this.beginShotReplay();
  }

  /// The coaching tip the recap reads out after a loss: one line, picked
  /// from the match's own numbers — aces conceded point at serve timing,
  /// spikes conceded at blocking and positioning, long rallies lost at shot
  /// placement — and a plain generic line when nothing stands out. Each
  /// category holds a few lines, and the pick rotates on the career loss
  /// count, so repeat losses hear the next line instead of the same one.
  coachingTip() {
    const s = this.stats;
    const pick = (lines) =>
      lines[(careerLosses() - 1 + lines.length) % lines.length];
    if (s.aces.cpu >= 2) {
      return pick([
        'TIME THE SERVE RECEIVE — WATCH THE TOSS AND GO EARLY',
        'THEIR ACES STUNG — STAND DEEPER AND JUMP THE SERVE SOONER'
      ]);
    }
    if (s.spikes.cpu - s.spikes.player >= 3) {
      return pick([
        'THEY SPIKED FREELY — COVER THE NET AND BLOCK EARLY',
        'TOO MANY SPIKES GOT THROUGH — HOLD YOUR SPOT AT THE TAPE'
      ]);
    }
    if (s.longestRally >= 7) {
      return pick([
        'LONG RALLIES WENT THEIR WAY — PLACE YOUR SHOTS TO THE CORNERS',
        'THE LONG ONES DRAGGED — MIX LOB AND DRIVE TO BREAK THE PATTERN'
      ]);
    }
    return pick([
      'KEEP THE BALL DEEP AND MAKE THEM MOVE',
      'SAVE THE CHARGE FOR THE POINT THAT MATTERS',
      'WATCH THEIR FEET — THE LOB BEATS A NET-HUGGER'
    ]);
  }

  setMsg(text) {
    this.msgText.textContent = text;
  }

  // ---------------------------------------------------------------- input

  bindInput() {
    // One drag zone per player: the left of the screen drives the near
    // athlete, and in a shared-screen match the right drives the second one —
    // the far athlete in two-player, the near partner in co-op doubles. With
    // one human on the court there is no second zone at all: a drag anywhere
    // on the screen moves the athlete, so no part of the panel is dead.
    const split = this.twoPlayer || this.coop ? 0.5 : 1;
    // Only a press that lands on an actual control belongs to the interface:
    // every score line, pill and readout is a plain element layered over the
    // court, and a drag that starts on top of one has to steer the athlete all
    // the same. The press is caught on window in the capture phase, so no
    // overlay of any size can swallow the drag before the court sees it.
    const onControl = (el) => {
      for (let n = el; n && n !== document.body; n = n.parentElement) {
        const tag = n.tagName;
        if (tag === 'BUTTON' || tag === 'INPUT' || tag === 'SELECT' ||
            tag === 'TEXTAREA') return true;
      }
      return false;
    };
    // A press is caught in the capture phase on window, so no overlay can
    // swallow it; the touch stream below feeds the same map as a fallback for
    // hosts that never deliver pointer moves.
    this.onDown = (e) => {
      if (onControl(e.target)) return;
      // The end-of-set huddle skips with a tap, like the pre-match sweep.
      if (this.huddle) {
        this.finishHuddle();
        return;
      }
      // The victory lap skips the same way.
      if (this.victoryLap) {
        this.finishVictoryLap();
        return;
      }
      // The pre-match flyover is skippable: any tap on the court cuts it
      // short, and the camera eases home the short way.
      if (this.flyT > 0) {
        this.flyT = Math.min(this.flyT, 0.3);
        return;
      }
      // The tap lands in viewport coordinates; the game's own space — turned
      // when the game is presenting landscape — is what the split reads.
      const at = toLocal(e.clientX, e.clientY);
      // The stage's own width, with the viewport behind it as a fallback so a
      // drag is never thrown away because the panel had not measured yet.
      const width = this.viewW || window.innerWidth || 1;
      const side = at.x < width * split ? 1 : 2;
      if (side === 2 && !this.twoPlayer && !this.coop) return;
      // A side holds one drag at a time, but a new press always takes it
      // over — even when the host reuses the same pointer id for it, as iOS
      // does for the primary touch. A missed pointerup must never leave an
      // athlete pinned against a boundary with no press able to free him.
      for (const [id, p] of this.pointers) {
        if (p.side !== side) continue;
        this.pointers.delete(id);
        const stale = p.side === 2 ? this.input2 : this.input;
        stale.x = 0;
        stale.z = 0;
        stale.tx = 0;
        stale.tz = 0;
      }
      this.pointers.set(e.pointerId, { side, rx: e.clientX, ry: e.clientY });
      this.hideMoveHint();
    };
    // The drag read as a steering vector: a soft dead zone around the anchor
    // so a resting thumb never drifts the athlete, full pace at the ring's
    // edge, and the distance in between carried through as pace.
    const steer = (input, d) => {
      const max = 60;
      const dead = 5;
      const len = Math.hypot(d.x, d.y);
      const mag = len <= dead ? 0 : Math.min(1, (len - dead) / (max - dead));
      input.tx = len > 0 ? (d.x / len) * mag : 0;
      input.tz = len > 0 ? (d.y / len) * mag : 0;
    };
    this.onMove = (e) => {
      const p = this.pointers.get(e.pointerId);
      if (!p) return;
      // The drag's delta turns with the game: a thumb sliding toward the net
      // on the held phone moves the athlete toward the net however the frame
      // is being presented.
      steer(p.side === 2 ? this.input2 : this.input,
        toLocalDelta(e.clientX - p.rx, e.clientY - p.ry));
    };
    this.onUp = (e) => {
      const p = this.pointers.get(e.pointerId);
      if (!this.pointers.delete(e.pointerId)) return;
      this.releaseSide(p && p.side);
    };
    // The touch fallback: the same drag, driven by the finger itself, keyed by
    // the touch's own identifier. A host that delivers pointer events as well
    // hands the drag to them — the one-drag-per-side guard keeps a single
    // finger from ever being counted twice.
    const touchId = (t) => 900000 + t.identifier;
    this.onTouchDown = (e) => {
      if (onControl(e.target)) return;
      if (this.huddle) {
        this.finishHuddle();
        return;
      }
      // The victory lap skips the same way.
      if (this.victoryLap) {
        this.finishVictoryLap();
        return;
      }
      const t = e.changedTouches[0];
      if (!t) return;
      if (this.flyT > 0) {
        this.flyT = Math.min(this.flyT, 0.3);
        return;
      }
      const at = toLocal(t.clientX, t.clientY);
      const width = this.viewW || window.innerWidth || 1;
      const side = at.x < width * split ? 1 : 2;
      if (side === 2 && !this.twoPlayer && !this.coop) return;
      for (const [id, p] of this.pointers) {
        if (p.side !== side) continue;
        this.pointers.delete(id);
        const stale = p.side === 2 ? this.input2 : this.input;
        stale.x = 0;
        stale.z = 0;
        stale.tx = 0;
        stale.tz = 0;
      }
      this.pointers.set(touchId(t), { side, rx: t.clientX, ry: t.clientY });
      this.hideMoveHint();
    };
    this.onTouchMove = (e) => {
      for (const t of e.changedTouches) {
        const p = this.pointers.get(touchId(t));
        if (!p) continue;
        steer(p.side === 2 ? this.input2 : this.input,
          toLocalDelta(t.clientX - p.rx, t.clientY - p.ry));
      }
    };
    this.onTouchUp = (e) => {
      for (const t of e.changedTouches) {
        const id = touchId(t);
        const p = this.pointers.get(id);
        if (!this.pointers.delete(id)) continue;
        this.releaseSide(p && p.side);
      }
    };
    // A drag is over only once no press is left on that side: the pointer and
    // touch streams both feed the same map, so a host that reports a touch
    // both ways can never strand an athlete mid-stride.
    this.releaseSide = (side) => {
      if (side !== 1 && side !== 2) return;
      for (const p of this.pointers.values()) {
        if (p.side === side) return;
      }
      const input = side === 2 ? this.input2 : this.input;
      input.x = 0;
      input.z = 0;
      input.tx = 0;
      input.tz = 0;
    };
    // A press the host never ends — the page going away — must not leave an
    // athlete dragging at thin air.
    this.onReleaseAll = () => {
      this.pointers.clear();
      for (const input of [this.input, this.input2]) {
        input.x = 0;
        input.z = 0;
        input.tx = 0;
        input.tz = 0;
      }
    };
    document.addEventListener('visibilitychange', this.onReleaseAll);
    window.addEventListener('pointerdown', this.onDown, true);
    window.addEventListener('pointermove', this.onMove);
    window.addEventListener('pointerup', this.onUp);
    window.addEventListener('pointercancel', this.onUp);
    // A host that delivers no pointer events at all still delivers touches:
    // the drag falls back to them, so the athletes move either way.
    window.addEventListener('touchstart', this.onTouchDown, { passive: false });
    window.addEventListener('touchmove', this.onTouchMove, { passive: false });
    window.addEventListener('touchend', this.onTouchUp);
    window.addEventListener('touchcancel', this.onTouchUp);
  }

  /// The movement caption has done its job the moment a drag lands: it fades
  /// out and is gone.
  hideMoveHint() {
    if (!this.moveHint) return;
    const el = this.moveHint;
    this.moveHint = null;
    el.style.opacity = '0';
    setTimeout(() => el.remove(), 450);
  }

  resize(width, height) {
    // The radar pill projects the server into this space.
    this.viewW = width;
    this.viewH = height;
    const aspect = width / height;
    if (aspect < 0.75) {
      this.camBase.y = 4.6;
      this.camBase.z = 10.6;
    } else if (aspect < 1.25) {
      this.camBase.y = 4.0;
      this.camBase.z = 9.2;
    } else {
      this.camBase.y = 3.4;
      this.camBase.z = 7.8;
    }
    // The recap scales with the panel: a turned landscape stage is shorter
    // than its card, and the pills have to stay on screen.
    this.fitRecap();
  }

  /// Scales the recap layer down when the panel is shorter than the card —
  /// a turned landscape stage is — keeping it centred and its pills
  /// reachable. Everything the recap shows shares one full-screen layer, so
  /// the card and its pills shrink together.
  fitRecap() {
    if (!this.recapWrap) return;
    const scale = Math.min(1, (this.viewH - 16) /
      (this.shot ? 710 : 600));
    this.recapWrap.style.transformOrigin = '50% 50%';
    this.recapWrap.style.transform =
      scale < 0.99 ? `scale(${scale.toFixed(3)})` : '';
  }

  dispose() {
    this.hideTeamTalk();
    clearHUD();
    // The murmur loop outlives the scene otherwise — fade it out.
    murmur(0);
    // The target ring owns its own geometry and materials.
    if (this.targetGroup) {
      this.targetGroup.traverse((o) => {
        if (o.geometry) o.geometry.dispose();
        if (o.material) o.material.dispose();
      });
    }
    // The ball machine likewise.
    if (this.machineGroup) {
      this.machineGroup.traverse((o) => {
        if (o.geometry) o.geometry.dispose();
        if (o.material) o.material.dispose();
      });
    }
    // The match-point spotlight: the light, the beam cone and the pool.
    if (this.spotGroup) {
      this.spotGroup.traverse((o) => {
        if (o.geometry) o.geometry.dispose();
        if (o.material) o.material.dispose();
      });
    }
    // The milestone banner: its painted cloth texture and material are its own.
    if (this.bannerMat) {
      this.bannerMat.map?.dispose();
      this.bannerMat.dispose();
      this.bannerMat = null;
    }
    // The stands and the crowd: three instanced meshes with their own
    // geometry, materials and per-instance colour buffers.
    if (this.crowdGroup) {
      this.crowdGroup.traverse((o) => {
        if (o.geometry) o.geometry.dispose();
        if (o.material) o.material.dispose();
        if (o.instanceColor) o.instanceColor.dispose?.();
      });
    }
    // The landing marks: one shared geometry, one material a disc.
    if (this.marks) {
      for (const m of this.marks) m.material.dispose();
      this.marks[0].geometry.dispose();
      this.marks = null;
    }
    // The sand spray: one instanced mesh with its own grain quads.
    if (this.sprayMesh) {
      this.sprayMesh.geometry.dispose();
      this.sprayMesh.material.dispose();
      this.sprayMesh.dispose();
      this.sprayMesh = null;
    }
    // The mirror world's materials are its own; its geometry is shared with
    // the real court and stays with it.
    if (this.mirrorMats) {
      for (const m of this.mirrorMats) m.dispose();
      this.mirrorMats = null;
    }
    // The environment panorama is held by the scene itself, not a mesh: drop
    // it here so rematches don't pile up dead sky textures on the GPU.
    if (this.root.environment) {
      this.root.environment.dispose();
      this.root.environment = null;
    }
    document.removeEventListener('visibilitychange', this.onReleaseAll);
    window.removeEventListener('pointerdown', this.onDown, true);
    window.removeEventListener('pointermove', this.onMove);
    window.removeEventListener('pointerup', this.onUp);
    window.removeEventListener('pointercancel', this.onUp);
    window.removeEventListener('touchstart', this.onTouchDown);
    window.removeEventListener('touchmove', this.onTouchMove);
    window.removeEventListener('touchend', this.onTouchUp);
    window.removeEventListener('touchcancel', this.onTouchUp);
  }
}
